"""Original teaching notes. Reported measurements retain their paper version and protocol.

Worked examples and suggested experiments are editorial, not author experiments.
"""
NOTES = {}

def add(key, **note):
    NOTES[key] = note

add('saycan', version='v2',
 takeaway='先问“该做什么”，再问“现在做得到吗”：两种分数共同选择下一项技能。',
 result='101 条真实机器人指令：实验厨房计划成功 84%，执行成功 74%；真实厨房执行降至 60%。',
 why='如果你已经会写 tool-calling agent，SayCan 最值得学的是工具选择的第二个条件。语言模型知道清理污渍需要海绵，却不知道机器人是否够得到海绵。论文把任务相关性和当前状态下的可执行性分开估计，让物理能力直接影响高层决策。',
 scene='指令是“我把饮料洒了，能帮我吗？”。机器人此刻停在空地上，海绵在远处的桌上。只按语义排序的话，“拿起海绵”最该做、分数也最高，可它此刻根本够不到；而“走到桌子旁”对清洁这件事的直接相关性更低，却是唯一做得成的一步。',
 recall_module='改动落在“选择”这一层：在一份已有技能之上，给每个候选再乘一个与当前状态相关的可执行性权重，让物理能力直接参与高层决策。它没有改底层控制器——策略与价值函数都是事先训好的，运行时不更新；也没有扩大动作集合，候选永远是那份固定的技能描述表；语言模型同样没有为机器人微调，只是被换了一种用法。',
 recall_io='输入有四样：一条自然语言指令、由已选步骤累积起来的提示、当前相机观测，以及固定的技能描述表；其中语言模型只看文本，观测只进价值函数，两者看到的东西并不相同。输出是一条被选中的技能描述，交给它自己的低层策略去执行，执行完这句描述被追加回提示，进入下一轮打分，直到模型选出终止 token。失败没有专门的处理通路：系统在执行后不做成功检测，环境变化只能通过下一轮价值函数在新观测上重新打分间接体现。因此价值函数虚高时，报了高值却失败的技能不会被识别，论文自己也把这一点列为局限。',
 steps=[('先固定一个技能库','论文提出 551 项技能，覆盖 7 个技能族与 17 种物体（抓取、放置、开关抽屉、导航等）。每项技能都有三样东西：一句语言描述、一个低层策略、一个可执行性估计。候选被限定在这些描述上，模型不能凭空发明机器人没有的动作。'),('语言分数：用打分模式，而不是生成','语言侧接的是现成的 540B PaLM，不为机器人做任何微调，只用它的打分接口，论文因此把系统称为 PaLM-SayCan。提示按对话结构写成“How would you: 指令 / I would: 1.”，附录的提示含 17 个示例。系统不让模型自由生成下一步，而是把每条技能描述逐条作为候选续写送进去，读出模型给这条描述的概率。它衡量的是“这句话接在任务与已选步骤之后有多合理”。v2 另有一个变体：先用生成模式写一段 Explanation，再把它放回提示里打分。'),('可执行性分数：来自稀疏奖励的价值函数','每项技能有一个以语言为条件的价值函数 Q(s, a, ℓ)，输入是当前相机观测加技能描述的文本嵌入，用 TD 方法在机器人经验上训练。奖励设成成功为 1、否则为 0 且不打折扣——在这种设定下价值本身就等于“从当前观测出发执行这条技能的成功概率”，这是它能当可执行性用的原因。实现上策略按 BC-Z 用行为克隆训练，价值函数则来自 MT-Opt 的多任务 RL（仿真训练后用 RetinaGAN 迁移）。'),('相乘、执行、把已选步骤写回提示','两个概率相乘后取最大的技能，执行它的低层策略，再把这句描述追加到提示里重新打分，直到模型选出终止 token。乘法是论文的建模分解（语义有用 × 当前做得到），实际分数仍依赖两个模型的校准。')],
 example='教学推演：回到上面的场景。第一步，候选只能来自那 551 条技能，“找一块海绵”“拿起海绵”“走到桌子旁”都在其中。第二步，把这些描述逐条送去打分，“拿起海绵”的语言分数很高——语义上它确实是该做的事。第三步，价值函数看的是当前画面：机器人面前没有海绵，于是所有 pick 类技能的值都很低（原文图 2(c) 画的正是这种空场景），而“走到桌子旁”的值很高。第四步相乘后排序反转：假设语言 0.6 × 可执行 0.1 = 0.06，低于 0.3 × 0.9 = 0.27（这两组数字是为解释相乘如何改变排序而设的假设值，不是论文报告的分数），于是先移动。执行后把“走到桌子旁”追加进提示重新打分，此时观测已变，“拿起海绵”的价值升高、语言分数依旧高，它才成为下一步；如此循环到模型选出终止。整个过程里变化的只是技能排序和观测，抓取控制器并没有现场学会新动作；而如果价值函数虚高，系统依然会选中一个其实抓不到的技能，论文在局限里也提到它无法对“报了高值却失败”的技能做出反应——这正是下一篇 Inner Monologue 的切口。',
 code='skills = 551 个固定选项，每个带 (policy, value_function, text)\nprompt = 17 个示例 + "How would you: " + instruction + "\\nI would: 1."\n\nwhile True:\n    for s in skills:                       # 打分模式：候选是固定描述，不生成新动作\n        say = p_LLM(text(s) | prompt)      # 语义上该不该做\n        can = Q(observation, text(s))      # 稀疏奖励价值函数 ≈ 此刻的成功概率\n        score[s] = say * can\n    s_best = argmax(score)\n    if s_best is terminate: break\n    execute(policy(s_best))                # 控制器在此刻不学习\n    prompt += " " + text(s_best) + ". next,"   # 写回已选步骤，用新观测重新打分',
 setup='作者在移动操作机器人上测试 101 条指令、7 个指令族，包括抽象表达与长程任务；分别记录计划是否正确、整段任务是否执行成功。表 2 还比较了实验厨房与真实厨房。',
 headers=['设置 / 方法','计划成功率','执行成功率'],
 rows=[['PaLM-SayCan · 实验厨房','84%','74%'],['去掉价值函数 · No VF','67%','该表未报告'],['PaLM-SayCan · 真实厨房','81%','60%'],['长程子集 · 实验厨房（15 条）','73%','47%']],
 findings='84% 到 74% 的差距说明：高层选对步骤后，物理执行仍会失败。长程子集只有 47% 执行成功，因此不能把总体 74% 当作复杂长任务的成功率。',
 ablation='去掉价值函数，计划成功率从 84% 降到 67%。这支持“场景中的可执行性有助于选对技能”。换用 FLAN 后计划 / 执行变为 70% / 61%（表 3），说明语言模型和底层能力都会限制系统。',
 boundary='模型来源是混合的，读结论时要分开算成本：语言侧是现成的通用大模型（540B PaLM），不做机器人微调、可以替换，换成 137B FLAN 后降到 70% / 61%；机器人侧的 551 项技能策略与价值函数都由作者自己训练（行为克隆用遥操作演示，价值函数用仿真多任务 RL 加真机在线采集），这是系统真正的前提成本。因此零样本主要指高层新指令的组合，不是整个系统不需要训练。把候选技能限制在技能库中能减少不合法选择，但无法替代执行后的成功验证——论文也提到它难以应对“报了高值却失败”的技能。',
 transfer='连到 Inner Monologue：SayCan 为选择提供依据，下一篇把执行结果再送回规划器。读后续论文时，也可以继续问：其“能不能做”的知识究竟存在哪里？',
 exercise='只用 CPU 就能做：设计 5 项工具和一个可变状态，比较纯语言排序与加入可执行性排序；再故意让可执行性分数失准。',
 answer='预期观察不是“相乘永远更好”，而是准确的状态相关评分能阻止不可执行选择；错误评分也会把正确技能压低。记录选错技能率和整任务成功率，才能区分选择与控制问题。',
 sources=[('方法：§3–4','S3'),('价值函数空间：图 2','S3.F2'),('结果：表 2、表 3','S5.T2')])

add('inner-monologue', version='v1',
 takeaway='把“刚才到底发生了什么”写回上下文，计划才能随现实改变。',
 result='有动作噪声的真实桌面任务：初始观测规划 20%，加入物体与成功反馈后平均 90%。',
 why='普通 Agent 的工具报错通常很明确，机器人却可能“命令执行完了，但东西没抓到”。Inner Monologue 的贡献是把物理执行中的成功、场景变化和人类反馈变成规划器能使用的语言信息，从一次性规划走向执行中的调整。',
 scene='真实桌面上的分类任务：把食物放进一只盘子、把调料放进另一只。抓放位置被人为注入了噪声，所以抓空是常态；还有物体一开始被别的东西挡着，没能进入最初的清单。如果规划只在开头看一眼世界、之后照计划念下去，抓空会被当成抓到，被挡住的瓶子会一直不存在。',
 recall_module='这篇的改动落在运行时与上下文管理这一层：在原有的高层规划与原有的低层技能之间新开一条回传通路，把每一步执行后的证据翻成文本重新拼进提示，规划因此从一次性生成变成边做边改。它没有换世界的表示，反馈仍旧是一句句自然语言；也没有换动作的出口，候选仍是技能库里已有的短程策略。语言模型全程少样本提示、不微调，低层策略在闭环里一次都不更新，真正被改写的只有提示里的文字。',
 recall_io='输入侧，模型看到的全是文本——任务指令、少样本示例、初始物体列表，以及每执行一步后追加的成功反馈、物体反馈与任务进度清单；图像并不进模型，而是先由外部模块消化成文字，仿真读真值规则，真实桌面用 MDETR，厨房用作者微调的 CLIP，厨房的物体反馈甚至由人工报读。输出是一句技能描述，也就是下一步做什么，交给技能库里对应的已训练好的低层策略去执行，终止条件是模型不再写出新步骤。失败处理这条通路是有的：由成功检测器判定刚才那条技能有没有做成，依据是执行前后的观测，真实桌面比的是 MDETR 检测框中心与目标放置点的距离，结论以一句文本追加回提示，模型据此重试同一步、换一步，或把刚刚露出来的物体补进后续计划。需要留住的是这条通路的可靠性完全取决于反馈模块，成功检测本身会误判，附录里 ViLD 在厨房仍有 28.0% 的漏检。',
 steps=[('先约定：规划器只能从已训练好的技能里选', '论文设定机器人只会执行技能库里已有的短程策略，每条策略配一句语言描述，这些策略可以由强化学习或行为克隆得到。规划器是一个预训练语言模型，全程不微调，只用少样本提示。三个实验用的模型并不相同：仿真桌面与真实桌面用 InstructGPT-1.3B（由 GPT-3 经人类反馈微调而来，走 OpenAI API），厨房移动操作用 PaLM-540B。'), ('每执行一步，就生成两类文本反馈', '成功检测是一个二分类问题，回答刚才那条技能有没有做成；物体反馈回答此刻看见了什么。实现方式按环境而变：仿真里用真值物体位姿写的规则（抓放后二维距离小于 4 cm 且高度更高即算成功），真实桌面用现成的开放词表检测器 MDETR，既给物体列表，也用检测框中心与目标放置点的距离做成功判定（堆积木阈值 3 cm，分类任务 10 cm）。厨房里的成功检测是作者自己训练的：一个以 CLIP 图像与文本编码器为底、在遥操作演示与自主回放数据上用二元交叉熵训练的 foresight 模型，输入是首帧、末帧与技能文本，另配一个用对比损失训练的 hindsight 模型压低误报。'), ('任务进度反馈把目标写成一张可勾选的清单', '在仿真桌面的 Object + Scene 变体里，模型先按高层指令生成一串“[x] 在 [y] 上面”形式的子目标，之后每执行一次抓放，就用上面那个成功检测器逐条核对，把当前已满足的子目标列表追加回提示。作者还允许模型在清单之后写一句“Robot thought: …”作为思维链摘要，经验上更稳。这类反馈解决的是组合状态空间里“做到哪一步了”的问题，与单步成功检测回答的问题不同。'), ('追加反馈重新生成，直到模型不再写出新步骤', '反馈以文本形式拼回提示，下一轮模型同时看到原指令、动作历史与最新反馈，于是可以重试、换步骤或处理刚露出来的物体。终止条件是模型停止生成新步骤，仿真里另设了最多 15 步的上限。厨房实验额外接入 SayCan 的价值函数为动作打可执行性分，但论文注明这些价值函数只影响选择、不把信息回传给语言模型；主动场景描述这一支则允许模型自己提问，由人作答。')],
 example='教学推演：回到上面的场景。第一步，候选动作来自那一条已经写好的抓放策略，规划器是不微调的 InstructGPT-1.3B，提示里只有少量示例和初始物体列表。第二步，第一次去抓水果抓空了，MDETR 重新检测当前画面，把检测框中心与原定放置点比对，距离超过 10 cm，于是成功检测返回失败；如果只记下“已执行 pick”，规划就会带着一个空盘子进入下一项。第三步，物体反馈同时刷新两份清单——当前可见物体，以及已经成功移入盘中的物体；仿真变体里对应的是那张按“[x] 在 [y] 上面”写成的子目标清单。第四步，这些文本拼回提示后重新生成：模型看到失败便重试抓取，看到清单里多出一个刚被水果遮住、现在才检测到的瓶子，就把它补进后续计划，直到清单填满、模型不再写出新步骤。整个过程里低层策略一次都没有更新，变化的只有提示里的文字；而反馈本身也会出错——附录 Table 5 显示 ViLD 在厨房场景仍有 28.0% 的漏检，错误的成功检测会让规划器把没做成的事当成做成了。另外，这套反馈只能把世界描述成一句句自然语言，“把积木等间距排成一条对角线”这种需要精确计算的目标写不进去，下一篇 Code as Policies 换掉的正是这个中间表示。',
 code='prompt = 少量示例 + 指令 + 初始物体列表        # 语言模型不微调\nhistory = ""\nfor t in range(15):                            # 仿真里步数上限为 15\n    step = LLM(prompt + history)               # 生成模式，直接写出下一句动作\n    if step is empty: break                    # 终止条件：模型不再写新步骤\n    execute(policy(step))                      # 已训练好的低层策略，此刻不更新\n    ok   = success_detector(o_before, o_after, step)\n    #      仿真=真值规则 / 真实桌面=MDETR 检测框距离 / 厨房=作者微调的 CLIP\n    objs = object_feedback(o_after)            # MDETR、ViLD 或人工报读\n    done = [g for g in subgoals if check(g, o_after)]   # 仅任务进度反馈使用\n    history += "\\nSuccess: " + ok + "\\nScene: " + objs + ", 已完成 " + done',
 setup='真实桌面实验使用 UR5e、RGB-D、MDETR 物体识别及脚本化抓放；为检验恢复能力，动作加入标准差 4 mm、截断于 2σ 的噪声。表 2 涉及续堆积木和水果 / 瓶子分类，每项 10 次。',
 headers=['反馈配置','两项真实桌面任务平均成功率'],
 rows=[['只在开始识别物体的开环 LLM','20%'],['持续物体反馈','45%'],['仅成功反馈','40%'],['持续物体 + 成功反馈','90%']],
 findings='闭环反馈的收益在失败恢复场景最明显；90% 是两个小规模桌面任务的平均值。另一个厨房移动操作实验中，表 3 的总体成功率为 SayCan 30.8%、完整反馈 60.4%，不能与桌面实验合并计算。',
 ablation='只保留物体或成功反馈都明显弱于两者结合。论文将相应失败联系到遮挡造成的漏对象和动作失败后不重试；这比只比较“有 / 无 agent”更能解释机制。',
 boundary='反馈质量决定闭环质量，而反馈来自哪里必须逐项拆开看。模型来源是混合的：语言侧完全是现成的通用模型，仿真与真实桌面用 InstructGPT-1.3B、厨房用 PaLM-540B，都不为机器人微调，可以替换；机器人侧则是作者的前提成本——仿真的低层抓放策略是一个以 CLIP 为底的 Transporter Net，用 20000 条演示训练，厨房的技能策略与价值函数沿用 SayCan。反馈模块同样混杂：仿真的成功检测与物体列表直接读仿真器真值，真实桌面靠现成的 MDETR 加几何启发式，厨房的成功检测是作者微调的 CLIP（foresight 加 hindsight 两个模型），而厨房的物体反馈由人工提供，附录 Table 5 才评估了把它换成 ViLD 或 MDETR 的可行性，ViLD 仍有 28.0% 的漏检。因此不能把所有反馈都理解成全自动视觉感知，也不能把一次成功检测当成真值。',
 transfer='往后读 PhyAgentOS 时关注同一个问题如何变成明确的验收协议；读 ASPIRE 时看反馈如何从一句“失败了”细化到具体 API 的执行证据。',
 exercise='在已有工具 Agent 中加入“假成功”：工具返回正常，但状态没有改变。比较只读返回码、读最终状态、同时读前后状态的三种判断。',
 answer='能形成记忆点的是反馈的内容，而不是反馈的长度。最好报告误接受率、漏检率和恢复额外调用数，避免靠无限重试把验证器的问题藏起来。',
 sources=[('反馈机制：§3','S3'),('桌面实验：§4.2 / 表 2','S4.SS2'),('厨房实验：§4.3 / 表 3','S4.SS3')])

add('cap', version='v4',
 takeaway='让语言模型写带计算和控制流的机器人程序，复杂行为可以由简单接口组合出来。',
 result='未见指令与属性的仿真长程任务：CaP 80%，自然语言规划器 64%；空间几何任务为 62%。',
 why='如果接口只有“抓”和“放”，自然语言列表很难精确表达“把积木均匀排成对角线”。CaP 把程序作为中间表示：模型负责组合规则，Python 和数值库负责准确计算，机器人 API 负责感知与执行。',
 scene='指令是“把三个积木等间距摆在两只碗之间”。这句话里没有一个名词能直接对应某条固定技能：等间距要算插值，两只碗的位置要先看到，摆放还得逐个循环。只给一份技能菜单，模型无从表达这个任务。',
 recall_module='改动落在动作的输出形式与中间表示上：高层不再吐一串技能名，而是吐一段可执行的 Python，控制流、算术与几何计算交给解释器和 NumPy、SciPy、Shapely，感知与动作只以被调用的 API 形式出现。世界的表示没有被预先写进提示，场景信息要等程序跑起来才由感知 API 取回。这篇不训练任何权重，不改底层的脚本化抓放原语与现成检测器，也没有给系统加上执行之后的验收环节。',
 recall_io='输入是提示里的 Hints（可用 API 的 import 与命名约定）、Examples（注释与解法代码的配对），以及作为一行注释追加进去的新指令；同一会话里上一轮的回答也留在上下文，因此后续指令可以引用前一步；场景状态不进提示，由生成的代码在运行时调用第一方感知 API 取回，背后是现成的 MDETR 或 ViLD。输出是一段 Python 程序，先过执行前的静态检查（不得有 import、双下划线变量、exec 与 eval），再交给 exec 在装着全部 API 的作用域里运行，调用到尚未定义的函数时由另一个 LMP 递归补出定义，真正落到硬件的是程序里调用的脚本化抓放原语或末端轨迹跟随接口。这篇没有执行之后的失败检测与恢复通路：代码里确实可以写反馈循环，但那是每轮重新调用 parse_obj 查询场景来决定还要不要继续，而不是判断上一次抓放有没有做成。原语正常返回与积木有没有稳稳落在插值点是两回事，碰撞与接触误差不在代码的视野里，论文也写明按执行反馈调整增益这一类能力当前并不支持。',
 steps=[('提示分成 Hints 与 Examples 两块', 'Hints 是一串 import 语句加命名约定，用来告诉模型手上有哪些 API、返回什么类型，论文建议写成 from utils import 函数名，并用 _np 后缀或 get_bbox_xyxy 这类名字传递类型信息。Examples 是若干“指令写成注释、紧跟一段解法代码”的配对。语言侧用的是现成的 OpenAI Codex code-davinci-002，温度设为 0 走贪心解码，全程不做微调；把新指令连同上一轮的回答继续追加，就能维持一个会话，让后面的指令引用“撤销刚才那一步”。'), ('三类 API 决定了代码能算什么、能碰什么', '第三方库负责计算：NumPy、SciPy、Shapely 已在模型的训练数据里，插值、几何运算不必靠语言推理完成。第一方感知 API 负责取状态，实现上直接调用现成的开放词表检测器——桌面抓放与画图用 MDETR，厨房移动操作用 ViLD，论文明确说这些模型是拿来即用、不做额外训练。第一方控制 API 负责动作，桌面域是一个脚本化的抓取并放置原语，画图域是末端轨迹跟随接口，厨房域是按名字或坐标导航与抓取的接口。'), ('分层生成：把没定义的函数交给另一个 LMP 补', '生成的代码块先被解析成抽象语法树，逐个找出当前作用域里不存在的函数，再调用一个专门做函数生成的 LMP 写出定义并加入作用域，然后对新生成的函数体重复同样的检查，按深度优先一路补下去。这样提示里只需给出逻辑的粗略骨架，不必把实现细节全部写进示例。论文把这种带冗长变量名的分层生成看作函数式版本的思维链。'), ('先做安全检查，再用 exec 执行', '运行前先确认代码里没有 import 语句、没有以双下划线开头的特殊变量、没有 exec 与 eval 调用。通过后交给 Python 的 exec，并传入两个字典作为作用域：globals 装着所有可调用的 API，locals 初始为空、执行过程中接住新变量与新函数；需要返回值时从 locals 里取。循环与终止条件写在生成的代码自己身上，例如“只要还有面积大于 0.2 且在红碗左边的积木就继续移动”，每轮重新调用 parse_obj 查询，直到列表为空。')],
 example='教学推演：回到上面的场景。第一步，提示的 Hints 写明 import numpy as np 与 from utils import get_pos, put_first_on_second，Examples 给出几组“注释加代码”的样例，把指令作为一行注释追加到末尾，交给温度 0 的 code-davinci-002 续写。第二步，生成的代码先用 get_pos 取两只碗的位置——这个函数背后是现成的 MDETR，返回的是检测框推出的坐标；随后用 NumPy 做插值算出三个目标点；最后逐个调用 put_first_on_second，由脚本化的抓放原语落到硬件上。分工很清楚：模型出结构，数值库出坐标，原语出动作。第三步，如果生成的代码顺手调用了一个没定义的 parse_obj 或 get_objs_bigger_than_area_th，语法树检查会发现它不在作用域里，于是再请一次函数生成 LMP 把定义写出来，并对这个新函数体继续同样的检查。第四步，整段代码通过“无 import、无双下划线、无 exec 与 eval”的检查后交给 exec，globals 里放好上述 API，locals 收下中间变量；如果指令带条件（比如“把所有还在红碗左边的积木往右挪”），终止条件就是生成代码里那个 while 每轮重查后返回空列表。需要注意的是这套流程没有验证物理结果：抓放原语报不报错与积木有没有稳稳落在插值点上是两回事，碰撞和接触误差不在代码的视野里。下一篇 ProgPrompt 补的正是这一层——把场景里有什么、动作的前置条件是什么，直接写进提示。',
 code='prompt = Hints(可用 API 的 import 与命名约定) + Examples(注释→代码) + "# " + 指令\ncode   = Codex(prompt, temperature=0)          # code-davinci-002，不微调\n\ndef run(code, scope):\n    assert 无 import and 无双下划线变量 and 无 exec/eval   # 执行前的安全检查\n    for name in 未定义调用(ast.parse(code)):     # 语法树里找不在作用域的函数\n        scope[name] = run(函数生成LMP(name), scope)   # 深度优先递归补全\n    exec(code, globals=所有 API, locals=空字典)  # locals 接住新变量与新函数\n    return locals.get("ret_val")\n\n# 循环与终止条件写在生成的代码里，例如：\n#   names = parse_obj("红碗左边且面积大于 0.2 的积木")\n#   while names: put_first_on_second(...); names = parse_obj(同一句查询)',
 setup='表 III 的桌面仿真按指令和属性是否见过划分，含 8 类长程任务与 6 类空间几何任务，每项 50 次。另有真实 UR5e 绘图 / 抓放展示，以及代码单元测试基准。',
 headers=['指标 / 设置','比较方法','CaP / 层次生成'],
 rows=[['未见指令 + 属性 · 长程成功率','NL Planner 64%','80%'],['未见指令 + 属性 · 几何成功率','CLIPort 0.01%','62%'],['RoboCodeGen · Codex davinci 测试通过率','平铺生成 81%','层次生成 95%']],
 findings='代码的优势在需要精确计算与组合的新指令上比较清晰。RoboCodeGen 的 95% 是程序单元测试通过率；摘要里的 HumanEval 39.8% 同样是编程指标，均不能替代机器人任务成功率。',
 ablation='表 I 在相同模型内对照平铺和层次化生成，davinci 从 81% 到 95%。这支持函数分解的作用，但不同模型改善幅度不同；小模型未必能可靠管理更复杂的函数层次。',
 boundary='高层抓放 API 隐含了大量工程能力，读代码时必须圈出模型生成的部分和人工提供的部分。模型来源这一层是干净的：语言侧是现成的 Codex code-davinci-002，感知侧是现成的 MDETR 与 ViLD，几何计算靠 NumPy、SciPy、Shapely，论文明确说整套系统不需要任何额外的数据收集或模型训练。但“零训练”只成立于模型层，成本被转移到了别处——作者自己写的是每个 LMP 的 Hints 与 Examples、第一方感知与控制 API 的实现、脚本化的抓放原语，以及那套语法树检查加递归函数生成的执行框架；附录专门用一节讨论提示里不能有 bug、命名要一致、类型提示怎么给。相比之下对照组 CLIPort 用 30k 条演示做模仿学习，那是基线的成本，不是 CaP 的成本，两者不可直接换算。示例可运行，也不意味着碰撞、接触与控制误差已解决。',
 transfer='接着读 ProgPrompt 看“提示怎么描述机器人世界”；再读 CaP-X 看接口抽象、感知噪声和多轮调试怎样改变结果。',
 exercise='固定模型与任务，把 pick_and_place 分别换成高层抓放、末端位姿 + 夹爪两套接口，观察成功率如何变化。',
 answer='把失败拆成代码错误、几何错误和控制失败。若高层接口大幅提升结果，说明抽象本身贡献了能力；不应把全部收益归因于模型更会推理。',
 sources=[('方法：§III','S3'),('代码与机器人实验：表 I–III','S4'),('仿真设置：§IV-D','S4.SS4')])

add('progprompt', version='v1',
 takeaway='把对象、动作、前置条件写进程序提示，让计划从一开始就适配当前环境。',
 result='VirtualHome：完整 Codex 配置任务成功率 40%，动作可执行率 90%；这两个数字衡量不同事情。',
 why='通用模型会说“打开冰箱拿食物”，但当前场景可能没有冰箱。ProgPrompt 将场景对象、可用动作、示例计划组织成类 Python 的提示，让模型补全一个具体环境中的程序。它还用注释提示子目标，用断言表达动作前必须满足的条件。',
 scene='指令是“把杯子放进柜子”，而柜子此刻是关着的。模型完全可能写出一段每条动作都合法、语法上无可挑剔的程序，直接把杯子往柜子里放。程序照样跑完，杯子却没进去——动作可执行与任务完成是两件事。',
 recall_module='改的是提示这一层，也就是机器人世界怎样被写给模型看：可用动作以 import 清单给出，场景对象以字符串列表给出，前置条件以 assert 写在动作之前并配上 else 恢复动作，计划因此在生成的那一刻就被约束在当前环境里。约束加在提示而不是解码上，模型仍然一次补全整段函数体，不走逐条枚举候选再打分那条路线。这篇不训练任何权重，不改动作原语的实现，也没有引入独立的符号检查器——断言成不成立由同一个语言模型作答。',
 recall_io='输入是动作原语的 import 清单、当前场景的可用对象列表（真实机器人上这份列表由现成的 ViLD 生成）、三段完整的示例程序（Davinci 主干因上下文长度只放得下两段），以及待完成的任务名。输出是一次补全的整段函数体，一段可直接执行的程序，交给解释器逐句对环境执行，终止条件就是函数体跑完，外层没有重规划。失败处理有一条，但只管动作之前：断言在现场求值，做法是把相关对象的信息从 VirtualHome 的状态图里取出来，连同这条断言一起作为文本再问一次语言模型，回答否定就先跑 else 分支里的恢复动作，例如先 open 柜子再 putin。没有的是动作之后的成功反馈——做没做成不回传给模型，这正是 90% 的动作可执行率能与 40% 的任务成功率并存的原因；真实机器人上因为状态跟踪不可靠，连这层断言检查都没有启用。',
 steps=[('把“机器人会什么、场景里有什么”写成程序头部', '动作原语以 Pythonic 的 import 语句列出，促使模型只调用当前语境下存在的函数；换一个机器人，只需换一份导入清单。场景里的可用对象以字符串列表给出，模型因此不会去拿一个不存在的杂货袋。真实机器人上这份对象列表由现成的开放词表检测器 ViLD 生成，同一批分割掩码再配深度图转成点云供动作使用。'), ('示例计划里同时演示注释、动作调用与断言', '提示中固定放三段完整可执行的示例程序（“把酒杯放进厨房柜子”“扔掉青柠”“洗马克杯”），Davinci 主干因为上下文长度只能放两段。注释用来把高层任务切成子任务，论文认为它给了模型一个近处的目标，减少发散与重复。断言写在动作之前表达前置条件，条件不成立时走 else 分支里的恢复动作，例如 grab(salmon) 之前先断言已经靠近它，否则先 find(salmon)。'), ('一次补全整段函数体，而不是逐条候选打分', '答案搜索的形式是让模型把 <next_task>() 这个函数的函数体一次写完，得到一段可直接执行的程序。这与 SayCan 那类先枚举全部合法动作再逐条打分的做法是两条路线：这里靠导入清单与对象列表在提示层面约束输出，而不是在解码层面约束。语言侧用的是现成的 GPT-3 系列模型，表 I 另外对照了 Codex 与 Davinci 变体，都不做微调。'), ('执行时逐句解释，断言在现场求值', '生成的程序交给一个解释器，逐条动作对环境执行，断言则在执行过程中闭环检查。在 VirtualHome 里环境给出的是带属性与关系的状态图，检查一条断言的做法是把相关对象的信息从状态图里取出来，连同这条断言一起作为文本再问一次语言模型，由它回答成不成立。终止条件就是函数体跑完，外层没有重规划；真实机器人上因为状态难以可靠跟踪，基于断言的闭环选项没有启用。')],
 example="教学推演：回到上面的场景。第一步，提示头部导入 find、grab、open、putin 这几个原语，再给出一行对象列表，告诉模型这个场景里有杯子和柜子——如果柜子不在列表里，模型就不会写出以它为参数的调用。第二步，三段示例程序示范了该怎么写：先用注释切出“# 拿起杯子”“# 把杯子放进柜子”两个子任务，每个动作前面挂一条断言与恢复动作。第三步，模型一次性补全 store_cup() 的函数体；此时一个合法但错误的程序完全可能直接写 putin(cup, cabinet)，因为每条动作都在导入清单里，语法上无可挑剔。第四步，解释器逐句执行，遇到 assert opened('cabinet') 时从 VirtualHome 的状态图里取出柜子的属性，把状态图与这条断言一起送回语言模型问一句“成立吗”，回答是否定的，于是先跑 else 分支里的 open(cabinet)，再继续 putin。没有这条断言，程序照样跑完、每条动作都合法，但杯子并没有进柜子——这正好解释了为什么动作可执行率会远高于任务成功率。还要注意两点：断言的判定者是同一个语言模型而不是独立的符号检查器，以及真实机器人实验里这一层根本没开。下一篇 Voyager 换的是另一个角度——程序在这里执行完就丢掉了，那边则把通过验证的程序存起来重复调用。",
 code='prompt  = "from actions import find, grab, open, putin, ..."   # 机器人会哪些动作\nprompt += "objects = [\'cup\', \'cabinet\', ...]"                  # 场景里有哪些对象\nprompt += 三段完整示例计划(含注释与 assert-else)              # Davinci 只放得下两段\nprogram = LLM(prompt + "def store_cup():")   # 现成 GPT-3 / Codex，一次补全整段函数体\n\nfor line in interpreter(program):            # 解释器逐句对环境执行\n    if line is assert:\n        graph = env.state_graph()            # VirtualHome 给出带属性与关系的状态图\n        ok = LLM(graph + line + " 成立吗")   # 断言由同一个语言模型判定\n        if not ok: execute(line.recovery)    # 不成立就先跑 else 分支的恢复动作\n    else:\n        execute(line)\n# 终止条件：函数体执行完即结束，外层没有重规划\n# 真实机器人上因为状态跟踪不可靠，这段断言检查未启用',
 setup='主要量化实验在 VirtualHome，报告完整任务成功 SR、动作可执行 Exec 和目标条件满足 GCR。表 I 含提示组成消融，固定示例数随模型上下文限制略有不同。',
 headers=['表 I 配置','SR','Exec','GCR'],
 rows=[['完整 · Codex','0.40 ± 0.11','0.90 ± 0.05','0.72 ± 0.09'],['完整 · GPT3','0.34 ± 0.08','0.84 ± 0.01','0.65 ± 0.05'],['GPT3 · 无注释、无反馈','0.18 ± 0.04','0.68 ± 0.01','0.42 ± 0.02'],['自然语言提示 · GPT3','0.00 ± 0.00','0.36 ± 0.00','0.42 ± 0.02']],
 findings='完整程序提示提高了多个指标，但 90% Exec 与 40% SR 的距离很大：动作逐步合法不保证最终完成任务。原文任务表里还出现 Exec 为 1、SR 为 0 的情况，适合训练自己区分“代码能跑”与“任务做对”。',
 ablation='同一 GPT3 下，完整配置 SR 为 34%，去掉反馈是 28%，去掉注释是 30%，两者都去掉是 18%。这比跨 Codex / GPT3 比较更能隔离提示结构的影响。',
 boundary='真实机器人部分主要是少量定性展示，没有启用反馈断言，因为系统不能可靠跟踪状态；不能把仿真的完整反馈机制与真实结果混为一谈。模型来源上这篇几乎没有自训模块：语言侧是现成的 GPT-3 系列，表 I 另比较了 Codex 与 Davinci，都不微调；真实机器人上的物体识别与分割用的是现成的 ViLD。作者自己提供的是提示模板、三段固定示例程序、动作原语的实现以及那个解释器。有一处特别值得圈出来：断言的判定者也是同一个语言模型，它依据 VirtualHome 的状态图作答，而不是一个独立的符号检查器，所以“程序里写了 assert”并不等于“正确性得到了保证”，闭环反馈的可靠性仍然回到同一个模型身上。',
 transfer='与 CaP 相比，本文更突出如何在提示中提供场景和动作约束；CaP 更突出程序的几何计算与层次组合。二者可以结合使用。',
 exercise='写一个很小的柜子状态机，分开计数“动作是否合法”和“杯子是否最终入柜”；比较有 / 无前置条件检查的程序。',
 answer='一个有力反例是：程序每条动作都合法，但遗漏放入杯子或最后又将杯子取出。只报告合法动作比例，会掩盖目标层失败。',
 sources=[('提示构造：§III','S3'),('表 I 与指标定义：§IV–V','S3.T1'),('真实机器人及限制：§V-C','S5.SS3')])

add('voyager', version='v2',
 takeaway='探索的产物是下次还能调用的技能代码，经验才有机会累积。',
 result='Minecraft 的 160 次提示预算内：钻石工具只在完整 Voyager 的 3 次运行中成功 1 次，无技能库版本为 0/3。',
 why='已熟悉 Agent 的读者容易把 Voyager 理解成多轮 ReAct；真正要记的是它把“下一个学什么”和“过去学过什么”都变成持久机制。环境不是实体机器人，而是 Minecraft，它适合观察课程、代码技能复用与持续探索之间的关系。',
 scene='智能体刚出生在 Minecraft 的森林里，物品栏是空的，没有人给它任务。它既要自己决定练什么，又要在做成之后把本领留下来；如果每次都从零写一段程序、用完就丢，后面做木镐时还得重新发现怎么采木头。',
 recall_module='改的是经验的存放位置与课程的来源：探索的产物不是参数更新，而是一段通过验证的 JavaScript 程序，连同它的描述嵌入写进向量数据库，以后靠检索取回来当子函数调用；练什么也不由人指定，而是课程模块按当前状态与已完成、已失败清单自己提。动作空间随之从底层指令换成了程序。这套系统没有任何梯度训练，底层执行完全依赖现成的 Mineflayer 接口，论文也直言不处理三维感知与传感运动控制。',
 recall_io='输入是智能体在 Minecraft 里的状态（物品栏、装备、附近方块与生物、生物群系、时间、生命与饥饿值、坐标）、已完成与已失败的任务清单、检索回来的 5 条技能，以及上一轮的代码连同三类反馈；其中状态与环境反馈由 Mineflayer 提供，报错由代码解释器提供，检索查询则先让 GPT-3.5 写一段笼统建议再嵌入去查。输出是一段 JavaScript 程序，交给 Mineflayer 在 Minecraft 里执行；通过自验证的程序连同 GPT-3.5 写的描述与其嵌入一起写进技能库。失败处理这条通路很完整：环境反馈来自控制原语内部的 bot.chat() 调用，执行报错来自代码解释器，另起一个 GPT-4 实例充当评论者回答任务有没有完成并给出怎么改的批评，三样一并拼回下一轮的生成提示重写代码，连续 4 轮仍然卡住就放弃这个任务、记进失败清单并换题。需要留住的是评论者与代码生成者同属一族模型，入库标准因此不是独立真值。',
 steps=[('自动课程：让 GPT-4 按当前能力提出下一个目标', '课程提示由四部分拼成：鼓励多样性并限制难度的指令（“目标是发现尽可能多不同的东西”“下一个任务不该太难”）、智能体当前状态（物品栏、装备、附近方块与生物、生物群系、时间、生命与饥饿值、坐标）、已完成与已失败的任务清单，以及一段由 GPT-3.5 自问自答生成的补充上下文——用小模型做这类常规文本任务是出于预算考虑。课程温度设为 0.1 以鼓励任务多样，系统其余部分温度都是 0。这个过程自下而上展开，论文把它看作新颖性搜索的上下文版本。'), ('技能库：向量数据库，键是描述的嵌入', '每条通过验证的技能以可执行程序的形式存入一个向量数据库，值是程序本身，键是这段程序描述的嵌入向量，描述由 GPT-3.5 生成、嵌入用 text-embedding-ada-002。检索时不直接拿任务名去查：先让 GPT-3.5 针对新任务写一段笼统的解题建议，把它与环境反馈拼成查询上下文，再取回最相关的 5 条技能。用程序而不是轨迹做记忆单元，是因为程序可组合、可读，也能被后续程序当子函数调用。'), ('代码生成：动作空间是 JavaScript 程序', '生成提示包含五块内容：编码规范（“这个函数会被复用来构造更复杂的函数，所以要写得通用”）、控制原语 API 与刚才检索到的技能、上一轮的代码连同环境反馈、执行报错与批评意见、智能体当前状态，以及要求先推理再写码的思维链引导。动作空间选程序而不是底层电机指令，是因为程序天然能表达时间跨度长、可组合的行为。执行靠现成的 Mineflayer JavaScript API，仿真环境搭在 MineDojo 上。'), ('三类反馈迭代修正，自验证决定入库还是换题', '环境反馈来自控制原语内部的 bot.chat() 调用（例如“做不了铁胸甲，还差 7 块铁锭”），执行报错来自代码解释器，自验证则是另起一个 GPT-4 实例充当评论者，拿到当前状态与任务后回答程序有没有完成任务，失败时还给出一段怎么改的批评。这三样都拼回下一轮的生成提示。循环有两个出口：自验证通过，就把程序连同描述的嵌入写进技能库，并向课程模块要下一个目标；连续 4 轮代码生成仍然卡住，就放弃这个任务、换一个。')],
 example='教学推演：回到上面的场景。第一步，课程模块把这份状态连同空的已完成清单送给 GPT-4，它在“发现尽可能多不同的东西”且“别太难”的约束下提出“采集木头”。第二步，带着这个任务去技能库检索：先让 GPT-3.5 写一句笼统建议，嵌入后取回最相关的 5 条技能——此刻库是空的，什么也取不到，后面学会采木头之后再问“做木镐”，取回的就会是采木头那条程序。第三步，GPT-4 拿着编码规范、Mineflayer 的控制原语、检索到的技能和当前状态，写出一段 JavaScript 函数。第四步，程序跑进 Minecraft，原语里的 bot.chat() 回报“还差 2 块木板”，解释器另外抛出一个不存在的方块名导致的报错，这两样连同批评一起拼回提示重写；自验证的 GPT-4 实例看过状态后判定任务完成，程序才连同 GPT-3.5 写的描述与其嵌入进入技能库，课程模块随即提出“做木镐”。如果四轮改下来自验证仍不通过，这个任务就被记进失败清单、换题。这套机制真正积累的是可检索的代码与索引，不是控制器参数——论文明说它依赖高层 Mineflayer 接口，不解决三维感知与底层运动控制；而且判定“做成了没有”的评论者与写代码的是同一族模型，通过与否并不是独立真值。下一篇 VoxPoser 换的正是这一层：它不再依赖预定义原语，而是让语言直接落到三维空间里的连续目标上。',
 code='while True:\n    task = GPT4(课程提示: 状态 + 已完成/已失败清单 + GPT3.5 自问自答的补充)  # 温度 0.1\n    q     = embed(GPT3.5("怎么做" + task) + 环境反馈)     # text-embedding-ada-002\n    skills = vecdb.topk(q, k=5)                          # 键是技能描述的嵌入\n    code = feedback = error = critique = ""\n    for r in range(4):                                   # 4 轮内仍卡住就换任务\n        code = GPT4(编码规范 + Mineflayer API + skills + code + feedback + error + critique + 状态)\n        feedback, error = run_in_minecraft(code)         # bot.chat() 与解释器报错\n        ok, critique = GPT4_critic(agent_state, task)    # 另一个 GPT-4 实例当评论者\n        if ok:\n            desc = GPT3.5(code)\n            vecdb.add(key=embed(desc), value=code)       # 只有自验证通过才入库\n            break',
 setup='作者在 Minecraft 比较 ReAct、Reflexion、AutoGPT 和 Voyager；表 1 以提示迭代次数衡量工具科技树进展，上限 160，进行 3 次运行。它不是实体机器人接触操作测试。',
 headers=['方法','木工具：提示次数 / 成功运行','铁工具：提示次数 / 成功运行','钻石工具'],
 rows=[['AutoGPT','92 ± 72 / 3/3','135 ± 103 / 3/3','0/3'],['Voyager 无技能库','7 ± 2 / 3/3','29 ± 11 / 3/3','0/3'],['完整 Voyager','6 ± 2 / 3/3','21 ± 7 / 3/3','102 / 1/3']],
 findings='技能库的价值更容易在较深的任务链中观察，但钻石里程碑的成功率仍只有 1/3。不能只记“到达钻石”，也应记它没有在所有运行中稳定达到。提示次数是预算单位，不能直接等同墙钟时间或机器人交互成本。',
 ablation='去掉技能库后，石工具的平均提示次数甚至是 9，而完整系统为 11；局部早期指标不是处处单调改善。铁工具与钻石阶段更能体现累积复用的意义。',
 boundary='Minecraft 提供的状态、动作接口和复位条件与物理机器人相差很大；游戏内技能代码的可复用不直接证明对传感器误差、抓取接触或本体变化的鲁棒性。模型来源上这套系统没有任何梯度训练：GPT-4（gpt-4-0314）负责课程、代码生成与自验证，GPT-3.5（gpt-3.5-turbo-0301）负责生成技能描述、自问自答与检索查询的改写，嵌入用 text-embedding-ada-002，动作执行靠现成的 Mineflayer JavaScript API，环境是 MineDojo。作者自己构建的是提示、那个向量数据库以及迭代循环本身，所以“终身学习”积累的是代码条目与检索索引，不是控制器参数——论文也直言不处理三维感知与传感运动控制。还有一点需要保留：自验证的评论者与代码生成者同属一族模型，入库标准因此不是独立真值，库里可能混入判定错误的条目。',
 transfer='把这个框架带到 Playful 时，要补上物理任务的提出、有效性检查与验证；带到 ASPIRE 时，经验还可以是跨任务修复策略，而不只是成功代码。',
 exercise='选一个可脚本控制的小环境，在相同交互预算下比较：无记忆、整段轨迹记忆、可调用函数库。使用未见组合任务测试迁移。',
 answer='至少记录库大小、检索命中、技能实际调用及失败传播。更多技能不必然更好，错误或重复条目也可能扩大上下文并误导调用。',
 sources=[('方法：§2','S2'),('探索结果与消融：§3 / 表 1','S3.T1')])
add('voxposer', version='v2',
 takeaway='语言先变成三维空间中的“哪里好、哪里不能去”，运动规划再寻找轨迹。',
 result='五类真实任务各 10 次：静态成功率 88%，扰动下 70%；原语基线分别为 24% 和 0%。',
 why='“把杯子放到右边，同时避开花瓶”既有目标，也有沿途约束。VoxPoser 不只生成一串动作名称，而是生成代码，将感知到的对象转换成可组合的三维价值图，给连续运动一个可优化的目标。',
 scene='指令是“把杯子从花瓶后面拿出来”。难处不在语义：杯子在哪、花瓶挡在哪、末端该走哪条弧线，都是连续空间里的量。技能菜单给不出这条轨迹，先喊一句“拿杯子”再指望控制器自己躲开花瓶也不成立。',
 recall_module='改的是世界与目标的表示形式：语言不再落成技能名或一串动作，而是落成三维空间里的一组价值图——哪里该去、哪里要避开、末端怎么转、什么时候闭合夹爪，都被写成 100×100×100 体素上的数值，目标与沿途约束因此能在同一次数值求解里被一起考虑。决策的产物交给运动规划器而不是控制策略，系统里没有技能库。这篇不训练任何组件，语言、检测、分割、跟踪全是现成模型，机器人自身动力学用已知模型，只有涉及接触的任务才在线拟合一个动力学模型。',
 recall_io='输入是自然语言指令，它进的是 planner 与 composer 这两层 LMP；RGB-D 观测不直接进模型，而是由代码发起的物体或部件查询驱动 OWL-ViT、Segment Anything 与 XMEM 串成的感知链，重建出点云供价值图代码赋值。输出先是一段 NumPy 代码，运行后得到那几张价值图；只有可供性图与避障图归一化加权后进入贪心搜索，求出一串无碰撞的末端位置，其余图再在每个路点上补齐旋转、速度与夹爪参数，合成的 6-DoF 轨迹只执行第一个路点。这篇没有执行后的成功检测，也没有发现失败、诊断原因、改写计划这条通路。它靠的是频率换稳健——每个周期重新感知、重新赋值、重新求解，5 Hz 滚动重规划，花瓶被挪开或抽屉被重新拉开这类变化会在下一帧的点云里自动体现，扰动因此被吸收；但没有任何模块回答刚才那次做成了没有，接触类失败不会被识别，开瓶这种靠接触定成败的任务，目标几何再正确也只能任其掉下来。',
 steps=[('planner 与 composer：两层语言模型程序', '提示结构沿用 Code as Policies 的做法，让模型递归地调用自己生成的代码，每个语言模型程序（LMP）只负责一项功能，每个 LMP 的提示里放 5 到 20 组示例问答。语言侧用的是 OpenAI API 上的 GPT-4，不做任何微调。两个高层 LMP 分工明确：planner 收下完整指令，输出一串子任务；composer 收下其中一个子任务，用具体的语言参数去调用相应的价值图 LMP。'), ('感知：三个现成模型串成一条链', '语言模型提出一个物体或部件的查询后，先由开放词表检测器 OWL-ViT 给出检测框，再送进 Segment Anything 得到掩码，最后用视频跟踪器 XMEM 把这个掩码逐帧跟住。跟踪到的掩码配合 RGB-D 观测重建出物体或部件的点云。这条链路上三个模型都是拿来即用、不做训练，它确定的是本轮要控制的“关注实体”——可能是机器人末端，也可能是某个物体或物体的一个部件。'), ('价值图：让模型写 NumPy，在 100³ 体素上赋值', '论文定义了五类价值图：可供性、避障、末端速度、末端旋转、夹爪动作，每一类由各自的 LMP 生成，输出形状是 (100, 100, 100, k)，可供性与避障的 k 为 1（表示一个代价），旋转的 k 为 4（表示 SO(3)）。由于直接赋值出来的图很稀疏，可供性图做欧氏距离变换、避障图做高斯滤波来致密化，这样规划出的轨迹更平滑。任务代价的定义是把关注实体走过的离散坐标上的图值累加起来再取负，也就是 F_task = -Σ V(p_j)。'), ('规划：只让两张图参与搜索，其余图逐点赋参数', '进入规划器优化的只有可供性图与避障图，代价图是这两张归一化后按权重 2 与 1 加权求和再取负，用贪心搜索求出一串无碰撞的末端位置。求出位置序列之后，再用剩下的旋转图、速度图、夹爪图在每个路点上补齐参数，得到完整的 6-DoF 轨迹。更一般的形式是零阶优化：随机采样若干条轨迹，用这个目标函数逐条打分。'), ('执行：只走第一个路点，5 Hz 重新规划', '整套优化放在模型预测控制框架里，每次只执行合成轨迹的第一个路点，然后拿最新观测重新规划，频率是 5 Hz。语言模型在环却仍然跑得动，是因为同一个子任务里生成的代码始终不变，可以把它的输出缓存下来重复使用。动力学方面机器人自身的模型是已知的，多数任务直接假设场景静止；只有当关注实体是物体时才用一个启发式的平面推动模型（以接触点、推动方向、推动距离参数化，把点云整体平移），用随机打靶的 MPC 求解参数后调用一个预定义的推动原语。')],
 example='教学推演：回到上面的场景。第一步，planner 把它拆成“抓住杯子”“把杯子搬到台面前沿”这样的子任务，composer 接过第一个子任务，带着具体的语言参数去调用价值图 LMP，这些提示的写法沿用 Code as Policies 的递归 LMP 结构，底下是不微调的 GPT-4。第二步，代码里对“杯子”“花瓶”发起感知查询，OWL-ViT 给框、Segment Anything 给掩码、XMEM 逐帧跟住，配合 RGB-D 重建出两者的点云，本轮的关注实体确定为机器人末端。第三步，可供性 LMP 在 100×100×100 的体素上把杯子附近赋成高值，避障 LMP 把花瓶周围赋成需要回避的区域，前者做欧氏距离变换、后者做高斯滤波把稀疏的赋值摊开；此外旋转图约定末端朝向，夹爪图约定在哪一格闭合。第四步，只有可供性与避障两张图进入贪心搜索，按权重 2 与 1 归一化加权求和再取负得到代价图，搜出一串绕开花瓶、伸向杯子的末端位置，随后在每个位置上补齐旋转、速度与夹爪参数。第五步，只执行第一个路点就重新感知、重新规划，频率 5 Hz；代码本身在这个子任务里不再重生成，只是缓存输出反复求解。所以花瓶被人挪动时，下一帧的点云变了，避障图跟着变，新轨迹自然绕开新位置——关键在于目标与约束是在同一次求解里被一起考虑的，而不是先生成一句“拿杯子”再指望控制器自己躲开障碍。这套机制解决不了的是接触：多数任务里环境动力学被假设为静止，只有物体推动这一类才有一个手写的平面模型，所以开瓶这种靠接触定成败的任务，目标几何再正确也会掉下来。与 ReKep 对照看最清楚：这里把目标写成空间中的值，那边把目标写成关键点关系的约束函数。',
 code='subtasks = planner_LMP(instruction)              # GPT-4，沿用 CaP 的递归 LMP 提示\nfor l in subtasks:\n    code = composer_LMP(l)                       # 同一子任务内只生成一次，之后缓存\n    while not done(l):\n        rgbd = camera()\n        pcd  = xmem(sam(owlvit(rgbd, 物体/部件查询)))   # 三个现成模型串成感知链\n        V_aff, V_avd, V_rot, V_vel, V_grip = exec(code, pcd)   # 各自 100×100×100\n        cost = -(2 * norm(edt(V_aff)) + 1 * norm(gauss(V_avd)))  # 只有两张图进优化\n        path = greedy_search(cost, 已知机器人动力学)\n        traj = attach(path, V_rot, V_vel, V_grip)   # 其余图逐点补成 6-DoF\n        execute(traj[0])                            # 只走第一个路点，5 Hz 重规划\n# 终止条件：当前子任务达成后取下一个 l；关注实体是物体时改用启发式平面推动模型',
 setup='表 1 的真实任务为移动并避障、摆桌、关抽屉、开瓶、扫垃圾，各设置每项 10 次；对照是使用预定义简单原语的 LLM 系统。表 2 另报告 13 项仿真任务。',
 headers=['表 1 真实任务','原语基线：静态 / 扰动','VoxPoser：静态 / 扰动'],
 rows=[['移动并避障','0/10 / 0/10','9/10 / 8/10'],['关抽屉','0/10 / 0/10','10/10 / 7/10'],['开瓶','5/10 / 0/10','7/10 / 5/10'],['五类任务总体','24% / 0%','88% / 70%']],
 findings='扰动后的 70% 是本文有解释力的数字：闭环空间重规划能够恢复部分变化，但没有完全消除物理困难。开瓶从 7/10 降到 5/10，也提醒读者复杂接触并不只由目标几何决定。',
 ablation='这个原语对照检验了联合空间表达与规划的整体收益，并非只移除一个模块的严格单变量消融。原文还研究在线动力学学习；“不训练任务策略”不能理解成系统完全没有模型与工程先验。',
 boundary='点云定位、地图分辨率和动力学近似决定可解范围。语言目标正确、价值图合理，仍可能因为姿态或接触模型不准确而失败。模型来源上这篇几乎全是现成件：语言侧 GPT-4，感知侧 OWL-ViT、Segment Anything 与 XMEM 串成一条链，机器人自身动力学用已知模型，论文强调整个过程不给任何一个组件追加训练。作者自己写的是各个 LMP 的提示（每个 5 到 20 组示例）、价值图的后处理（可供性做欧氏距离变换、避障做高斯滤波）、代价图的加权方式与贪心搜索规划器，以及那个平面推动的启发式动力学模型。唯一会拟合参数的地方在 §3.4：当任务涉及接触时，才用在线采集的转移数据学一个动力学模型，并拿零样本轨迹当采样先验缩小搜索范围。所以“不训练任务策略”指的是没有针对任务的策略学习，不等于系统里没有任何模型拟合或工程先验。',
 transfer='与 ReKep 对照看最清楚：VoxPoser 把目标写成空间中的值，ReKep 把目标写成关键点关系的约束函数；两者都把语言输出交给数值求解器。',
 exercise='先在二维平面模拟“目标 + 障碍”价值图，再移动障碍。比较固定轨迹、每步重新规划，并逐步增加感知偏移。',
 answer='这个简化实验能解释组合目标与反馈的作用，不能验证真实接触。将规划可行率、碰撞率、完成时间分开报告，避免只展示一条漂亮轨迹。',
 sources=[('价值图和规划：§3','S3'),('真实与仿真结果：表 1–2 / §4','S4')])

add('sayplan', version='v2', source_kind='pdf',
 takeaway='先在场景图里找出相关世界，再让规划器解决具体路径与动作前置条件。',
 result='长程规划：SayPlan 的计划可执行率 86.6%，LLM-As-Planner 为 13.3%；这不是实机任务成功率。',
 why='多房间机器人面对的是一栋楼，而不是一张桌子。把完整地图、物体清单和每一步移动都塞入上下文，会迅速扩大搜索空间。SayPlan 用分层三维场景图让语言模型按需展开相关区域，并把路径计算交给经典规划器。',
 scene='指令是“把二楼会议室的杯子拿到一楼厨房”，环境是一栋多楼层多房间的建筑（论文的 Home 环境有 3 层、28 个房间、112 件资产与物体）。把所有房间、家具与物体一次塞进上下文，光是办公室环境的完整场景图就有 6731 tokens，而其中绝大部分与这个杯子无关。',
 recall_module='改动落在世界的表示和规划视野上：一栋楼的信息被组织成一张可折叠的三维场景图，语言模型靠 collapse / expand / contract 按需取出与任务相关的子图，再只负责写房间级动作，pose 之间怎么走交给 Dijkstra；另外补了一个图模拟器，用来在执行之前校验计划。没有改的部分同样明确——场景图假设由已有建图方法预先构建，那几个图 API 与 verify_plan 都是手写的，底层的 pick、place、open、close 仍由原有的运动控制器完成，语言侧是现成的 GPT-4，没有训练任何权重，也没有改动作空间。',
 recall_io='输入是一句自然语言指令与序列化成 JSON 的三维场景图，模型每一轮只看到当前折叠状态下的图，外加一份记录已展开节点的 Memory 和与任务、环境都无关的静态提示；这张图不是模型感知出来的，由外部建图方法预先提供。输出分两段：语义搜索阶段输出 expand / contract / terminate 这类 JSON 命令，由场景图模拟器执行并回传更新后的图；因果规划阶段输出 goto、access、open 这样的房间级动作序列，再由 Dijkstra 补成 pose 级完整计划，通过校验后才交给底层视觉引导的运动控制器。失败由 verify_plan 发现，它在图上把整条计划前向模拟一遍，依据是图的谓词、状态与 affordance，不成立就把原因转写成一句文本追加进提示让模型重写，重规划上限为 5 次。要留意这条通路全部发生在执行之前：模拟器只检查图上的事实，论文假设建图之后物体保持静止，因此真实执行中抓取失败或物体已被搬走并不会回传给规划器（实机演示里的失败恢复由技能层的行为树处理，不进入这一层）。',
 steps=[('先有一张可折叠的三维场景图', '3DSG 是一个 NetworkX 图，序列化成 JSON 交给模型，分楼层、房间、资产、物体四层，另有一个动态 agent 节点和一串记录可通行拓扑的 pose 节点。论文假设这张图由已有的建图方法预先构建，不属于本文训练的内容。场景图模拟器 ψ 提供 collapse / expand / contract 三个 API：collapse 后只暴露最上层，办公室环境的完整图有 407 个节点、6731 tokens，折叠后剩 105 个节点、878 tokens。'), ('语义搜索：模型调 API 自己展开子图', '语言侧是现成的 GPT-4，不做任何微调。静态提示包含角色设定、场景图说明、输出格式与若干输入输出示例，约 3900 tokens，且与具体任务和环境无关。模型每一步输出一个 JSON，给出 expand 或 contract 以及节点名，由模拟器执行后把更新过的图回传；已展开过的节点记在 Memory 里一并输入，既避免重复展开，也使每一步不必携带完整交互历史。搜索由模型自己输出 terminate 结束。'), ('因果规划：只写房间级动作，路径交给 Dijkstra', '在搜索得到的子图上，模型只需要生成节点级的导航与操作动作，例如 goto(meeting_room)、access(fridge)、open(fridge)。pose 与 pose 之间怎么走由最优路径规划器（Dijkstra）补成完整计划。这一步是刻意缩短模型的规划视野，把细粒度搜索从语言模型手里拿走。'), ('图模拟器校验，用文字反馈重规划', 'verify_plan 在场景图层面把整条计划前向模拟一遍，检查是否符合图的谓词、状态与 affordance：手上已经拿着东西、机器人不在正确位置、冰箱没有先打开，都会判为失败。失败被转写成一句文本（如 cannot pick banana）追加进提示，让模型重写计划，循环到反馈为 success 为止；全部实验把重规划次数上限设为 5。通过校验的计划才交给底层视觉引导的运动控制器。')],
 example='教学推演：回到上面的场景。第一步，整张图先被 collapse，模型看到的只有楼层与房间这一层，而不是全部节点——在办公室环境里，这一步把 6731 tokens 压到 878 tokens。第二步，模型按房间名与属性判断哪里可能有杯子，输出形如 {command: expand, node_name: meeting_room} 的 JSON；模拟器展开该节点并回传新图，若里面没有相关物体，模型再输出 contract 把它收起，展开过的房间进入 Memory 不再重复访问；等会议室的杯子和厨房的目标位置都进入子图，模型自己输出 terminate。第三步，模型在这个小子图上只写高层动作序列，例如 goto(meeting_room)、pickup(cup)、goto(kitchen)、release(cup)，楼层之间与 pose 之间的路线由 Dijkstra 补齐。第四步，模拟器把补全后的计划整条走一遍：若杯子在一个需要先打开的柜子里，或机器人手上还握着别的东西，就返回一句“cannot pick cup”之类的文本，追加进提示让模型重写，最多重写 5 次。需要留意的是这整套循环都发生在图里：模拟器只检查图上的谓词是否满足，它不知道真实杯子此刻是否还在那个位置，也不检验抓取会不会失败。这正是 RoboOS 那类共享场景记忆要接手的问题——图不仅要缩短上下文，还必须随机器人行动更新。',
 code="G0 = collapse(scene_graph)        # 只留楼层/房间层：办公室 6731 → 878 tokens\nmemory = []                       # 已展开节点，避免重复且无需传完整历史\nwhile True:                       # 阶段一 语义搜索：GPT-4 输出 JSON 调用图 API\n    cmd, node = LLM(static_prompt, G0, instruction, memory)\n    if cmd == 'terminate': break\n    G0 = expand(node) if cmd == 'expand' else contract(node); memory += [node]\nfeedback = ''\nfor _ in range(5):                # 阶段二 因果规划：重规划上限 5 次\n    plan = LLM(static_prompt, G0, instruction, feedback)  # 只写房间级动作\n    full_plan = dijkstra_fill(plan, G0)                   # pose 级路径交给路径规划器\n    feedback = verify_plan(full_plan)                     # 查谓词 / 状态 / affordance\n    if feedback == 'success': break\nexecute(full_plan)                # 通过校验后才交给底层视觉引导控制器",
 setup='两个大规模环境覆盖多楼层、房间和资产；论文将语义搜索与因果规划分开评估。正确性 Corr 关心是否完成所要求的目标，可执行性 Exec 关心动作是否满足环境约束。',
 headers=['表 3 · 长程规划','正确性 Corr','可执行性 Exec'],
 rows=[['LLM+P','33.3%','0.0%'],['LLM-As-Planner','66.7%','13.3%'],['SayPlan','73.3%','86.6%']],
 findings='86.6% 可执行率高于 73.3% 正确率并不矛盾：一个计划可以合法执行，却没有正确满足用户意图。表 2 中办公室图的表示从 6731 tokens 缩到 878，展示的是按需展开对上下文规模的帮助。',
 ablation='两种规划基线与完整系统的差异表明，路径补全和模拟反馈有助于减少缺失动作、位姿等错误。语义搜索仍会受模型能力限制：GPT-4 在简单 / 复杂搜索中为 86.7% / 73.3%，不是总能找到合适子图。',
 boundary='模型来源在这篇里很集中：语言侧是现成的 GPT-4，不做任何微调，静态提示约 3900 tokens 且与任务和环境无关，换成 GPT-3.5 后语义搜索明显变差；系统其余部分都不是学出来的——三维场景图假设由已有建图方法预先构建，collapse / expand / contract / verify_plan 是手写的图 API，导航用 Dijkstra，实机演示中的 pick、place、open、close 由运动控制器配合 RGB-D 抓取检测与行为树实现。因此前提成本不在训练，而在“必须先有一张准确且最新的场景图”。核心量化结果也来自场景图层面的搜索与规划评估，真实机器人执行仅作展示；不能把图模拟中的可执行率当成抓取、导航和感知误差共同作用下的实机成功率。',
 transfer='RoboOS 的共享场景记忆可以与这篇一起理解：图不仅缩短上下文，还必须随机器人行动更新，否则更精巧的搜索也会建立在过期事实上。',
 exercise='用 JSON 构造楼层—房间—物体树。比较完整展开与按需展开在相同任务上的 token 数、漏检对象和计划正确率。',
 answer='增加“物体已被搬走”的情形，能把静态搜索与状态维护分开。若图不更新，检索速度再快也无法保证计划正确。',
 sources=[('方法：§3（PDF 第 4–5 页）','page=4'),('搜索与规划：表 1–3（第 6–7 页）','page=7'),('限制：§6（第 8 页）','page=8')])

add('rt2', version='v1',
 takeaway='把动作也当成模型要预测的 token，让网络语义知识参与机器人控制。',
 result='未见条件平均成功率：RT-1 32%，两种 RT-2 均为 62%；新语义能力测试中 PaLI-X 版为 60%。',
 why='前面的论文大多让 LLM 指挥一个外部执行器。RT-2 要理解的是执行器本身怎样吸收视觉语言知识：把预训练 VLM 接着训练成能输出机器人动作的模型，形成 VLA。它是理解后续“冻结 VLA + 外部 Agent”的基础。',
 scene='指令是“把苹果移到二加一的地方”，桌上摆着写有数字的卡片，而机器人演示数据里从未出现过数字卡片。做成这件事既需要知道 2+1 等于 3、认出 3 号卡片，也需要输出能把苹果挪过去的连续动作；只用机器人数据训出来的策略没有前一半知识。',
 recall_module='改的是策略本身，不是外层编排。落点有两处：动作的输出形式，8 维动作被离散成整数 token、直接占用视觉语言模型原有的词表，动作预测于是和文本预测共用一个目标；以及训练数据的混合方式，共同微调把机器人演示与网页图文放进同一批次，损失只有一个 next token prediction。没有改的东西是理解这篇的关键——不新增参数、不加动作专用层，动作空间沿用 RT-1 的 8 维，机器人数据也直接沿用 RT-1 那一批，没有另外训练低层控制器，也没有技能库、外部规划器或执行后的反馈环。',
 recall_io='输入是每个控制周期拍到的一帧机器人相机图像，加上写成 VQA 格式的指令 Q: what action should the robot take to [指令]? A:；模型能看到的只有这张图和这句文本，没有本体状态，也没有技能菜单或历史反馈作为额外上下文。输出是一串整数 token，采样被限制在合法动作 token 上，解码回末端位移与旋转、夹爪开合以及一个离散的终止指令，直接下发给机器人执行，中间没有规划器或原语层接手；推理跑在多 TPU 云服务上由机器人联网查询，55B 版约 1–3 Hz、5B 版约 5 Hz，做完一次动作再重新拍图问下一次。失败处理这一条要明确写出来：这篇没有成功检测、没有重规划、也没有恢复动作，闭环只体现在每个周期重新观测一次。抓空或物体被碰倒之后能不能纠正，取决于新图像落在训练分布的哪个位置，系统里没有任何模块会判定上一步失败了，终止也由模型自己置起终止维决定。',
 steps=[('先选定两个现成的视觉语言模型当主干', '论文接的是 PaLI-X（图像侧 ViT-22B，文本侧 32B、50 层的 encoder-decoder，实验用 5B 与 55B 两档）和 PaLM-E-12B（decoder-only，图像侧 ViT-4B）。两者都不是为机器人设计的。RT-2 不引入任何新参数，也不在策略里加动作专用层，只是把这两个模型接着训练成能输出动作，论文把这一类模型称作 VLA。'), ('动作离散成 token，占用模型原有的词表', '动作空间沿用 RT-1：末端 6 自由度的位移与旋转、夹爪开合程度，外加一个离散的终止指令，共 8 维。除终止外的连续维度各均匀离散成 256 个 bin，一条动作因此写成几个整数拼成的字符串（论文给的样例是 1 128 91 241 5 101 127）。占用哪些 token 取决于分词器：PaLI-X 中 1000 以内的整数各有专属 token，直接对应；PaLM-E 没有这种表示，就覆写 256 个最少使用的 token。训练样本按 VQA 格式写成 Q: what action should the robot take to [指令]? A:。'), ('共同微调：机器人数据与网页数据放进同一批次', '训练目标就是 next token prediction，在机器人这边等价于行为克隆损失。机器人数据沿用 RT-1 那批用 13 台机器人、17 个月在办公室厨房采集的演示；网页侧是 PaLI-X 与 PaLM-E 原本的混合（主体是 WebLI 等图文数据）。机器人数据的采样权重被调高，在 RT-2-PaLI-X 中约占训练混合的 50%，在 RT-2-PaLM-E 中约占 66%。消融显示只用机器人数据微调、或完全从零训练，泛化都明显更差。'), ('推理：约束词表、云端出 token、解码后闭环执行', '当提示属于机器人动作任务时，采样被限制在合法动作 token 上；模型在做通用视觉语言任务时仍可输出全部自然语言 token。模型太大跑不进机上算力，论文把它部署在多 TPU 云服务上由机器人联网查询，55B 版约 1–3 Hz，5B 版约 5 Hz。每个控制周期读一次图像与指令、出一串 token、解码成一次动作执行，直到模型自己输出终止维。')],
 example='教学推演：回到上面的场景。第一步，起点不是一个机器人模型，而是一个已经在网页图文上训练过的视觉语言模型——它本来就认得数字、也会做这种算术，RT-2 要做的是让它学会说出动作。第二步，指令要变成动作，先得规定动作的写法：末端位移与旋转、夹爪、终止共 8 维，连续维度各切成 256 档，于是“向右前方移一点、夹爪保持闭合、尚未结束”被写成形如 0 132 140 126 128 128 130 255 的一串整数（这串数字是为说明编码格式而设的假设值，不是论文报告的动作）。第三步，模型既懂 2+1 又会输出这串整数，是因为共同微调把两类数据放进了同一批次：机器人演示约占一半（PaLM-E 版约三分之二），其余仍是它原来的网页视觉语言任务，损失只有一个 next token prediction。第四步，运行时提示被送进云端多 TPU 服务，采样限定在那 256 个动作 token 上，回传的字符串解码成一次末端位移，执行完再拍新图重复，直到终止维被置起。这里迁移过来的是“3 号卡片在画面的哪个位置”这类语义与视觉知识，被复用的仍是机器人数据里那七类技能（pick、move near、place upright 等）；论文明确指出网页知识不会让机器人学会新的运动。下一篇 Harness VLA 关心的正是：当策略本身的动作分布已经固定时，外层还能怎样改善它的表现。',
 code="backbone = PaLI-X(5B/55B) 或 PaLM-E(12B)   # 现成 VLM，不新增参数\n# 动作编码 [terminate, Δpos xyz, Δrot xyz, gripper]，连续维各离散成 256 档\n# 训练：机器人演示(约 50% / 66%) + 原网页视觉语言数据 → next token prediction\n\nwhile True:\n    image = camera()\n    prompt = 'Q: what action should the robot take to ' + instruction + '? A:'\n    tokens = backbone.decode(image, prompt, vocab=仅 256 个动作 token)\n    a = detokenize(tokens)          # 整数串 → 末端位移/旋转/夹爪/终止\n    if a.terminate: break\n    robot.execute(a)                # 云端多 TPU 推理：55B 约 1-3 Hz，5B 约 5 Hz",
 setup='论文报告逾 6000 次机器人评估，分别研究已见任务、未见物体 / 背景 / 环境，以及符号、推理、人物识别等语义测试。下表取附录表 6–7；不同列来自不同评估集合。',
 headers=['模型','已见任务','未见条件平均','新语义能力平均'],
 rows=[['RT-1','92%','32%','17%'],['RT-2-PaLI-X-55B','91%','62%','60%'],['RT-2-PaLM-E-12B','93%','62%','40%']],
 findings='RT-2 的主要增益出现在泛化而非已见任务；已见表现没有全面碾压 RT-1。两种 RT-2 都是 62% 未见平均，却在语义测试上差异明显，也说明一个总体分数不能概括全部能力。',
 ablation='附录表 8 比较从头训练、只用机器人数据微调、共同微调；5B 模型从头训练的泛化平均为 9%，共同微调为 44%。该表独立报告的数值与表 6 的汇总口径应分别引用。',
 boundary='模型来源要分两层看：主干是现成的通用视觉语言模型（PaLI-X 5B / 55B、PaLM-E 12B），不新增任何参数；但 RT-2 并不是冻结调用它们，而是把整个主干做了共同微调（55B 版学习率 1e-3、批大小 2048、训练 8 万步），机器人侧则直接沿用 RT-1 的演示集，没有另外训练低层控制器。所以这套系统的前提成本是一次大模型微调加上云端推理，而不是一个技能库。原文也明确指出：网页知识帮助重组已有运动技能，并未让机器人自动学会训练轨迹之外的新运动；55B 版只能跑到 1–3 Hz，控制频率本身也是限制。',
 transfer='后续 Harness VLA 研究的正是：已有策略具备局部运动能力时，外层 Agent 怎样把它放到更合适的状态再调用。',
 exercise='用现有策略设计两类测试：只换目标物体的语义指代，以及保持语义但改变接触动作。分开统计两类泛化。',
 answer='如果第一类改善而第二类不改善，就支持语义迁移的解释。把这两类都叫“未见任务”，会隐藏机制差异。',
 sources=[('动作 token 与训练：§3','S3'),('泛化与语义测试：附录 H 表 6–8','A8'),('能力限制：§5','S5')])

add('robocodex', version='v1',
 takeaway='代码生成还需要看懂对象怎样运动；多模态推理要落实为抓取偏好和操作约束。',
 result='仿真表 1：抓放 80% 对 GPT-4V 的 63%，开门 74% 对 52%，多阶段任务 64% 对 50%。',
 why='“打开门”和“拉开抽屉”都可以写成一个函数，但它们的运动轴、可抓部位和碰撞约束不同。RoboCodeX 将多模态理解与树状代码生成结合，同时通过专门数据训练模型，让它更擅长把对象语义转化成可执行约束。',
 scene='指令是“把香蕉放进抽屉”。抽屉得先拉开，而拉开的方式取决于它是平移关节还是转轴门；香蕉怎么抓，又取决于它的形状与桌面朝向。这些都不是从指令文本里能读出来的，必须从图像里看出物体会怎么动。',
 recall_module='改的是从图像到运动参数这条链上的中间表示，同时也换了做这件事的模型。指令被拆成以物体为中心的代码单元，每个单元附一个操作偏好（接近方向或偏好接触位置），再向下展开成部件级 affordance、抓取位姿、关节类型与轴向、平面法向量这些可以算出来的量，最后编译成结构化的可执行代码。与 ReKep 的对照点正在模型来源上：那边全部用现成件，这边作者训练了自己的多模态模型 RoboCodeX-13B（EVA-CLIP ViT-G/14 加 Q-Former 加 LLaMA-13B，另有一个视觉适配器）；但抓取候选、关节参数、平面检测、运动规划与控制器一概没有改，分别来自 AnyGrasp、GAMMA、Open3D 与 ROS 侧的成熟模块。',
 recall_io='输入是三个视角的 RGBD 与一句指令，其中模型真正读到的只有三张 RGB 加指令，深度融成 TSDF 与占据栅格、物体点云按深度对齐后取出，这些都由外部系统完成，不经过模型。输出是若干 object-centric 单元连同各自的操作偏好，向下展开成一段结构化代码：代码里调 AnyGrasp 取前 10 个抓取候选再按偏好选定一个，调 GAMMA 估关节类型与轴向，调封装成 API 的 Open3D 平面检测取法向量；随后轨迹由零阶优化在控制代价与占据栅格约束下采样评分得到稠密路点，交给 ROS 侧的 MoveIt 与 OMPL，再由操作空间控制器跟踪。失败处理这一条是缺的：执行前只有轨迹层面的约束筛选，占据栅格会挡掉会碰撞的采样，但执行之后既没有成功检测，也没有重新感知或重写代码的通路。所以把平移关节的抽屉当成绕轴旋转的门时，生成的代码语法正确、程序照样跑完，问题只留在最终结果里——论文的误差分析也把长程任务的主要错误归到抓取位姿选择与轨迹规划失败，而不是某个运行时检测器报了警。',
 steps=[('先训一个自己的多模态代码模型', 'RoboCodeX-13B 沿用 BLIP-2 结构：视觉编码器是 EVA-CLIP 的 ViT-G/14（去掉最后一层、改用倒数第二层输出，训练时冻结并转成 FP16），中间用 Q-Former 把视觉 token 压短以容纳很长的 API 文档提示，语言侧是 LLaMA-13B。另加一个视觉适配器：把视觉编码器的隐层按比例分成四段，各取末层的 class token 拼接，经一个通道注意力网络（降维—SiLU—升维）后与其余视觉 token 一起输入。这一层是作者自己设计并训练的，与直接提示 GPT-4V 不是同类系统。'), ('训练数据由大模型在仿真里自动产出', '预训练数据是程序化生成的：从 HM3D 采样家居场景，往合理位置插入 Google Scanned、YCB、OmniObject3D 与 AKB-48 的物体，把场景写成文字交给 GPT-4 生成任务描述与对应代码，每个任务采 10 份、由 GPT-3.5 评分并滤掉语法错误。SFT 阶段以 RT-1 与 LIBERO 的任务类型为基础，对语法正确但执行失败的代码穷举可选设置（中心提举还是 AnyGrasp、偏好接触位置、夹爪方向、轨迹生成方式），把最优项作为标签，再让 GPT-4V 解释为什么它更好并写成注释充当思维链标签。两个阶段都掺入 ShareGPT4V 等通用视觉语言数据以防过拟合。'), ('树状分解：把指令拆成以物体为中心的单元', '观测是三个视角的 RGBD，深度融合成截断符号距离场（TSDF）表示环境结构。模型读这三张 RGB 加指令，输出若干个 object-centric 单元及每个单元的操作偏好 pf——接近方向或偏好接触位置，例如球形物体从中心抓更稳，杯子这类开口容器抓边缘更灵活。这一层只决定“用什么姿态对待这个物体”，不直接给坐标。'), ('每个单元向下展开成四类可以算出来的量', '部件级 affordance 给出任务相关部件的点云分割，例如抽屉把手区域；抓取位姿由现成的 AnyGrasp 生成带分数的候选，取前 10 个，再用推理出的偏好选定一个；物体物理属性由现成的 GAMMA（基于 PointNet++，做部件分割与关节轴回归）从点云估出关节信息；平面与法向量则把 Open3D 的平面检测封装成 API 供代码调用。四类结果最后被编译成结构化的可执行代码。'), ('轨迹与跨平台执行', '轨迹规划用零阶优化：随机采样轨迹，按控制代价与占据栅格约束打分选优，输出是稠密的末端路点序列（每个路点含 6-DoF 位姿、速度与夹爪动作）。执行侧是 ROS 环境里的 MoveIt 与 OMPL 做运动规划，再由操作空间控制器跟踪。换机器人时只改配置文件，论文据此在 Franka Emika Panda 与 UR5 上做了零样本展示。')],
 example='教学推演：回到上面的场景。第一步要先记住读图的是谁：不是被提示的通用大模型，而是作者自己训练过的 RoboCodeX-13B（EVA-CLIP ViT-G/14 加 Q-Former 加 LLaMA-13B，另有一个聚合四段隐层 class token 的视觉适配器）。第二步，它之所以知道抽屉该怎么开，来自那套自动生成的数据——同类任务在仿真里被穷举过“中心提举还是 AnyGrasp”“沿关节轴拉还是只给终点”这些选项，成功的那一项连同 GPT-4V 写的理由一起成了训练标签。第三步，三个视角的 RGBD 融成 TSDF，模型把任务拆成抽屉单元与香蕉单元，并分别给出偏好：抽屉要求夹爪对齐棱柱关节轴，香蕉要求夹爪对齐桌面法向、靠近物体中心。第四步，抽屉单元向下展开：把手区域由部件级分割给出，抓取候选由 AnyGrasp 生成前 10 个再按偏好挑一个，“这是平移关节、轴向朝外”由 GAMMA 从点云估计，桌面法向由 Open3D 的平面检测 API 返回。第五步，这些量被写进代码，轨迹由零阶优化在占据栅格约束下随机采样评分得到，交给 ROS 侧的运动规划与操作空间控制器执行。如果把抽屉当成绕轴旋转的门，生成的代码语法一样正确、执行照样失败——所以读这篇时要追踪的是视觉信息究竟改变了哪一个运动参数，而不是代码写得好不好看。',
 code='I = 三视角 RGBD;  tsdf, occupancy = fuse(I)         # 融出 3D 结构与占据栅格\nunits, prefs = RoboCodeX(RGB×3, instruction)       # 自训 13B 模型：树状分解 + 操作偏好\nfor u, pf in zip(units, prefs):\n    O = 点云(u)                                     # 多视角 2D 框按深度对齐后取物体点云\n    A = affordance(O, u)                            # 部件级分割，如把手区域\n    pc = top10(AnyGrasp(A)); g = 按 pf 选一个        # 现成抓取检测器给候选，偏好定取舍\n    phi = GAMMA(O)                                  # 现成模型：关节类型与轴向\n    n = open3d_plane_normal(O)                      # 封装成 API 的平面检测\n    code = 写出调用序列(g, phi, n, pf)\n    tau = 零阶优化(采样轨迹, 控制代价, occupancy)    # 采样—打分—选优，出稠密路点\n    execute(tau)                                    # ROS 运动规划 + 操作空间控制器',
 setup='主要操作比较在仿真中进行，表 1 报告每类任务 50 次试验的平均成功率；还包含导航基准、一般 VQA 与真实 Franka 展示。不同任务的指标应分开理解。',
 headers=['表 1 任务','GPT-4V','RoboCodeX'],
 rows=[['抓取放置','63%','80%'],['抽屉操作','68%','84%'],['门操作','52%','74%'],['把物体放入抽屉','55%','68%'],['多阶段任务','50%','64%']],
 findings='提高并不均匀：门操作提升 22 个百分点，多阶段提升 14 个百分点。结果支持专门的多模态操作建模，但不意味着所有物理步骤都已可靠；多阶段成功率仍只有 64%。',
 ablation='§4.5 / 图 5 分别研究操作偏好、视觉适配器和一般 VQA 数据。阅读这些消融时应区分“视觉信息更好”“模型经过专门训练”和“代码组织更好”，三者不是同一项改进。',
 boundary='模型来源是混合的：作者自己训练的只有 RoboCodeX 这一个 13B 多模态模型（视觉编码器 EVA-CLIP ViT-G/14 冻结，Q-Former 与 LLaMA-13B 参与训练），而它的训练数据又主要由 GPT-4 与 GPT-4V 在程序化生成的仿真场景里产出；抓取候选来自现成的 AnyGrasp，关节参数来自现成的 GAMMA，平面检测来自 Open3D，运动规划与控制来自 ROS 侧的成熟模块。因此与直接提示 GPT-4V 的比较里同时混着“模型被专门训练过”和“接了一整套几何工具”两种差异，不能据此得出树状分解单独贡献了全部提升。主要操作比较也在仿真中进行，真实 Franka 与 UR5 上只做了跨平台展示。',
 transfer='与 CaP 共同看“程序由谁写、几何由谁算”；与 ReKep 共同看“约束如何表示”。与 CaP-X 比较时还要对齐感知接口与低层原语。',
 exercise='在仿真中保留同一规划器，只替换门 / 抽屉轴向信息为真值、视觉估计和错误估计，观察行为差异。',
 answer='如果轴向误差主导失败，就优先研究感知约束与不确定性处理；仅加长语言推理可能无效。按定位、约束、规划和执行四阶段归因。',
 sources=[('树状生成与训练：§3','S3'),('量化操作实验：§4.1 / 表 1','S4.T1'),('实机展示与消融：§4.4–4.5','S4.SS4')])

add('rekep', version='v2',
 takeaway='将“壶嘴对准杯口、再倾斜”写成关键点间的关系，让优化器求出动作。',
 result='7 项真实任务：自动生成约束 44.3%，人工标注约束 68.6%，VoxPoser 基线 10.0%。',
 why='任务经常不是一个位置目标，而是一组随阶段变化的关系：抓把手、对齐壶嘴、倾斜、保持杯口下方关系。ReKep 用三维语义关键点及其约束函数描述这些要求，在模型的语言推理与机器人连续控制之间建立接口。',
 scene='指令是“把茶壶里的茶倒进杯子”。这件事很难写成一句目标：壶嘴要对准杯口，搬运途中壶得保持竖直，只有到位之后才允许倾斜。写成一个末端目标位姿会丢掉过程中的约束，写成一段轨迹又绑死了这一次的物体位置。',
 recall_module='改的是任务目标的表示形式，以及最终由谁来求解。它既不给末端目标位姿也不给一条轨迹，而是把任务写成关键点之间的关系：分成若干阶段，每阶段配 sub-goal 约束（阶段结束时要满足）与 path 约束（阶段全程要满足），每条约束是一个无状态的 Python 函数，坐标不写死、在调用时才由跟踪器填入，剩下的留给数值优化器。与 RoboCodeX 的对照点在于这套系统没有任何由作者训练的模块——关键点提议用 DINOv2 与 SAM、约束由 GPT-4o 写、抓取候选来自 AnyGrasp、优化用 SciPy；底层也仍是 PyBullet 求逆运动学加 Deoxys 的关节阻抗控制，动作空间与控制器都没有动，阶段骨架同样不在运行中重新生成。',
 recall_io='输入是标定过的 RGB-D 观测与一句指令：先从 DINOv2 特征与 SAM 掩码里聚出候选关键点、投到三维，带编号叠回原图，与指令一起送进 GPT-4o；模型看到的就是这张带编号的图和一段通用说明，提示里没有图文示例，同一掩码内的点由系统记成一个刚体分组，这一步不经过模型。输出是任务需要几个阶段，以及每个阶段的 sub-goal 约束与 path 约束，都写成在关键点数组上做算术的 Python 函数、以 f(k) ≤ 0 表示满足；这些函数不直接交给控制器，而是交给 SciPy 求解器，先解当前阶段的子目标位姿、再解一条到它的路径，首次用 Dual Annealing 配 SLSQP 做全局搜索，之后基于上一解只跑局部优化。失败处理这一篇是有的，而且写得具体：跟踪器以 20 Hz 刷新关键点、每轮重解一次，末端与子目标的距离进入容差就推进阶段，同时每个控制周期都检查当前阶段的 path 约束有没有被违反，一旦违反就逐级回退到 path 约束仍然成立的更早阶段，例如杯子在倒茶途中被人从夹爪里取走。边界也随之清楚：能被发现的只有被写下来的约束所覆盖的那些失败，少写一条 path 约束，优化器照样会给出一条提前倾斜的解，而阶段骨架由 GPT-4o 一次定下，运行中不会重新生成。',
 steps=[('关键点提议：DINOv2 加 SAM，全程不训练', '先用 DINOv2（带 registers 的 ViT-S14）取 patch 级特征，双线性插值放大回原图尺寸；再用 Segment Anything 分出场景中所有掩码。每个掩码内的特征做 k=5 的 k-means（余弦相似度），簇心即候选关键点，经标定过的 RGB-D 相机投到三维，工作区外与彼此过近的点被过滤。同一掩码内的点会被记下来，后续在优化中充当一个刚体分组。'), ('约束生成：让 GPT-4o 写 Python 函数', '候选点带编号叠回原图，与任务指令一起送进 GPT-4o；提示只有通用说明，没有图文示例。模型输出任务需要几个阶段，以及每个阶段的 sub-goal 约束（阶段结束时要满足）和 path 约束（阶段全程要满足）。每条约束是一个无状态的 Python 函数 f(k)，用 NumPy 在关键点数组上做算术，f(k) ≤ 0 表示满足。函数里不写死坐标，只写关系，坐标在调用时由跟踪器填入——这也让模型可以用点之间的算术表达三维旋转，绕开旋转表示与数值计算。'), ('分层求解：先解子目标位姿，再解到达路径', '完整问题被分解成只求当前阶段。子目标问题的决策变量是一个末端位姿（双臂则两个），目标函数里含碰撞、可达性、位姿正则、解的一致性等辅助代价，抓取阶段另外接入 AnyGrasp 的抓取质量；路径问题再从当前位姿求一条到该子目标的轨迹，全程满足 path 约束。两者都用 SciPy 求解，首次用 Dual Annealing 配 SLSQP 做全局搜索（约 1 秒），之后基于上一解只跑局部优化器，约 10 Hz。优化中的前向模型采用刚性假设：被抓的那组关键点随末端做同一刚体变换，其余点视为不动，这个近似只在 0.1 秒的求解窗口内成立。'), ('闭环：跟踪、推进、回退', '关键点位置由一个基于 DINOv2 特征余弦匹配的点跟踪器以 20 Hz 更新，每轮重新求解一次。末端与子目标位姿的距离进入容差就推进到下一阶段；同时每个控制周期都检查当前阶段的 path 约束是否被违反，一旦违反就逐级回退到 path 约束仍然成立的更早阶段，例如杯子在倒茶途中被人从夹爪里取走。阶段骨架本身固定，系统不在运行中重新生成。')],
 example='教学推演：回到上面的场景。第一步，系统还完全不理解任务：DINOv2 的特征加 SAM 的掩码在画面里提出一批候选点，壶柄、壶嘴、杯口各自落上一两个编号点，同属一个掩码的点被记成一组刚体。第二步，带编号的图与这句指令交给 GPT-4o，它给出三个阶段——抓壶、对准、倾倒——并为每个阶段写出 Python 约束：阶段一让末端靠近壶柄；阶段二的 sub-goal 要求壶嘴位于杯口上方，同时配一条 path 约束要求壶在移动途中保持竖直；阶段三的 sub-goal 才把姿态改成倾倒角。关键在于这些函数写的是关系而不是坐标，壶和杯此刻在哪里并不进入函数体。第三步，求解器接手：先解当前阶段的子目标位姿（含碰撞、可达性等辅助代价，抓取阶段再叠上 AnyGrasp 的抓取质量），再解一条到达它的路径；首次全局搜索约 1 秒，之后局部热启动约 10 Hz。第四步，跟踪器以 20 Hz 刷新关键点，每轮重解一次；末端与子目标的距离进入容差就推进阶段，而如果阶段二的“保持竖直”在半途被违反，系统会回退到仍然成立的更早阶段重来。若少写了那条 path 约束，优化器完全可以给出一条提前倾斜、把茶洒在路上的解——它保证的只是被写下来的条件。至于阶段序列本身，这套系统不会改：骨架由 GPT-4o 一次定下，换一套骨架需要重跑关键点提议与 VLM。',
 code='keypoints = kmeans(DINOv2 特征 ∩ SAM 掩码, k=5) → 投到三维   # 现成模型，无训练\nstages = GPT-4o(带编号的图, instruction)                     # 每阶段 C_subgoal / C_path\ni = 1\nwhile i <= len(stages):\n    k = tracker(所有相机)                       # DINOv2 特征余弦匹配，20 Hz\n    if 违反(C_path[i], k):\n        i = 回退到 path 约束仍成立的更早阶段; continue\n    e_goal = argmin 辅助代价(e)   s.t. f(h(k, e)) <= 0, f ∈ C_subgoal[i]\n    path   = argmin 辅助代价(e_t:g) s.t. f(h(k, e)) <= 0, f ∈ C_path[i]\n    execute(path[0])                            # h 为刚体前向模型，仅 0.1 秒内有效\n    if dist(e_now, e_goal) < eps: i += 1        # 达到子目标才推进阶段',
 setup='在带轮单臂与固定双臂平台上测试倒茶、收书、回收罐、封箱、叠衣、装鞋、协作折叠等 7 项任务，每项 10 次；部分任务另加物体位置扰动。Auto 与 Annot. 分别表示自动生成和人工标注约束。',
 headers=['结果设置','VoxPoser','ReKep Auto','ReKep Annot.'],
 rows=[['7 项任务总体','10.0%','44.3%','68.6%'],['倒茶','0/10','3/10','8/10'],['3 项扰动任务总体','6.7%','26.7%','46.7%']],
 findings='最该记住的是 44.3% 与 68.6% 的差距：约束表示可用，不等于系统总能自动提出正确关键点和约束。人工标注结果是诊断生成环节的参考，不能作为全自动系统成绩。',
 ablation='表 1–2 的 Auto / Annot. 对照隔离了一部分约束生成影响；§4.3 的失败分析还指出关键点跟踪、提议与 VLM 推理是主要误差来源。优化器并不是唯一或最大的瓶颈。',
 boundary='模型来源这一层值得单独记：这套系统没有任何由作者训练的模块——关键点提议用 DINOv2 与 SAM，约束由 GPT-4o 写成 Python，抓取候选来自 AnyGrasp，优化用 SciPy 的 Dual Annealing 与 SLSQP，碰撞场用 nvblox 算 ESDF，底层是 PyBullet 求逆运动学加 Deoxys 的关节阻抗控制。代价是系统表现直接绑定这些现成组件：§4.3 的误差分解中点跟踪器造成的失败最多，关键点提议与 VLM 次之，优化器反而不是主要瓶颈。此外关键点前向模型使用刚性近似，遮挡影响跟踪，任务阶段骨架也固定不重生成。服装实验中的“策略成功”和“给定可行策略后的执行成功”有不同条件，不能直接相乘冒充新的实测端到端数值。',
 transfer='它与 VoxPoser 展示两种可解释中间表示；对 Agent 研究者而言，重点是设计能被工具求解、还能定位错误的输出，而不只是长文本解释。',
 exercise='从两点对齐开始，构造一个满足全部已写约束却任务失败的例子，再补上缺失约束。',
 answer='例如点对齐成功但碰撞了旁边物体。这说明优化器保证的是你写下来的条件；任务规范是否完整仍要单独验证。',
 sources=[('约束与求解：§3','S3'),('真实结果：表 1–2','S4.T1'),('误差分解与限制：§4.3–5','S4.SS3')])
add('pi05', version='v1',
 takeaway='让不同机器人、不同场景和语义任务共同训练，策略才能到没见过的家里做事。',
 result='图 12 的搭建家居环境实机测试：四项任务平均进度约 58%–91%；这里测的是进度，不是整任务成功率。',
 why='π₀.₅ 讨论的是策略怎样获得更宽的分布覆盖。相比在测试时不断修改程序，它主要通过数据和训练配方，让模型同时预测高层语义子任务与低层动作。对 Agent 研究者，它提供一个必须了解的背景：外部规划器所调用的策略究竟已经学到了什么。',
 scene='让机器人去一个训练里没出现过的厨房，指令只有一句“把餐具放进水槽”。这里同时缺两样东西：它要认得没见过的盘子和水槽，还要知道在一间陌生厨房里“下一件该收什么”。只在少数固定场地采数据训出来的策略，换个家就两样都对不上。',
 recall_module='改的是策略本身，具体是动作表示与训练数据混合，而不是在策略外面加一层编排。同一个模型的两端各出一种输出：PaliGemma 主干输出文本形式的高层子任务，旁边 300M 的动作专家输出连续动作块，分布被分解成 π(a, ℓ̂ | o, ℓ) = π(ℓ̂ | o, ℓ)·π(a | o, ℓ̂)，低层只看被选中的子任务、不看总指令；能力来自预训练把五类数据压成同一种离散 token 一起训、后训练再接上流匹配的动作专家。动作之后那一段完全没有改：输出直接是双臂关节或末端目标位姿、夹爪、躯干升降与底盘速度，以 50 Hz 交给简单的 PD 控制器，没有轨迹规划也没有碰撞检测，系统里也没有技能库或外部规划器——零样本提示 GPT-4 充当高层反而不如自家高层，高层消融还显示把子任务数据放进训练、推理时不显式使用已能拿到相当一部分收益。',
 recall_io='输入是多路相机图像、离散化后当文本 token 输入的本体状态，以及任务指令，高层用四路图像、低层用腕部与前向相机，全部进同一个模型，没有外部感知模块先把场景转成结构化表示。输出分两级：先自回归解码出一句文本子任务，再以它为条件做 10 步流匹配去噪，产出长 50 的连续动作块，18 至 19 维，以 50 Hz 下发给 PD 控制器执行，高层推理的频率低于低层。失败处理这一条要明确写出来：这篇没有成功检测器、没有验证器、也没有失败后的恢复动作；一块动作执行完就看新观测重新预测子任务，上一段没做成时的纠正只能来自高层在新观测下再次选中同一个子任务，而不是来自任何判定失败的模块。也正因为缺这条通路，实机评测按各任务的评分规则统计完成进度而不是整任务成功率；换到陌生的家里，变的是场景与物体外观，动作仍取自这套数据里已有的家务技能分布。',
 steps=[('一个模型，两种输出', '主干是现成的 PaliGemma 视觉语言模型（2B，宽 2048、18 层），旁边接一个 300M 的动作专家（宽 1024）。输入是多路相机图像、离散化后当文本 token 输入的本体状态，以及任务指令；输出被劈成两半：前面是文本 logits，用来采样高层子任务，后面若干 token 由动作专家产出并线性投影成连续动作块。注意力上信息单向从主干流向动作专家，两种动作表示互不相看以避免泄漏。分布被分解成 π(a, ℓ̂ | o, ℓ) = π(ℓ̂ | o, ℓ)·π(a | o, ℓ̂)，也就是低层只看被选中的子任务，不看总指令。'), ('预训练：一切都当离散 token，混五类数据', '第一阶段是标准的自回归 next-token prediction，机器人动作用 FAST 动作分词器压成离散 token，与文本、物体框一视同仁。数据有五类：约 400 小时、约 100 个真实家庭的移动操作数据（MM）；各种家庭环境中的非移动单臂/双臂数据（ME）；实验室里的跨本体数据，含开源的 OXE（CE）；人工标注的高层子任务预测，模型还要先预测相关物体框再预测子任务（HL）；以及网页多模态数据，包括图像描述、问答与物体定位（WD）。动作按各数据集自身 1% 与 99% 分位归一化到 [-1, 1]，维度补零对齐到最大的动作空间。这一阶段训练 28 万步。'), ('后训练：接上流匹配动作专家', '第二阶段随机初始化动作专家，用流匹配训练：取 a^{τ,ω} = τa + (1-τ)ω、ω 采自标准正态，让模型预测向量场 ω - a，与文本交叉熵按 α = 10 相加成一个损失，再训 8 万步。数据收窄到 MM 与 ME 中长度受限的成功片段，保留网页数据与多环境那部分 HL，另加口头指令（VI）：由人实时用语言遥控已训好的低层策略，把选得好的子任务记录成高层示范。离散 token 训得快、连续流匹配推得快，这一步的作用就是把两者接起来。'), ('运行：先出子任务，再出动作块', '每次推理先自回归解码文本得到子任务（例如 pick up the plate），再以它为条件做 10 步流匹配去噪，产出一段长 50 的动作块。高层推理的频率低于低层动作推理。动作直接是双臂的关节或末端目标位姿、夹爪、躯干升降与底盘速度，共 18 至 19 维，以 50 Hz 下发给简单的 PD 控制器，没有额外的轨迹规划或碰撞检测；一块执行完再看新观测、重新预测子任务。')],
 example='教学推演：回到上面的场景。第一步，接住这句话的不是“一个规划器加一个策略”，而是同一个模型的两端：PaliGemma 主干读四路相机与本体状态先输出文本，3 亿参数的动作专家再输出连续动作；两级共享权重，低层只看被选中的子任务，不看总指令。第二步，它能认出没见过的盘子，靠的是预训练把五类信号压成同一种离散 token 一起训——本体的移动操作数据、别的机器人与实验室数据、人工标注的子任务、以及网页上的图文问答与物体定位，盘子的外观知识多半来自最后这一类。第三步，后训练才换成流匹配：动作专家从随机初始化开始学着把噪声还原成动作块，同时保留文本损失，并额外吃进人用语言实时遥控真实策略时留下的子任务示范——这正是让它在陌生厨房里挑对“下一件该收什么”的那部分数据。第四步，运行时模型先解码出 pick up the plate，再以这句为条件做 10 步去噪生成一段 50 步的动作块，以 50 Hz 交给 PD 控制器，中间没有轨迹规划也没有碰撞检测；一块做完再看新观测、重新预测子任务，如此推进到任务结束。要注意“陌生家庭”变的是场景与物体外观，动作仍来自这套数据里已有的家务技能分布；论文的高层消融还显示，把子任务数据放进训练但推理时不显式使用（implicit HL）已经能拿到相当一部分收益，说明这部分好处不全在运行时多了一个 planner。',
 code='backbone = PaliGemma-2B(现成 VLM) + action_expert-300M(后训练时随机初始化)\n# 预训练 280k 步：MM + ME + CE + HL + WD，动作经 FAST 压成离散 token，纯 next-token\n# 后训练 80k 步：MM/ME 成功片段 + WD + HL + VI(人用语言遥控留下的子任务示范)\n#   损失 = 文本交叉熵 + α · ||(ω - a) - f_a(a^{τ,ω}, o, ℓ)||²,  α = 10\n\nwhile 任务未完成:\n    o = (四路图像, 本体状态)                   # 高层用四路；低层用腕部与前向相机\n    l_hat = decode_text(backbone, o, 总指令)   # 高层子任务，推理频率低于低层\n    a = flow_match(action_expert, o, l_hat, steps=10)   # 长 50 的连续动作块\n    执行(a)   # 18-19 维：双臂关节/末端、夹爪、躯干升降、底盘速度，50 Hz PD 跟踪',
 setup='作者在未见过的真实家庭与搭建的家居房间测试移动操作。图 12 比较四项任务，每策略每任务通常 10 次，按各任务评分规则统计完成进度。下列数值为从图 12 读取的约值，不是原始表格精确值。',
 headers=['图 12 · 平均任务进度（约）','π₀ 300k','π₀-FAST+Flow（无高层）','π₀.₅'],
 rows=[['餐具放入水槽','41%','55%','91%'],['物品放入抽屉','33%','71%','85%'],['衣物放入篮子','31%','73%','80%'],['整理床铺','20%','48%','58%']],
 findings='整理床铺仍明显难于收餐具。图 7 中三个真实家庭的各任务平均进度约为 65%–94%；不同任务评分、场景和误差条都需保留理解，不能浓缩成一个“家庭任务成功率 90%”。',
 ablation='图 13 显示：保留高层预测训练数据、但推理时不用显式高层的 implicit HL 仍表现较强；去掉这类训练信号更差。这说明收益部分来自共同训练，不能全部解释成推理时多了一个 planner。',
 boundary='模型来源与前提成本要一起看：接入的现成部分只有 PaliGemma 这个 2B 视觉语言主干，其余都由作者训练——预训练 28 万步、后训练 8 万步，3 亿参数的动作专家在后训练阶段从随机初始化开始学，FAST 离散动作表示与流匹配也都在自家训练流程里，而不是运行时调用的外部工具。数据同样是前提：约 400 小时、约 100 个家庭的移动操作数据，加上跨本体与网页数据；其中口头指令只占高层移动操作样本的约 11%，去掉却会让表现明显下降。论文里零样本提示 GPT-4 充当高层策略反而不如自家高层，说明这一级的能力来自领域内训练，而不是通用推理。因此“未见家庭”不等于“没有相关技能数据”，新场景泛化、新物体泛化和新运动技能泛化应分别讨论。',
 transfer='与 AtomicVLA 对照：两者都让语义规划接到动作生成，AtomicVLA 进一步把动作端组织为技能专家。与 Harness VLA 对照：后者主要改变冻结策略之外的运行方式。',
 exercise='复现不一定要从头训练大模型。可以固定公开策略，按新背景、新物体、新布局三条轴测试，并同时记录子任务完成进度与整任务成功率。',
 answer='若进度提升但最终成功率变化小，要检查末尾步骤与错误恢复。一个完成九成步骤的策略，对用户可能仍意味着任务未完成。',
 sources=[('训练配方：§IV','S4'),('模型对比：图 12','S5.F12'),('真实家庭：图 7；高层消融：图 13','S5'),('评估评分：附录 A-B','A1')])

add('roboos', version='v2',
 takeaway='多机器人协作需要共享任务依赖、世界状态和各自能力，不能只把多个 Agent 放在一起。',
 result='多机器人规划工具调用准确率：RoboBrain-7B-1.5-OS 81.74，DeepSeek-V3 76.21；这不是协作实机成功率。',
 why='一个机器人能规划，不代表两个机器人就能有效配合。RoboOS 把认知、技能执行和共享记忆拆开，以统一的机器人与工具描述连接异构本体。读这篇要理解任务分配依据和同步过程，而不只记“具身操作系统”这个名字。',
 scene='按论文餐厅演示的配置，一台 Unitree G1 人形与一台 Agilex 双臂机器人协作处理“我饿了，来一个普通汉堡”。两台机器人本体不同、技能不同，还必须知道对方做到哪一步。把两个各自会规划的 Agent 放在一起并不够：任务依赖、世界状态与各自能力都得是共享的。',
 recall_module='这篇动的不是机器人会做什么，而是多台异构本体之间用什么格式互相看见对方：接入侧被规定成标准化的 Robot Profile 与工具描述，世界状态被收进一份由 Redis 承载的共享记忆，任务依赖、环境事实与各自能力因此成为共用的东西，而不是每台机器人各持一份。它没有训练任何一条底层技能，小脑技能库里的抓取、VLA 策略与导航管线都是现成组件按这层格式接进来的，动作空间与控制器保持原样，本体的能力边界一点没变。自训的部分只在大脑侧的 RoboBrain-1.5-OS，而它学的也是分工与工具调用，不是运动。',
 recall_io='输入是全局指令 T_global，加上四样由外部系统备好的东西：RAG 检索共享空间记忆得到的环境信息 M_s、时序记忆里的历史执行反馈 M_t、各机器人当前状态 S_r（空闲、忙碌或离线）、以及技能库 M_r；大脑看到的是这些结构化描述，场景图由多视角 RGB-D 经 SAM 分割与 CLIP 特征在系统侧建好，原始图像流并不直接进它的输入。输出是一段推理轨迹与一张子任务图 G，节点标注执行深度与承担者，分单机器人子任务与需要多台协同的协作子任务，交给 Monitor 按拓扑深度决定并行下发还是阻塞，每个节点再由一个专属 Robotic Agent 从小脑技能库里选工具去执行。失败由该子任务的 Robotic Agent 自己发现，依据是此前执行的反馈、工具调用历史与环境的局部空间记忆，处理方式是换候选位置重试：厨房里没检测到鸡蛋，就据空间记忆推断冰箱这类位置、改调导航工具过去，动作结果实时改写场景图的节点属性与空间边，反馈写入时序记忆，影响下一轮调度。这条通路里没有独立于执行者的验收环节，子任务算不算完成由同一个 Agent 凭自己拿到的工具反馈判定；共享记忆一旦过期，依赖排序看起来依然流畅，分工却已经错了。',
 steps=[('先固定接入格式：Robot Profile 与小脑技能库', 'Cerebellum Skill Library 部署在各机器人终端，通过标准化的 Robot Profile 与工具描述接入系统。库里的工具基本都是现成组件：操作侧包含专家式抓取（AffordGrasp、AnyGrasp）与 VLA 类策略（OpenVLA、RDT-1B、Octo、π₀），导航侧包含传统的建图—定位—导航管线（SLAM）与视觉语言导航工具（MapNav、NaVid），另有灵巧手、接触密集与柔性物体等专用技能。RoboOS 自己不训练这些底层技能，它规定的是接入格式与调用接口。'), ('大脑：在 Qwen2.5-VL-7B 上三段训练出的 RoboBrain-1.5-OS', '论文明说云端大脑可以换成任意 MLLM，而作者自己训练的版本是 RoboBrain-1.5-OS：以预训练 Qwen2.5-VL-7B 为底座做全参数训练，Stage-1 用 300 万条通用 VLM 数据建立感知与推理，Stage-2 用 230 万条机器人数据（规划、指点、可供性、轨迹四类能力）并保留 10% 的 Stage-1 数据防遗忘，Stage-3 先用 245K 的 OS-SFT 样本，再对 4K 条纯工具调用样本做 GRPO。Stage-3 的数据是合成的：用 DeepSeek-V3-0324 在超市、家居、餐厅三类场景的 68 种协作任务类型上生成 Multi-Robot-45k（每条含场景图、机器人规格与长程协作任务，答案是推理过程与子任务工作流图），再派生出带概率注入错误负样本的 Robotic-Agent-144k。'), ('分解：先检索共享记忆，再产出带依赖的子任务图', '收到全局指令 T_global 后，RoboBrain 先对共享空间记忆做一次 RAG 检索得到环境信息 M_s，再与时序记忆里的历史执行反馈 M_t、各机器人状态 S_r（空闲 / 忙碌 / 离线）、技能库 M_r 一起拼接输入，输出一段推理轨迹和一张子任务图 G。共享记忆的空间部分是分层动态场景图（楼层—房间—物体三级节点，边表示空间或功能关系），由多视角 RGB-D 经 SAM 分割与 CLIP 特征构建，再用几何聚类与开放词表 grounding 合并，整体由 Redis 承载。'), ('调度：Monitor 按拓扑深度决定并行还是阻塞', 'G 是有向无环图，每个子任务标注执行深度 d 与承担者，分两类：单机器人子任务 (d, r_i) 和需要多台协同的协作子任务 (d, r_{i:j})。Monitor 对同一深度的独立子任务做并行下发，对深度 d+1 的子任务做顺序阻塞——它要等 d 层的全部前置完成才解锁。系统还支持同时管理多张子任务图，以应对机器人状态和任务依赖的动态变化。'), ('执行与回写：每个子任务一个 Agent，记忆随动作增量更新', '每个子任务配一个专属 Robotic Agent，依据三样东西自行从技能库选工具：此前执行的反馈、工具调用历史、以及环境的局部空间记忆。论文给的例子是“找一个鸡蛋并放到桌上”——厨房里没检测到鸡蛋时，Agent 用空间记忆推断冰箱这类可能位置，改调导航工具过去，这就是它所谓的闭环恢复。动作产生的效果实时改写场景图的节点属性与空间边（如把杯子放上架子后更新位置与支撑关系），并做遮挡与历史感知的修正；反馈与工具调用记录写入时序记忆，关节与电量等状态写入机器人记忆，共同影响下一轮调度。')],
 example='教学推演：回到上面的场景。第一步，两台机器人在注册时各自提交 Robot Profile，人形挂着导航与搬运类工具，双臂挂着 VLA 类抓取工具；大脑看到的是这些标准化描述，而不是各自的关节接口——换一台新本体意味着补一份 Profile 和一批已接入技能，不是零适配。第二步，大脑是 RoboBrain-1.5-OS。它之所以能直接输出“谁做哪一段”，不是因为通用 VLM 天然会分工，而是因为 Stage-3 专门用 DeepSeek-V3 合成的多机协作与工具调用数据训过；换成未经这类训练的模型，表 1 里的差距就是代价。第三步，大脑先 RAG 检索空间记忆确认食材与餐盘在哪、时序记忆里上一轮做到哪、两台机器人当前是空闲还是忙碌，然后吐出子任务图：备餐在人形侧，取餐与递送在双臂侧，递送依赖备餐完成。第四步，Monitor 看拓扑深度——备餐与擦拭台面同在第一层可以并行，递送在第二层被阻塞，直到备餐节点回报完成才解锁。第五步，各子任务的 Agent 自己选工具；若“检测汉堡”失败，Agent 不会硬重试，而是查空间记忆里还有哪些候选位置并改调导航工具，动作结果又立刻改写场景图的节点与边，供下一次调度使用。整套流程里，决定协作成败的其实是第三步和第五步之间的一致性：如果场景图仍把托盘记在厨房，第四步的依赖排序看起来依然流畅，分工却已经错了。这个推演不代表论文测量过这条具体流程，表 1 的 81.74 衡量的也只是大脑侧的工具调用准确率。',
 code='robots：每台注册时提交 Robot Profile（本体、技能库 Mr、状态 Sr）\nmemory = Redis(空间=分层场景图, 时序=反馈与调用史, 机器人=关节/电量)\nR, G = RoboBrain(RAG(空间记忆) ⊕ Mt ⊕ Sr ⊕ Mr ⊕ T_global)  # 推理轨迹 + 子任务图\nwhile G 中仍有未完成节点:\n    ready = [n for n in G if n 的所有上游深度已完成]   # 同深度并行，跨深度阻塞\n    for n in ready:                      # 单机 (d, ri) 或协作 (d, ri:j)\n        agent = RoboticAgent(n)\n        while n 未被判定完成:\n            tool = agent.select(时序反馈, 调用历史, 局部场景图)\n            fb = execute(tool)           # 小脑：AnyGrasp / OpenVLA / π0 / SLAM / MapNav\n            memory.更新(场景图节点与边, fb, 机器人状态)  # 失败则据空间记忆改选工具\n    # 记忆变化后，大脑可对剩余子图重新规划',
 setup='表 1 比较具身模型的多机器人规划、指点、可供性和轨迹预测。规划部分在餐厅、家居、超市三类场景各采样生成 200 个任务，以工具调用准确率 AR 评估；实机协作另见 §4.3 的演示。',
 headers=['表 1 规划模型','餐厅','家居','超市','平均 AR'],
 rows=[['Qwen2.5-VL-7B','43.22','59.30','58.29','53.60'],['DeepSeek-V3-685B','69.85','83.92','74.87','76.21'],['RoboBrain-7B-1.5-OS','78.39','86.93','79.90','81.74']],
 findings='81.74 衡量的是规划 / 工具调用层面的表现。论文同时提供跨本体协作演示，但这个表不能证明多台机器人完整完成真实任务的概率是 81.74%。',
 ablation='本文主要证据是模型能力比较、系统部署和协作展示；这些不能替代“去掉共享记忆”后的同预算端到端对照。把共享记忆视为架构设计的合理机制，与认定它的独立贡献已经量化，是两件不同的事。',
 boundary='模型来源是混合的，读这篇时要把两侧成本分开算。小脑侧全部是现成组件（AnyGrasp、AffordGrasp、OpenVLA、RDT-1B、Octo、π₀、SLAM、MapNav、NaVid 等），RoboOS 不训练它们，只规定 Robot Profile 与工具描述这层接入格式；大脑侧的 RoboBrain-1.5-OS 则是作者在预训练 Qwen2.5-VL-7B 上做的全参数三阶段训练，Stage-1 与 Stage-2 用了 20 台 8×A800 服务器，这是系统真正的前提成本。还要注意表 1 的 81.74 评的是这个自训大脑的工具调用准确率，不是整套系统的协作成功率；换成现成的 DeepSeek-V3-685B 是 76.21，说明这层可替换但有代价。Stage-3 的训练数据由 DeepSeek-V3-0324 合成，评测用的多机规划任务同样是在这三类场景里采样生成的每场景 200 条，论文没有说明两者的生成流程是否完全独立。此外不同机器人仍需已接入的技能和标准化 Robot Profile，跨本体支持不等于任意新机器人零适配；状态冲突、通信延迟和技能前置条件都会影响最终协作。',
 transfer='结合 SayPlan 看空间记忆，结合 PhyAgentOS 看执行生命周期。RoboHarness 则把注意力放在不同策略之间交接时的状态分布。',
 exercise='用两个仿真 worker 共享物体状态，加入一个“搬运后才能加工”的任务依赖，比较即时更新和延迟更新。',
 answer='统计重复工作、无效调用、依赖违反和总用时，比只记录任务分解文本是否合理更能评价协作。',
 sources=[('架构与调度：§3','S3'),('能力评估：表 1 / §4','S4.T1'),('规划基准的 AR 定义：附录 B','A2')])

add('atomicvla', version='v2',
 takeaway='在 VLA 内部显式区分“思考”和“行动”，再按原子技能路由到动作专家。',
 result='LIBERO-LONG：π₀ 85.2% → AtomicVLA 95.2%；π₀.₅ 92.4% → AtomicVLA* 96.2%。',
 why='当所有动作混在一个解码器里，新技能学习可能干扰旧技能，长任务也难以显式跟踪进度。AtomicVLA 在模型内部加入任务链、当前进度和原子技能抽象，并以技能引导的混合专家组织动作生成。这里的技能是一组参数化专家。',
 scene='取论文真机长程任务之一“把盘子放进微波炉并关门”。这条任务要连着做好几段性质不同的动作——靠近、抓起、送入、关门——其中关门不需要闭合夹爪，抓起却必须闭合。全部混在一个动作解码器里训练，这两件事会互相干扰，长任务也无从跟踪进度。',
 recall_module='改动全部发生在一个 VLA 内部：动作生成不再由单个解码器包办，而是每一步先由模型自己吐出 [think] 或 [act] 决定这一步说话还是动手，再把 think 给出的原子技能抽象压成 Z_σ 当作路由条件，由 SG-MoE 把这一段交给某一个技能专家，共享专家则继承基座原有的动作生成能力。换个说法，被重新划分的是动作生成的内部分工边界，而不是这个策略对外的样子：观测与指令的入口没变，动作块这种输出形式没变，末端的动作空间与底层控制器都没动，模型外面也没有新挂规划器或验证器，任务链与进度都写在同一个模型自己的输出里。代价是它不是在基座上挂一个轻量模块，技能专家从随机初始化开始训，基座仍要重训一遍。',
 recall_io='模型直接看到的输入是多路相机观测 O_t、语言指令 ℓ 与本体感知状态 s_t；训练期那批原子技能标签由主轴分析切段、再由现成的 InternVideo2.5 校正，属于数据侧的外部供给，推理时并不在环。输出分两种形态：think 模式以文本给出整条任务链、当前执行进度与接下来要做的原子技能抽象 σ，act 模式用最近一次 think 留下的 σ 加上 s_t 产出一段动作块，直接下发给机器人，中间没有第二个执行者。一次失败由模型自己在 think 时重新判定：执行中出现异常（原文举的是黄油抓起后又掉落），模型重新 think、改写进度并重发同一个 σ，从而回到同一项技能重做。这里没有独立的验证者，异常与完成都由同一个模型凭观测判断；更要紧的是路由只看 Z_σ，σ 一旦错了，相关 token 会被稳定地送进错误的专家，而这层错误在动作层面看不出来，原文也把路由上限归到 VLM 产生准确原子技能抽象的能力上。',
 steps=[('每一步先输出 [think] 或 [act]，由模型自己决定模态', '推理循环的每一步，模型先根据多路相机观测与语言指令预测一个标识 token。预测到 [think] 就进入思考模式，以文本形式输出三样东西：整条任务链 C_{0-k}、当前执行进度 C_t、以及接下来要做的原子技能抽象 σ；论文说这种模式通常只在任务开始或子技能切换这类关键时刻触发。预测到 [act] 就进入行动模式，用最近一次 think 留下的 σ 加上当前本体感知状态 s_t 生成一段动作块 A_t。算法 1 的循环条件写的是“任务未完成”；执行中若出现异常（论文举的例子是黄油抓起后又掉落），模型会重新 think、改写进度并重发 σ，从而回到同一技能重做。'), ('技能抽象先压成一个标量，再嵌成路由条件', '每项原子技能抽象被映射到一个标量“噪声级” σ ∈ [0, 100]，再经 Z_σ = E(norm(log σ)) 嵌成高维向量。这个编码方式是借扩散去噪模型里噪声调度的做法，目的是让不同技能在嵌入空间里拉开距离。映射是确定性的，同一项技能永远得到同一个 Z_σ，所以路由不依赖模型每次对技能名称的重新理解。'), ('SG-MoE：只看 Z_σ 做 top-1 路由，再与共享专家加权相加', '路由器的输入只有 Z_σ，输出各专家分数 w_k = Router(Z_σ)，采用稀疏激活策略，只选得分最高的那一个技能专家。最终动作块是共享专家与被选专家的加权和：F_out = (1 − w_k)·F_share(x_t) + w_k·F_k(x_t)，其中 x_t 是 [多路观测, 指令, 本体状态]。共享专家承载基座 π₀ 原有的动作生成能力，技能专家各自按 Gemma 结构实现（前馈用独立的 SwiGLU MLP），训练开始时全部随机初始化。LIBERO 与真机实验用 5 个技能专家，CALVIN 因任务词表更广用 8 个。'), ('技能标签怎么来：主轴分析切段，再让 InternVideo2.5 校正', '原子技能的监督不是人工标注的。作者先对末端执行器轨迹做主轴分析：在连续五帧内比较平移量（Δx, Δy, Δz，阈值 3 厘米）、旋转量（Δroll, Δpitch, Δyaw，阈值 0.05 弧度）与夹爪变化（阈值 0.1）的主导分量——例如 z 坐标持续下降且夹爪闭合判为 pick，位移很小但旋转明显且夹爪保持闭合判为 turn。切出的片段再交给现成的视频理解模型 InternVideo2.5 看，自动校正与补全语义标签，最后与完整轨迹对齐成“已执行的原子动作序列 + 后续高层计划”的推理链。LIBERO 上由此得到 Pick / Place / Open / Close / Turn 五类，条数分别为 2462、761、201、152、175，少数类靠提高采样频率来平衡。'), ('扩展新技能：只训新专家与新路由分支', '遇到训练时没见过的技能，做法是给现有架构加一个对应专家并扩展路由网络，已有专家保持不变。扩展后的路由器直接复制原路由器权重，新增的路由分支用小随机值初始化，让模型以较少微调就适应变大的技能集。真机的持续学习实验就是这样做的：先在四个短任务上混合训练 20k 步，再以 5×10⁻⁶ 的学习率单独训练 7k 步来学“打开顶层抽屉”这项新技能。')],
 example='教学推演：回到上面的场景。第一步，开局模型预测到 [think]，输出整条任务链（靠近盘子 → 抓起 → 送入微波炉 → 关门）、当前进度停在第一段、以及下一项原子技能 pick。第二步，pick 这个抽象被确定性地映射到一个固定标量，再嵌成向量 Z_σ；之后每次路由只看这个向量，不需要模型重新读懂“pick”这个词。第三步，路由器据 Z_σ 稀疏地选中 pick 专家，动作由共享专家（继承自 π₀.₅ 基座的通用动作能力）与 pick 专家按路由分数加权相加产生；接着模型连续吐出 [act]，直到抓取这一段走完，中间不再思考。第四步值得倒着看一遍：这段“pick”标签当初是怎么来的——训练时主轴分析发现 z 持续下降且夹爪闭合，把这一小段切出来标为 pick，再由 InternVideo2.5 核对。也就是说，专家的分工来自轨迹的运动学特征加一个现成视频模型的复核，不是人事先设计的技能表。第五步，若之后还要加“打开抽屉”，只需新增一个专家并复制扩展路由分支，其余专家不动。论文强调的收益也正在这里：混合训练时“开抽屉不需要闭合夹爪”这件事会污染其他抓取任务的夹爪行为，显式的专家边界把这种干扰隔开。这套机制没做到的是保证 σ 本身正确——路由完全听命于 think 给出的抽象，σ 一旦错了，路由会稳定地把所有相关 token 送进错误的专家，而这层错误在动作层面看不出来。论文附录也把这一点列为限制：技能路由的上限受 VLM 自身的推理与规划保真度约束。',
 code='Atomic = none\nwhile 任务未完成:                          # 算法 1 的终止条件\n    M = vla.predict_token(O_t, ℓ)          # 每步先决定输出模态\n    if M == [think]:\n        chain, progress, σ = vla.thinking(O_t, ℓ)   # 任务链 / 进度 / 原子技能\n        Atomic = σ                         # 执行异常时也走这里，重发 σ 以恢复\n    elif M == [act]:\n        Z = E(norm(log(scalar(Atomic))))            # 技能→标量→确定性嵌入\n        w, k = Router(Z)                            # 只看 Z，top-1 稀疏激活\n        F = (1 - w) * F_share(x_t) + w * F_k(x_t)   # x_t = [O_t, ℓ, s_t]\n        execute(F)                         # F_share 来自 π0 / π0.5 基座\n    t += 1\n\n# 扩展：加一个 F_new 并扩展 Router 分支（复制旧权重 + 小随机初始化），旧专家不动',
 setup='v2 报告 LIBERO、CALVIN ABC→D 及真实 Franka 实验。AtomicVLA 基于 π₀，带 * 的 AtomicVLA* 基于 π₀.₅；这两组必须分别与自己的基座比较。',
 headers=['表 1–2','LIBERO 平均','LIBERO-LONG','CALVIN 平均完成长度'],
 rows=[['π₀','94.2%','85.2%','3.87'],['AtomicVLA','96.6%','95.2%','4.09'],['π₀.₅','96.9%','92.4%','4.02'],['AtomicVLA*','97.8%','96.2%','4.27']],
 findings='长任务改善幅度大于 LIBERO 总平均；同样不能把 * 版本与 π₀ 的差距全部当成技能结构的收益。真实长任务表 3 中，π₀.₅ 为 45%，AtomicVLA* 为 63.3%，相差 18.3 个百分点。',
 ablation='表 5 的 LIBERO-LONG：π₀ 85.2%，普通 MoE 88.6%，MoDE 89.5%，技能引导 SG-MoE 95.2%。这比“加专家就会更好”的解释更细，但还需要考虑模型规模与推理成本。',
 boundary='模型来源是混合的：基座 π₀（AtomicVLA）与 π₀.₅（AtomicVLA*）是现成的通用机器人策略，共享专家直接继承它们的动作生成能力；技能专家则全部随机初始化、由作者训练（LIBERO 与 CALVIN 各 10 万步迭代，真机 3 万步，batch 64，8 张 H200）。标注侧接入的 InternVideo2.5 也是现成模型，只在数据生成阶段校正技能标签，不参与推理时的控制。因此这篇的前提成本是“一个可用的 VLA 基座加一次全量重训”，不是在基座上挂一个轻量模块；论文附录也承认新技能仍需相当量的人类示范做模仿学习。语义专家结构还依赖技能标签的质量、路由的准确性和训练覆盖，附录明确指出路由的上限受 VLM 产生准确原子技能抽象的能力约束。持续学习表 4 显示旧技能平均下降从 15.0 个百分点缩小到 1.3 个百分点，支持该设置下的抗遗忘，但不能据此宣称永不遗忘。',
 transfer='把 AtomicVLA、Voyager、ASPIRE 的技能载体并排写下来：参数专家、可执行函数、修复知识。它们的更新、迁移、验证方式都不同。',
 exercise='若有训练算力，固定参数或计算预算比较普通 MoE 与语义路由；算力有限时，先分析技能路由错误会怎样传播到长任务。',
 answer='最好同时报告路由准确率、单技能成功率、长链成功率和旧技能保留率。只测新增技能，无法回答持续学习是否真的有效。',
 sources=[('方法：§3','S3'),('仿真：表 1–2','S3.T1'),('实机、持续学习与消融：表 3–5','S4')])

add('roboclaw', version='v3',
 takeaway='一次正向操作配一个逆向复位，机器人才能更连续地为自己采集训练数据。',
 result='图 4 的第 5 轮长程整理任务：RoboClaw 约 30%，直接 VLA 基线约 5%；人工采集耗时约为它的 2.16 倍。',
 why='实体机器人学习的瓶颈常常不是缺少下一步计划，而是每做一次实验就要人来复位。RoboClaw 用同一 VLM Agent 连起采集、训练和部署，引入 Entangled Action Pairs（EAP）：正向任务改变场景，逆向策略把场景带回可再次练习的状态。',
 scene='取论文四项单技能里最难的“口红插入窄槽”。想练这条技能就得反复采数据，而每插进去一次，现场就变了：口红留在槽里，下一次演示无法开始。靠人把它取回来，采集速度就卡在人手上。',
 recall_module='这篇改的不是机器人怎么做事，而是训练数据怎么源源不断地来：每项技能被要求配一条逆向复位策略，正向执行改变了场景之后由复位把场景带回可以再练一次的前置区域，两段合成纠缠对一起入库，采集、训练与部署被同一个 Agent 和同一套 MCP 工具接口串成一个环，Agent 只在角色身份上切换。它没有改动作空间，也没有换控制器：策略仍是在现成 π₀.₅ 上做 LoRA 微调，高层决策接的是一个现成 VLM、不为机器人微调。被重新设计的是环路本身，以及谁负责把现场恢复到可以再采一条数据的状态；逆向任务还被刻意设计得比正向任务简单，因为它只需要可靠，不需要困难。',
 recall_io='Agent 看到的输入是观测 o_t 与结构化记忆 m_t = (r_t, g_t, w_t)：角色身份规定当前是数据采集模式还是任务执行模式以及可用工具集，任务级记忆记全局任务、拆出的子任务及各自执行状态，工作记忆记当前激活的技能与工具调用历史；关节层面的东西它看不到，环境摘要与机器人状态由 MCP 工具回报，条件策略用的语言指令也不是人给的，是 Agent 调工具时现生成的结构化子任务描述。输出是一次工具调用，落地形式是一次策略启停，低层动作由 π₀.₅ 的 LoRA 检查点产出；采集侧真正的产物是纠缠对，正向轨迹与复位轨迹成对写进数据集 D，每轮攒够新轨迹就重做一次 LoRA 微调。一次失败先由同一个 VLM 凭观测判定，再分两类处理：非降级失败（抓空但瓶子仍直立、位姿基本没变）直接重试同一条策略，降级失败（瓶子倒了或滑出前置区）必须先跑恢复动作，或用 Change Policy 换一条，自主恢复无效与触发安全条件时 Call Human 上报。系统里没有独立验证器，子任务成功与否就是那个 VLM 说了算，判错会把一条失败轨迹当正样本写进 D、污染下一轮微调；此外复位策略本身也会失败，采集环路会断在这里。',
 steps=[('三层抽象：Skills 调 Tools，Tools 调 Policies', '系统自上而下分成三层。最底层 Policies 是产生低层电机动作的机器人基础模型，这里由 VLA 模型 π₀.₅ 担任；中间层 Tools 是通过 Model Context Protocol（MCP）暴露的系统接口，包括 Start Policy、Terminate Policy、Change Policy、Env Summary、Fetch Robot Stats、Call Human；最上层 Skills 是编排这些工具的可复用流程，例如一个“长程执行”技能会先调 Env Summary 再调 Start Policy。做决策的是一个现成 VLM，以 in-context learning 的方式工作、不为机器人做微调，但论文没有给出它的具体型号与规模。'), ('记忆三件套驱动的 CoT 决策循环', '每个时间步 t，Agent 维护一个结构化记忆 m_t = (r_t, g_t, w_t)：r_t 是角色身份，规定当前是数据采集模式还是任务执行模式以及可用工具集；g_t 是任务级记忆，记录全局任务、拆出的子任务及各自的执行状态；w_t 是工作记忆，存当前激活的技能与工具调用历史。VLM 结合观测 o_t 与 m_t 做链式推理，顺序固定：先解读场景、再确定当前子任务与它的成功判据、再评估当前状态是否达标或需要纠正、最后决定下一个动作。结果写回记忆，形成感知—推理—动作的持续循环。'), ('EAP：每条正向策略配一条逆向复位策略', '对每项技能 k 都学两条策略，正向执行 π→_{θk} 与复位 π←_{φk}。正向执行采到轨迹 τ→ = {(o_t, q_t, a_t)}；只有当 Agent 判定子任务成功，才触发复位策略采出 τ←，把环境带回可以再练一次的前置区域，两段合成一个纠缠对 τ_k 一起进入数据集 D。逆向任务是被刻意设计得比正向任务简单的——它只需要可靠，不需要困难；表 2 里四项复位的成功率是 36/50 到 43/50，说明这条自复位环路本身也会断。还要注意条件策略用的语言指令 l_t 不是人给的，而是 Agent 在调用 MCP 工具时现生成的结构化子任务描述。'), ('底层策略怎么训：π₀.₅ 上的 LoRA 微调', '策略不是从零训练，而是在现成 π₀.₅ 上做 LoRA 微调：rank 16、alpha 16、dropout 0.1，目标模块为 all-linear，bfloat16 精度，batch 16，学习率 2.5×10⁻⁵，训练 1 万步，推理 3 步。训练目标是条件流匹配——学一个速度场 v_θ，把标准高斯噪声输运到真实动作分布，一次预测长度为 H 的动作块。训练数据有三个来源：人工示范、EAP 自主采集的轨迹、以及自主 rollout 失败后人介入纠错产生的数据；实验里每一轮迭代新增 50 条。'), ('部署：同一个循环，区分重试与恢复，必要时叫人', '部署时 Agent 用同一套闭环结构选下一个子任务，通过 MCP 启动对应的正向策略，并周期性调用 Env Summary 与 Fetch Robot Stats，把反馈写进工作记忆来判断子任务是否完成。达标就更新任务级记忆并进入下一个子任务；不达标则重试同一条策略，或用 Change Policy 换一条；若检测到反复失败或异常环境状态，就重新规划、从正向技能集里改选；自主恢复无效或触发安全条件时，通过 Call Human 上报。论文据此把失败分成两类：非降级失败（如抓空但瓶子仍直立，位姿基本没变）可以直接重试，降级失败（瓶子倒了或滑出前置区）必须先执行恢复动作。早期这类恢复靠人，随经验累积，恢复行为被逐步固化成专门的恢复策略进入策略库；部署期产生的轨迹同样回流进 D 用于继续改进策略。')],
 example='教学推演：回到上面的场景。第一步，这条技能在系统里其实是一个 π₀.₅ 的 LoRA 检查点；Agent 看不到关节，它能看到的只是 Start Policy、Env Summary、Change Policy 这几个 MCP 工具。第二步，Agent 读到角色身份是数据采集者，任务级记忆里写着“练口红插入”，工作记忆还是空的；它先调 Env Summary 看一眼场景，确认口红此刻在起始区域，再决定启动正向策略。第三步是这篇的核心：正向策略把口红插进槽里，采到 τ→；Agent 判定成功之后才触发复位策略，把口红取回起始区，采到 τ←，两段合成一个纠缠对入库。之所以这条环路能自己转下去，是因为“从槽里取出来”本来就比“对准插进去”容易，复位被有意设计成弱任务。第四步，攒够一轮新轨迹后，在 π₀.₅ 上重做一次 LoRA 微调；表 3 显示口红插入从第 1 轮的 2/50 升到第 5 轮的 23/50——起点这么低，恰好说明早期环路主要是靠复位策略维持转动的，而不是靠正向策略成功。第五步，部署到“整理梳妆台”这条长程任务时，同一个 Agent 依次编排四条正向策略：某次抓空而口红还立着，它重试；口红被碰倒滚出前置区，重试就没有意义，必须先调恢复行为。这套机制没解决的是验证本身：成功与否仍由同一个 VLM 凭观测判定，系统里没有独立验证器，判错会让一条失败轨迹被当作正样本写进 D，污染下一轮微调。论文也把“存在实用的逆向复位行为”明确列为前提假设；顺着这个假设推下去（这是讲义的推论，不是论文的论断），倒水、切割这类结果不可还原的任务就配不出复位策略，整个数据引擎在那里转不起来。',
 code='m = (role, task_memory, working_memory)        # 角色 / 子任务进度 / 工具调用史\n每项技能 k 有一对策略 forward_k 与 reset_k     # 都是 π0.5 上的 LoRA 微调\nwhile role == 采集者 and 未达采集预算:\n    l = VLM_CoT(m, o_t)                        # 子任务指令由 Agent 现生成，非人给\n    τ_fwd = run(forward_k, l)\n    if VLM 判定成功: D += (τ_fwd, run(reset_k, l))   # 成功才复位，成对入库\n    else: 重试 或 Call Human\nfinetune(π0.5, D)                              # 每轮新增 50 条后重训\nwhile role == 执行者 and 任务未完成:            # 同一 Agent、同一记忆、同一语义\n    run(forward_k); m.w += Env_Summary() + Fetch_Robot_Stats()\n    if 达标: m.g 更新并进入下一子任务\n    elif 环境未破坏: 重试同一策略                # 非降级失败\n    else: 恢复策略 / Change Policy / Call Human  # 降级失败；本条轨迹回流 D',
 setup='在 Agibot G01 双臂移动平台上做真实操作。表 3 比较 1–5 轮采集，每轮增加 50 条数据；各单技能用 50 次试验评估。人工示范预算固定，但自主采集数据随轮数增加。',
 headers=['表 3 · 单技能','第 1 轮后','第 5 轮后'],
 rows=[['乳液摆放','21/50（42%）','43/50（86%）'],['妆前乳摆放','23/50（46%）','40/50（80%）'],['口红插入','2/50（4%）','23/50（46%）'],['纸巾擦拭','11/50（22%）','26/50（52%）']],
 findings='图 4(c) 的长程梳妆台整理，在第 5 轮时 RoboClaw 约 30%，直接 π₀.₅ 基线约 5%（图读数，20 次试验），差距约 25 个百分点；最终成功率仍不高。§4.1 的人工耗时比约 2.16×，对应约 53.7% 的节省；这些收益伴随更多自主交互和数据。表 2 的逆向复位为 36/50–43/50，也意味着采集环路仍会中断。',
 ablation='迭代轮数对照说明新增轨迹有助于单技能学习。长程实验还比较直接 π₀.₅ 和各子技能成功率的乘积估计；乘积是理论参考，不能当成实际跑过的闭环控制器。',
 boundary='模型来源是混合的：高层决策接的是一个现成 VLM，论文只写“off-the-shelf”，没有给出型号与规模，也不为机器人做微调，因此这一侧是可替换的（结论里还提到云端大模型会带来延迟）；而四条正向策略与四条复位策略全部由作者在 π₀.₅ 上用 LoRA 微调得到，加上每条正向策略固定的人工示范预算和失败后的人工纠错，这些才是系统真正的前提成本。还有两处结构性假设要记住：一是论文在结论里明确把“存在实用的逆向复位行为”列为限制，没有可靠复位就没有自采集环路；二是子任务成功与否由同一个 VLM 凭观测判定，系统内没有独立验证器，判错会把失败轨迹写成正样本。难任务如口红插入经五轮后仍只有 46%，因此自采集闭环并不保证很快学会所有技能。',
 transfer='与 Playful 的差别是研究重心：RoboClaw 让采集—训练—部署闭环可持续，Playful 关注主动提出什么任务、积累什么代码技能。',
 exercise='在仿真中设计正向和逆向任务，分别记录正向成功、复位成功、单位人工分钟有效轨迹数，再测试复位误差的累积。',
 answer='如果只计采集总条数，会把无效或高度重复轨迹也算作成果。更合适的是同时检查独立测试性能和总采集成本。',
 sources=[('EAP 与部署监督：§3','S3'),('人工成本与轮次实验：§4.1–4.2','S4.SS1'),('正向 / 逆向成功率：表 2–3','S3.T2'),('长程成功与人工成本：图 4','S3.F4')])

add('capx', version='v2',
 takeaway='评价机器人 Coding Agent，必须同时说清 API 有多强、感知有多准、允许调试多少次。',
 result='CaP-RL 的真实 Franka 抓取成功率：24% → 84%；但训练使用 S1 特权状态 API，不能混同所有评测层级。',
 why='两个方法都声称“用代码控制机器人”，难度可能完全不同：一个调用 pick(object)，另一个必须从 RGB-D 定位物体、算位姿、控制夹爪。CaP-X 提供环境、分层基准、Agent0 和 RL 后训练方法，把这些条件拆开测。',
 scene='同一句“把蓝色方块放到黄色方块上面”，可以是两种难度完全不同的题：一种能直接调 pick(object)，另一种必须自己从 RGB-D 定位物体、算位姿、控制夹爪。两篇论文都说“用代码控制机器人”，成绩却可能根本不可比。',
 recall_module='这篇改的是评测协议本身，不是又提出一个更强的机器人系统：它把“用代码控制机器人”拆成三条可以分别拨动的轴——观测是无噪声的仿真真值还是真实感知模块处理的 RGB-D、原语是人设计的高层宏还是各个包的底层 API、以及允不允许多轮迭代与用什么形态回传反馈——由此切出 S1 到 S4 与 M1 到 M4 八个层级，并把评分规定成 Pass@1、一次 trial 内绝不重置环境。它不训练感知与控制原语，SAM3、Molmo 2 与 PyRoki 都是现成的，仿真器的原生动力学被保留，也没有提出新的控制器；CaP-Agent0 完全 training-free，连技能库里那批通用函数都是从已有成功轨迹里抽出来的。唯一动过权重的是 CaP-RL 那条线，而它刻意选在 S1 的特权状态 API 下训练，所以它证明的事情和层级表想说清的事情并不是同一件。',
 recall_io='被评对象每次拿到的是一次 turn 的观测，具体内容由层级决定：S1 给仿真真值的掩码与物体位姿配高层原语，S2 起换成真实感知模块处理的 RGB-D，S3 把原语拆回底层 API 但保留用法示例，S4 连示例也去掉、只留函数签名与 docstring；多轮侧再叠反馈形态，M1 回传沙箱的 stdout 与 stderr，M2 在此之上加原始 RGB，M3 换成 VDM 把前后帧差异写成结构化文字，CaP-Agent0 另有一份跨 trial 持久的技能库一并进上下文。输出不是一个动作，而是一整段 Python 程序，交给 CaP-Gym 的 REPL 执行到底；程序内部可以多次调用感知与控制原语，每次原语调用又驱动模拟器或真机控制器跑很多内部步，因此一个回合的边界是“这段程序跑完”。一次失败没有复位这条退路，环境在同一个 trial 内永远不重置，把方块碰倒了下一轮面对的就是倒着的方块，Agent 只能从回传的反馈里读出出了什么事，再插打印语句确认或重新采样抓取位姿，不能靠重开一局刷成绩。判成败的是基准自带的成功判据，这一层是外部的；但 Agent 在环内对“做成了没有”的判断完全依赖反馈形态，M3 与 M4 里这个判断出自 VDM 背后的 VLM，而把原始 RGB 直接塞回上下文的 M2 反而不如纯文本的 M1。',
 steps=[('CaP-Gym：把仿真器包成 REPL，原语做成无状态服务', '环境层建在标准 Gymnasium 接口上，把底层模拟器（Robosuite、LIBERO-PRO、BEHAVIOR）的原生动力学保留下来，再以读—求值—打印循环（REPL）的方式暴露给 Coding Agent。一个“回合”(turn) 的定义很具体：Agent 收到观测、生成一段 Python 程序、环境把这段程序执行到底；程序内部可以多次调用感知与控制原语，每次原语调用又会驱动模拟器或真机控制器跑很多内部步。所有计算密集的原语都被实现成无状态服务，因此能做高吞吐的并行评测。'), ('原语本身来自现成模型：SAM3、Molmo 2、PyRoki', '感知原语负责把原始传感数据抽象成结构化语义对象：语言条件分割用 SAM3，开放词表指点用 Molmo 2，此外还有 OpenCV 与 Open3D 这类标准视觉库。控制原语不让 Agent 直接发关节空间命令，而是调用运动规划器或逆运动学求解器（PyRoki），由控制器负责碰撞检查、可达性约束与动作空间变换，Agent 因此可以在任务导向的笛卡尔空间里推理。这些都是现成组件，CaP-X 不训练它们；被评测的对象是“怎么把它们组装成一段程序”。'), ('分层怎么定义：三条轴切出八个层级', 'S1–S4 是单轮，M1–M4 允许多轮，三条轴分别是感知条件、原语抽象度、以及迭代与 grounding 方式。S1 用无噪声的仿真真值（掩码与物体位姿）配高层原语，作用是把高层规划与感知噪声分开，给出一条推理上界；S2 换成真实感知模块处理 RGB-D，仍用高层原语，这是多数既有工作的默认设置；S3 把人设计的高层原语拆回底层原语（solve_ik()、sam3_text_prompt() 这类直接来自各个包 API 的接口），文档里保留用法示例；S4 连示例也去掉，只留函数签名与 docstring。多轮侧，M1 回传 Python 沙箱的 stdout 与 stderr，M2 在此之上额外回传原始 RGB，M3 换成视觉差分模块（VDM），M4 则是 M3 的 VDM 配 S3 的底层原语与示例。'), ('调试预算怎么定义：Pass@1，且一次 trial 内绝不重置环境', '评测协议是 zero-shot Pass@1。一次 trial 内 Agent 可以只跑一轮，也可以多轮——边看执行反馈边改代码、边补探测语句——但环境在这个 trial 内永远不重置，物理后果会累积，不能靠“重开一局”刷成功率。论文没有给出统一的回合数上限，而是改报平均耗时：Gemini-3-Pro 做方块堆叠时，S1 单次 trial 约 12.9 秒，S3 约 28.4 秒，M1 约 60.8 秒，M3 约 113.6 秒。人类参考线也不是一次写成的：7 位作者在每个层级用与模型完全相同的 API 写单个 Python 脚本，反复读执行轨迹、改 bug，直到单轮平均成功率 88.5%；简单抓放任务几小时能到位，接触密集与双臂任务每项花了 2–3 周。'), ('CaP-Agent0 不训练，CaP-RL 才训练', 'CaP-Agent0 是 training-free 的外壳，只做三件事：把 VDM 转出的结构化文字当作每轮观测；带一个自动合成、跨 trial 持久的技能库——做法是把 12 个模型在 7 个 Robosuite 任务上所有成功的 S3 轨迹汇总，用正则抽出函数定义，再让 Gemini-3-Pro 找出高频且与任务无关的逻辑，最终得到 9 个经验证的通用函数；以及并行推理，每轮采 9 个候选（单模型是 Gemini-3-Pro 用 0.1 到 0.9 九档温度，多模型是 Gemini-3-Pro、Claude Opus 4.5、GPT-5.2 各 3 次），再由一个中心 Agent 把候选合成最终代码。CaP-RL 走的是另一条路：用 GRPO 对 Qwen2.5-Coder-7B-Instruct 做可验证奖励的强化学习后训练，每个任务训 50 轮；并且刻意选 S1 的特权状态 API 训练，以避开 S2 中感知与控制误差叠加造成的奖励噪声和信用分配歧义。')],
 example='教学推演：回到上面的场景。第一步，这句话进入 CaP-Gym 后，Agent 拿到的是一次 turn 的观测，它要交出一整段 Python，而不是一个动作；程序跑完才算一个回合，中途的所有物理后果都留在环境里。第二步，这段程序能调什么决定了难度上限：调 SAM3 拿蓝块掩码、调 Molmo 2 指点、调 PyRoki 解 IK，都只是把可达性和碰撞检查交出去，“抬到上方—对准—下降—松爪”的结构仍要 Agent 自己写出来。第三步，同一句指令在 S1 下拿到的是仿真真值位姿加一个封装好的高层原语，几行就写完；在 S4 下没有用法示例，只有函数签名与 docstring。两种成绩若直接并列，比的是 API 封装度而不是推理能力——论文图 3 画的正是抽象度越高成功率越高的那条单调曲线。第四步，若允许多轮，Agent 第一次把方块碰倒了，环境不会重置，它下一轮面对的是倒着的方块，要么插打印语句确认高度差、要么重新采样抓取位姿。这就是“调试预算必须和成功率一起报”的原因：人类专家的 88.5% 背后是离线反复迭代（接触密集任务每项 2–3 周），而 CaP-Agent0 一次 trial 只有约两分钟。第五步，CaP-Agent0 把这些机制全用上——VDM 把“蓝块现在歪了”写成文字、技能库里已有旋转矩阵转四元数一类现成工具函数、九路候选合成一份代码，结果是它在 7 项任务的 4 项上达到或超过人类的单轮代码。这里最该记住的是 M2 那个反直觉结果：把原始 RGB 直接塞回上下文，反而不如纯文本反馈的 M1，只有把视觉变成结构化文字的 M3 才稳定更好。多给一个模态不等于多给了有用信息，这一条在读后面那些沿用同名基准的论文时尤其要带着。',
 code='# 一个评测配置 = 感知条件 × 原语抽象 × 是否给用法示例 × 反馈形态\ntier = (perception, primitives, examples, feedback)   # S1..S4 单轮；M1..M4 多轮\nenv  = CaP_Gym(sim = Robosuite | LIBERO-PRO | BEHAVIOR)  # 原语为无状态服务\n\nobs = env.reset()                    # 一次 trial 内此后不再 reset\nwhile not done:                      # 每个 turn 交出一整段 Python\n    cands = [model.write(obs, tier, skill_lib) for _ in range(9)]  # 并行采样\n    code  = ensemble.synthesize(cands)\n    stdout, stderr, imgs = env.execute(code)   # 程序内部调 SAM3 / Molmo2 / PyRoki\n    obs  = stdout + stderr + VDM(前一帧, 当前帧, 任务)   # M3/M4：视觉→结构化文字\n    done = 目标达成 or 触及回合与时间预算\nrecord(success, turns, wall_time, tokens)      # Pass@1 必须连预算一起报',
 setup='CaP-Gym 含更广任务集合；核心 CaP-Bench 用 7 项任务研究 12 个模型及不同接口条件。下表是论文 §5 的独立 CaP-RL 实验：Qwen2.5-Coder-7B 在 3 项任务训练，仿真每项 100 次、真实 Franka 每项 25 次。',
 headers=['表 4 任务','基础 Qwen 7B','CaP-RL 后','人工专家'],
 rows=[['仿真抓取','25%','80%','93%'],['仿真堆叠','4%','44%','73%'],['真实抓取','24%','84%','92%'],['真实堆叠','12%','76%','84%']],
 findings='训练可以显著改善指定任务上的代码控制，但这张表不能证明基准中的每项任务、每种感知层级都得到同等提升。真实堆叠仍低于人工专家，仿真堆叠差距更大。',
 ablation='§3.3 的分层实验发现，直接加入 RGB 的 M2 并未稳定优于文本反馈，视觉差分 M3 更有效。更多模态不自动等于更好；反馈必须能帮助定位代码与物理变化之间的关系。',
 boundary='这篇的模型来源格外需要拆开看：被评的 12 个前沿模型、做 VDM 的 Gemini-3-Pro、感知原语 SAM3 与 Molmo 2、控制原语 PyRoki 全是现成组件，CaP-Agent0 是完全 training-free 的外壳，连技能库那 9 个函数也是从已有成功轨迹里抽出来的，不是新训练的模块；真正由作者训练的只有 CaP-RL 一条线——在 Qwen2.5-Coder-7B-Instruct 上用 GRPO 后训练，而且是在 S1 特权状态 API 下训的。所以表 4 的 24% → 84% 是“训一个小代码模型 + 特权 API”的结果，CaP-Agent0 接近人类的那部分成绩则来自推理时算力（九路采样、多轮、VDM），两者成本结构完全不同，不能合并成一句“CaP-X 让机器人写代码更强了”。VDM 用的是当时最强的 VLM，论文明说这是为了给“语言化感知”的效果取上界，换弱一点的 backbone 结论可能变。人类参考程序也经历过调试，模型的单轮 Pass@1 是另一种开发成本；附录 K 显示平均试验时长随多轮机制显著增长，比较成功率时必须同时报预算。',
 transfer='它是读 ASPIRE、Playful 和 Harness VLA 的评测尺子。后续论文即使用同一个 LIBERO-Pro 名字，也可能使用不同任务范围、seed、工具和探索预算。',
 exercise='为自己的方法填写一张评测契约：输入、可用 API、reset 权限、训练 / 调试 seed、每任务调用预算、成功判据。',
 answer='先保证对照在这些条件上可比，再讨论方法收益。否则实验可能测到“谁获得了更多信息或更多尝试”，而非你想研究的机制。',
 sources=[('分层定义与发现：§3 / 表 1','S3'),('Agent0：§4','S4'),('CaP-RL：§5 / 表 4','S5.T4'),('预算与人工参考：附录 K','A11')])
add('playful', version='v1',
 takeaway='自主练习要选“新鲜但学得动”的任务，再把成功代码和失败教训带到后续任务。',
 result='LIBERO-Pro 主实验：CaP-Agent0 23.2%，RATs 43.8%；真实迁移的两个任务平均 30.0% → 38.8%。',
 why='如果机器人只在用户给任务后临时写程序，许多困难会被反复发现。Playful Agentic Robot Learning 让 RATs 在没有外部任务指令的 play 阶段主动练习，再把积累的代码技能用于测试。关键问题是练什么、怎样确认学到了，以及积累的能力是否可迁移。',
 scene='顺着论文附录记录的 MolmoSpaces 第 15 轮 play 走一遍。此刻没有人下达任何指令，机器人面前是一张摆着喷瓶、黑布与纸巾盒的场景。如果只在收到任务之后才临时写程序，同样的困难会在每个任务里被重新发现一遍。',
 recall_module='改的是获取技能的时机：技能不再等用户下达指令之后临时写，而是在一个把外部指令 l 拿掉的 play 阶段由 Agent 自己提出任务、自己练，练够轮数后把技能库冻结，再拿去做测试任务。配套换掉的是“该练什么”的判据，Goldilocks 打分用新颖项乘能力前沿项，把太熟与做不到的候选一起压低，技能可靠性按 Wilson 下界估计而不是原始成功率，以免一次侥幸成功就把少用技能判为可靠。它不训练任何模型权重，感知与控制原语沿用 CaP-Agent0 那一套，动作空间没变；积累下来的技能是一批参数化的 Python 函数，迁移靠把代码检索进上下文，不靠微调，代价转移到了交互与 token 上。',
 recall_io='play 期的输入里没有指令：提出器拿到的是当前场景上下文、原语 f、技能库 L 的元数据摘要（技能名、描述、可靠性等级与成功统计，但不含源码，以免上下文被代码撑满）、最近若干条尝试记录，以及从失败记忆 M 按任务与物体重叠度检索出的教训；可见且可达的物体由外部的场景 grounding 与可达性过滤给出，环境实例则由 Environment Creator 造。输出先是一个 play 阶段的候选任务，在 LIBERO 上还要先被写成 BDDL 任务规范才能实例化成环境，随后才是 Planner 的有序计划与 Policy Writer 的一段可执行代码，交给环境去跑，成功的执行再被抽成参数化辅助函数入库。这一篇的失败处理不仅有，而且分得清“提错了任务”和“做错了事”：Environment Verifier 用两个 reset seed 做确定性检查，被拒的任务退回提出阶段、不消耗一次执行机会；Planner Verifier 在写码之前查计划与初始观测对不对得上，Quality Checker 静态挡掉语法错误、不存在的 API 与无界循环；执行后 Goal Verifier 判总成败，有结构化谓词时按环境状态求值、否则走自定义检查或视觉判断，程序崩溃一律算失败，Per-Step Verifier 再结合代码切片、关键运行时数值与前后视觉证据给出步级判决。Failure Diagnoser 据此给出失败类别、首个失败步与修复建议并路由回改码、重规划或派 SubAgent 单练子动作，失败集蒸馏成教训写进 M，技能按 experimental、verified、deprecated 三级升降；需要留意的是除了那条谓词求值，其余判定仍出自与写码者同一底座的模型，分工清楚并不等于判据独立。',
 steps=[('play 的定义：把外部指令 l 拿掉', '标准 Code-as-Policy 给 Agent 的是环境上下文 c、原语函数 f 和语言指令 l，Agent 据此合成可执行程序 π。play 阶段把 l 去掉，Agent 在 play 环境里自己提出并练习任务 τ_t。系统维护两个持久库：技能库 L = L₀ ∪ L_learned，其中 L₀ 就是初始原语 f，L_learned 存从成功执行里抽出的代码技能；失败记忆 M 存失败后蒸馏出的紧凑教训。跑 N 轮之后 L 被冻结拿去做测试任务，主实验 N = 50，底座模型是 gemini-3.1pro-preview，两个 play 环境分别是 LIBERO-PRO 与 MolmoSpaces。'), ('任务提出：先生成候选池，再用 Goldilocks 打分选一个', '提出器 LLM 拿到三样输入：当前场景上下文、技能库的元数据摘要（技能名、描述、可靠性等级与成功统计，但不含源码，以免上下文被代码撑满）、以及最近若干条尝试记录，据此生成候选任务池 T_t 并标出每个候选需要的物体与技能。选择用解析式打分 τ_t = argmax [N(τ)·F(τ)]：新颖项 N(τ) 对每个物体—技能对取 1/√(N(o,s)+1) 再平均，鼓励很少试过的组合；能力前沿项 F(τ) = 4·r̄(1−r̄)，其中 r̄ 是所需技能的 Wilson 下界成功率均值，这条抛物线在 r̄ ≈ 0.5 时取最大，于是太熟（r̄→1）和做不到（r̄→0）的候选都被压低。用 Wilson 下界而非原始成功率，是为了避免一次侥幸成功就把一项少用技能判为可靠；与近期失败高度相似的候选还会被降权。'), ('任务要先能被实例化：Environment Creator 与 Verifier', '选中的任务不会直接开跑。在 LIBERO 上，Environment Creator 把提议转成一份 BDDL 任务规范（objects / init / goal 谓词），做语法与语义校验后实例化对应的 MuJoCo 环境；校验不过允许一次有界修复再验一遍。随后 Environment Verifier 用两个 reset seed 做确定性检查：环境要能实例化与渲染、能暴露模拟器、每个声明的物体实体都要存在、每条目标谓词都能无误求值、初始状态不能有严重穿模。被拒的任务退回提出阶段，不消耗一次执行机会——这一步把“提了一个根本不存在的任务”和“提了一个做不到的任务”分开了。'), ('执行：带重试预算的 Write-Execute-Verify-Diagnose 内循环', 'Planner 拿到任务描述、初始观测、从失败记忆检索的教训、原语 API 与激活技能（verified 排在 experimental 之前展示，deprecated 默认隐藏），输出有序计划、给每步标注相关技能并预测可能的失败点；Planner Verifier 在写代码之前先查计划是否与初始观测对得上（场景误判、缺前置、顺序错、物体范围不符），不通过就退回细化，直到通过或耗尽细化预算。之后进入内循环：Policy Writer 写代码（重试时还会拿到逐步验证结果与“哪些代码段已经能跑”的摘要，鼓励局部修改而非整段重写），Quality Checker 静态筛掉语法错误、不存在的 API、无界循环与违规模式，避免把机器人交互预算花在读源码就能发现的错误上。执行后 Goal Verifier 判总成败（程序崩溃一律算失败，即使最终画面看着合理），Per-Step Verifier 结合每步的代码切片、关键运行时数值和前后视觉证据给出步级判决。成功即停；失败则 Failure Diagnoser 给出失败类别、首个失败步与具体修复建议并路由——代码层面回 Policy Writer，计划层面触发重规划，反复卡住的局部物理瓶颈派一个 SubAgent 在同一 reset 状态下单独练这个子动作，直到耗尽重试预算。'), ('记忆更新：三级可靠度加每 K 轮整理', '成功后系统从执行过的代码里抽出自包含、参数化的辅助函数（抽的是可复用行为单元，不是整段任务脚本），补 docstring、静态校验后作为 experimental 技能入库；失败则把该集记入 M，并蒸馏成一条紧凑教训（什么条件下避免什么做法、改用什么修正），Planner 日后按任务与物体重叠度检索这些教训。技能走三级生命周期：新技能是 experimental，累计至少 3 次使用且经验成功率不低于 0.5 升为 verified，至少 10 次使用且成功率不高于 0.2 标为 deprecated 并默认隐藏，verified 也会因持续表现差被降级。每 K 轮（默认 K = 5）Memory Curator 合并或重写近似重复的技能、清理冗余教训；若近期失败反复暴露同一项缺失能力，Skill Proposer 会从已有原语起草一个候选辅助函数作为 experimental 入库，靠后续使用挣可靠度。测试阶段任务提出器与 Memory Curator 一并关闭，只用冻结的 L。')],
 example='教学推演：回到上面的场景。第一步，此刻没有人下达任何指令，技能库里是 22 项：13 个原语（感知类如 get_observation、segment_sam3_text_prompt、point_prompt_molmo、vlm_verify，抓取规划与控制类如 plan_grasp_from_point_clouds、solve_ik、goto_pose，夹爪类如 open_gripper、close_gripper）加上 9 项此前 play 学来的技能。第二步，场景 grounding 标出五个可见物体——蓝色喷瓶、黑布、棕色纸巾盒、马桶、白色柜子；可达性过滤把马桶去掉，剩四个作为提议目标。提出器据此生成 5 个候选，按新颖度乘能力前沿排序，“抬起纸巾盒”以综合分 0.6236 胜出：它足够新，同时离当前抓取能力不算太远。黑布那条候选在进入排序前就被否决，因为当前 bridge 配置不支持这种交互。第三步是容易被忽略的一环：被否决的候选退回提出阶段，不算一次执行机会——在 MolmoSpaces 里是重绑环境后检查目标是否仍能被视觉定位，在 LIBERO 里则是生成 BDDL 规范并跑两个 seed 的确定性检查。第四步，Planner 排出计划并给每步挂技能，比如“定位纸巾盒”会挂上已有的 localize_object_with_molmo_sam3——这条技能在第 15 轮的原始成功率只有 0.3125（用过 32 次），仍是 experimental，所以它排在 verified 技能之后展示。Quality Checker 先挡掉不合法代码，执行后 Goal 与 Per-Step 两级验证给出判决，失败则由 Failure Diagnoser 定位到首个失败步再重试。第五步，若这次抬起成功，抽出来的不是“抬纸巾盒”这段脚本，而是一段参数化的可复用函数，先作为 experimental 入库，要用满三次且成功率不低于 0.5 才升 verified。这套机制的代价写在附录的 token 统计里：失败诊断一项就占 play 期 token 的 40.5%，是最大开销项。它也不保证越练越强——RoboSuite 迁移里双臂交接反而从 24% 降到 20%。真正值得记住的是论文那个算力对齐对照：把 play 花掉的 token 折算到测试期，CaP-Agent0 可以从 10 轮重试放宽到约 15 轮，问题于是变成“同样的算力，花在事后重试还是事前练习”。',
 code='L = L0(原语) ∪ L_learned;  M = 失败教训库     # play 期没有外部指令 l\nfor t in range(50):\n    cands = Proposer(场景上下文, L 的元数据摘要, 最近尝试记录)\n    τ = argmax [ N(τ) · 4·r̄(1−r̄) ]            # 新颖度 × 能力前沿，r̄ 取 Wilson 下界\n    env = Creator(τ); if not Verifier(env, 2 个 seed): continue  # 退回提出，不计执行\n    plan = Planner(τ, obs, 检索到的教训, L)     # verified 先于 experimental 展示\n    while 未成功 and 未耗尽重试预算:\n        code = PolicyWriter(plan, 上轮诊断); QualityChecker(code)  # 静态拦截\n        ok = GoalVerifier(run(code)) 且 PerStepVerifier 逐步判决\n        if not ok: Diagnoser → 改码 / 重规划 / 派 SubAgent 单练子动作\n    L += 抽取的参数化函数(experimental) if ok else M.add(蒸馏教训)\n    if t % 5 == 0: Curator(合并去重); SkillProposer(补缺失能力)\n# 测试期：冻结 L，关闭 Proposer 与 Curator',
 setup='主实验在 LIBERO-Pro 的 60 个任务条件、600 次 rollout，以及 MolmoSpaces 的 40 项任务、400 次 rollout 上评测。技能库还迁移到 RoboSuite 和真实机器人；下表各行属于不同评测，不是同一难度排名。',
 headers=['主实验 / 迁移','CaP-Agent0','加入 RATs 机制或技能'],
 rows=[['LIBERO-Pro · 完整系统','23.2%','43.8%'],['MolmoSpaces · 完整系统','21.0%','38.0%'],['RoboSuite · 技能迁移','141/350（40.3%）','172/350（49.1%）'],['真实两任务 · 技能迁移','24/80（30.0%）','31/80（38.8%）']],
 findings='真实迁移确有收益，但最终成功率只有 38.8%，远没有解决所有问题。迁移也并非每项都正收益：RoboSuite 双臂交接从 24% 降到 20%，螺母装配仍为 0%。',
 ablation='表 4 固定 CaP-Agent0 执行器时，无 play / 随机 play / 好奇心 play 分别为 23.2% / 24.7% / 32.3%。仅换 RATs 执行器、不 play 可到 36.3%；两者结合的消融为 44.3%。该消融部分采用每任务 5 次，不能与主表 43.8% 当作同一次实验。',
 boundary='模型来源这一层很单薄，也正是这篇的成本所在：整个系统不训练任何模型权重，play 与测试都由现成的 gemini-3.1pro-preview 驱动，底层感知控制原语沿用 CaP-Agent0 那一套（Molmo 指点、SAM3 分割、IK 与抓取规划），学到的“技能”是一批经过验证的 Python 函数，所以迁移时靠的是把代码检索进上下文，不需要微调。代价换成了交互与 token：附录的分解显示 Failure Diagnoser 一项占 play 期 token 的 40.5%，Policy Writer 次之，也就是说主要开销在反复失败后的诊断与改写，而不是任务提出。play 需要额外交互、计算和任务验证；无外部目标不等于没有成功判据，应把探索预算与测试预算分别报告，也要控制技能是否提前接触过测试任务。论文自己做了算力对齐对照——把 play 的摊销 token 折给测试期让 CaP-Agent0 跑约 15 轮，与标准 10 轮加 RATs 技能库相比——读这类“积累型”方法时应当要求同样的对照。',
 transfer='与 Voyager 同看课程与积累，与 ASPIRE 同看经验的内容：Playful 更强调主动探索的任务与代码能力，ASPIRE 更强调从失败中提炼可迁移修复。',
 exercise='固定 50 轮练习预算，比较随机任务、最难任务、适中难度任务；用相同测试执行器和未见任务测试技能库。',
 answer='只看训练期成功率会偏爱简单任务。更有意义的是下游增益 / 探索成本，以及负迁移发生在哪些技能上。',
 sources=[('任务选择、执行和记忆：§3','S3'),('主实验与迁移：表 1–3','S4'),('拆分 play 与执行器：表 4 / §4.4','S4.T4')])

add('aspire', version='v1',
 takeaway='把一次失败修好的原因，沉淀成下一次可检索的修复技能。',
 result='LIBERO-Pro 消融：基础系统约 14%，执行证据引擎 62%，再加进化搜索 72%；长程迁移为 30.5%。',
 why='机器人程序报错时，“任务失败”通常不够用。到底没看见目标、导航点不可达，还是夹爪抓偏？ASPIRE 为 coding agent 提供逐原语的多模态执行记录，让它检查因果链、修改程序，再将经过验证的修复方式存入技能库。',
 scene='任务是 BEHAVIOR-1K 里的导航取收音机。机器人已经检测到收音机，却反复靠不过去。此时只知道“任务失败”没有用：是没看见、导航点不可达，还是抓偏了，对应的修法完全不同。',
 recall_module='改动落在经验的存放位置，以及为沉淀经验所必需的执行环境。机器人侧的感知、几何与运动规划都是 CaP-X 预先给定的 API，程序由现成的 coding agent 写，控制器权重一律不动，动作的输出形式也还是那套 API 调用。真正换掉的是两件事：让执行引擎为每一次原语调用留下记录与多模态证据，使得“哪一环先坏”成为可查的事实；再把一次已验证的修复从“这次怎么绕过去的”升级成技能库里带触发条件的条目，于是被积累下来的是修复知识，而不是某个 seed 的坐标。',
 recall_io='输入是任务描述、CaP-X 固定的 API 列表，以及开工前先读的记忆索引与相关技能条目；运行中真正供诊断用的输入是逐原语的执行记录——调用了哪个 API、输入与输出、返回状态，外加围绕可疑调用的多模态证据，包括该调用前后各一帧图像与叠加图、抓取候选、物体位姿与运动规划结果，代理看到的是这些片段而不是整段视频。被明确禁止的是仿真器真值：物体位置、任务判定谓词、场景资产文件都算违规，评测 seed 在调试期间锁住，诊断必须出自观测与 trace。输出有两级：一是针对出错原语改过的程序，只在调试 seed 上重跑确认，最终程序在留出 seed 上只跑一次；二是经协调者审核后串行写入共享技能库的条目，内容是失败特征、何时适用的触发条件、修复策略与必要的代码草图，落地形式就是 coding agent 的技能文件加一份记忆索引，交给后续任务的程序合成使用。失败由代理自己发现，依据是 trace 里的返回状态与前后帧证据：收音机那次是感知调用已经给出位姿、而多次 navigate_to_pose 返回 PLANNING_ERROR，据此判定坏在导航目标位姿而非检测或抓取，修法是加一段多角度接近例程并在调试配置上重跑通过；若沿单条轨迹反复打补丁仍走不出去，进化搜索会基于技能库、历史表现最好的前三个程序与它们残留的失败 trace 另提一批候选，并把已被实验排除的方向写进跨轮的任务分析文档。',
 steps=[('把程序放进一个留下逐调用证据的执行环境', 'ASPIRE 自己不训练机器人模型：程序由现成的 coding agent 写（仿真部分全程是 Claude Code 搭 Claude Opus 4.6、1M token 上下文；真机换成 OpenAI Codex GPT-5.5），程序只能调用 CaP-X 框架预先给定的感知、几何与运动规划 API，感知端接的是 SAM3 文本提示分割、VLM 指点这类现成服务。执行引擎为每一次原语调用留下一条记录：调用了哪个 API、输入与输出、返回状态，以及相关的多模态证据——该调用前后各一帧图像与叠加图、抓取候选、物体位姿、运动规划结果。代理拿到的不是整段视频，而是围绕可疑调用的这些片段，因此能顺着返回状态往回找是哪一环先坏。'), ('定位失败、改程序、在调试分片上重跑验证', '代理不重写整段任务程序，而是先从 trace 里认出出错的原语，再写针对性的修改，并只在调试 seed 上重跑确认。评测 seed 在调试期间被锁住，最终程序在其上只跑一次，这条协议由 agent 提示直接规定。系统提示同时禁止读取仿真器真值：物体位置、任务判定谓词、场景资产文件都算违规，诊断必须出自观测与 trace，理由是这些通道在真机上不存在。'), ('用进化搜索跳出局部补丁', '沿单条轨迹反复打补丁容易困在同一个坏思路上。每一轮，coding agent 基于技能库、历史表现最好的前三个程序以及它们残留的失败 trace，提出 K 个候选程序，逐个送进执行引擎打分；下一轮再条件在新的最优程序与它尚未解决的失败模式上。终止条件有两个：某个候选在调试配置上达到阈值，或者搜索预算用尽。搜索还维护一份跨轮的任务分析文档，记下场景描述、正在检验的假设、已经被实验排除的方向，以及因工作空间限制暂时走不通、但将来有新手段可以再试的方向。'), ('只有验证过的修复才升级成技能', 'actor 按固定字段汇报：观察到的失败模式、验证过的修复、可迁移的模式、任务特有的怪癖，以及在调试配置上的验证成功率。协调者审这份汇报，确认修复没有违反 API 政策、而且能迁移出原任务，才把它写进共享技能库；多个 actor 并行跑，但技能写入由协调者串行化。技能条目存的是失败特征、何时适用的触发条件、修复策略，必要时附一段代码草图——落地形式就是 coding agent 的技能文件加一份记忆索引，新任务开工前先读索引再读相关技能。')],
 example='原文 §2.1 的收音机案例正好把这四步走了一遍。第一步，任务是 BEHAVIOR-1K 的导航取收音机；自我视角关键帧显示机器人找到了收音机却反复靠不过去，而执行引擎已经把这段过程拆成逐调用的记录留在那里。第二步，代理顺着记录读返回状态：感知调用成功并给出了收音机位姿，问题出在随后多次 navigate_to_pose 都返回 PLANNING_ERROR；再看日志里的导航目标点，它落在离桌沿约 20 厘米的范围内（这是论文给出的数值），触发避障，规划器因此判定不可达。这一步的结论是失败既不在检测也不在抓取，而在目标位姿本身不可行。第三步，修复顺着诊断写：不动感知提示、也不动抓取原语，而是加一段多角度接近例程，在收音机周围采样别的导航目标，挑一个能绕开碰撞缓冲的方向靠过去，再重新感知并完成抓取；这段修改要在调试配置上重跑通过才算数，评测 seed 此时仍是锁住的。第四步，写进技能库的不是这台收音机在哪个坐标，而是一条导航恢复模式：当采样目标落进障碍物边界的碰撞缓冲、规划器反复报错时，先在物体四周换接近方向，再重试感知与抓取。协调者确认它不依赖本任务、也没有绕过 API 政策，才把它升级成技能。这套机制没做到的事也要看清：它不改动任何控制器权重，能表达的修复被预先给定的 API 圈住；技能库变大之后，过时、过细或误导性的条目如何淘汰与再验证，论文自己列为尚未解决的问题。',
 code='program = agent.write(task, skills=library.read())        # 现成 coding agent 写程序，技能库进提示\nfor gen in range(T):                                      # 进化搜索预算 (K, T)\n    for k in range(K):\n        score[k], trace[k] = run(program[k], seeds=debug)  # 逐调用记 API/输入输出/返回状态/前后帧\n    best = argmax(score)\n    if score[best] >= theta: break                        # 解决调试配置即终止\n    analysis = update_analysis(analysis, trace)           # 记下已排除与暂时走不通的方向\n    program = agent.propose(top3(history), trace, library, analysis)\nrun(best, seeds=heldout)                                  # 留出 seed 只跑一次，调试期锁住\nfinding = actor.report(failure_mode, fix, transferable, debug_success_rate)\nif coordinator.audit(finding):                            # 查可复用性与 API 政策，写入串行化\n    library.add(failure_signature, when_to_apply, repair, code_sketch)',
 setup='LIBERO-Pro 报告位置与指令扰动，并采用留出的 50 个评测 seed；另在 LIBERO-90 积累技能后，对 LIBERO-Pro Long 做不再调试的迁移。真实实验比较有 / 无技能，并同时报告成功率和 token。',
 headers=['证据位置 / 设置','对照','ASPIRE'],
 rows=[['§3.7 · LIBERO-Pro 组件消融','基础约 14% → 引擎 62%','完整 72%'],['附录表 5 · 长程零样本迁移','CaP-Agent0 3.8%','技能来自 90 项任务：30.5%'],['表 1 · 实机抬汽水罐','13/20','19/20'],['表 1 · 实机开 / 推抽屉','0/20','11/20']],
 findings='执行证据引擎带来的跳升最大，说明“能看清哪里坏了”是关键条件；进化搜索再解决一部分残余难题。长程迁移 30.5% 是另一种更难的协议，不能用 72% 代替。',
 ablation='§3.7 区分引擎与进化搜索；附录表 5 还显示技能来源从 0、25、50 到 90 项任务时，长程总体为 4.7%、13.7%、21.5%、30.5%。积累的覆盖重要，但需计入训练任务上的调试成本。',
 boundary='模型来源与前提成本要分开算：ASPIRE 不训练任何模型。机器人侧用的是 CaP-X 预先给定的感知、几何与运动规划 API（感知服务里包含 SAM3 文本提示分割等现成模型），智能侧用的是冻结的前沿 LLM——仿真实验全程 Claude Code 搭 Claude Opus 4.6，真机换成 Codex GPT-5.5。论文自己列出随之而来的四条限制：没有验证更小或更弱的模型能否撑住同一套调试循环；能表达的修复被固定 API 圈住，超出范围只能低效逼近或等人扩接口；技能库变大后会出现过时、过细、冗余或误导的条目，缺少成熟的检索、剪枝、排序与再验证，这也能解释零样本迁移的非单调；整个调试与搜索循环消耗大量 LLM 调用与 rollout。技能可以是自然语言修复知识，不一定是独立可执行控制器。真实开 / 推抽屉使用技能后仍只有 11/20；自动复位、成功判断与长时间自主运行仍有工程限制。',
 transfer='与 Inner Monologue 相连的是反馈，与 Voyager 相连的是持久技能库。更具体的研究问题是：什么样的失败摘要能跨对象、跨场景复用？',
 exercise='保留相同基础模型，比较只给“失败”、给最后一帧、给失败 API 前后证据三种修复方式；用新布局检验修复规则。',
 answer='一条可迁移的教训应有适用条件和已验证证据。若只记某个 seed 的坐标，很可能是实例记忆；要通过留出布局才能证明更一般的技能。',
 sources=[('执行引擎、技能库与搜索：§2','S2'),('真实实验与组件消融：表 1 / §3.7','S3'),('长程迁移：附录 C / 表 5','A3.T5')])

add('harness-vla', version='v4',
 takeaway='把冻结 VLA 当成局部接触技能；外层 Agent 负责把机器人带到合适状态，再决定何时调用。',
 result='v4 表 3 的 8 个 LIBERO-Pro 条件平均：相同 π₀.₅ 检查点直接运行 50.0%，Harness VLA（CC）82.4%。',
 why='一个 VLA 可能很会在熟悉状态下抓取，却会在目标换位置或指令换对象后回到训练习惯。Harness VLA 保留策略权重，将它封装成短程调用，并让外层代理结合解析控制、当前观测和历史记忆决定执行顺序。',
 scene='一台 LIBERO-Pro 上的机械臂，指令被改写成把黑碗放到木托盘上，而画面和标准任务看起来差不多。一个在标准变体上很强的冻结策略，很容易照训练时的习惯去够原来那个目标。重新训练它不在选项里——问题是能不能不动权重就让它做对。',
 recall_module='改的是一个冻结策略被调用的方式与时机，而不是策略本身。VLA 权重一律不动，各基准换的只是背后的检查点；规划器是现成的 coding agent，不为机器人做任何训练；解析原语由运动学写死，不需要训练数据；成败仍按基准自己的完成谓词判。新增的是外面那层 harness：把冻结策略收成 vla_act 这一条带提示、chunk 预算与早停谓词的调用，只用在抓取、受约束放置、开关抽屉、插入这类接触密集的局部阶段，自由空间搬运与预接触摆位交给固定词表里的解析原语，再让每一次物理动作后面跟一次观测与判断。与 ASPIRE 沉淀修复知识不同，这里被沉淀与复用的是“在什么状态下起步、什么时候把控制权交给策略”。',
 recall_io='输入是任务文本、当前 RGB 图像（负责语义）与共对齐的深度图和本体状态（负责度量），加上两份内容不同的记忆：任务记忆是一条 JSONL 过程轨迹与一份 JSON 语义摘要，轨迹按顺序记下发过哪些原语调用、并把具体坐标换成符号化的感知查询；全局记忆存跨任务的成功规则与失败模型。仿真器特权状态与物体真值坐标被明确禁止，规划器看不到它们。输出是一次写进 command.json 的原语调用——要么是 move_to、rotate_pitch、set_gripper、release 这类解析原语，要么是一次带提示、chunk 预算与早停谓词的 vla_act；长驻的环境 worker 读走它、在仿真里执行到该原语的内部后置条件，再写回带序号的观测文件、诊断日志与同步标志，规划器等这些文件出现才选下一条，部署时 reset 关闭、步数预算缩短。失败由规划器发现，依据就是 worker 写回的新观测与诊断记录：它把结果归类为进展、可恢复失败或不可恢复失败，例如读到夹爪已闭合而物体位置没跟着末端走，全局记忆里的失败模型要求按空抓处理、重新定位再重试。判为可恢复时整段 rollout 不终止，规划器先用解析原语把机器人重新摆到该 VLA 熟悉的预接触构型，再调一次 vla_act，把错误局限在当前这一段接触上，循环直到完成谓词满足或预算用尽。',
 steps=[('冻结 VLA 被暴露成一条可调用原语', '策略权重一律不动，只通过 vla_act 这一个 JSON 调用对外开放：规划器给它一条任务相关的提示、一个 chunk 预算和一个早停谓词，冻结策略就持续输出 action chunk，直到谓词满足或预算耗尽。谓词可以是抓稳抬起、某个接触状态、基准的完成信号，或者单纯的 chunk 上限。各基准换的只是背后的检查点，接口不变：LIBERO 与 LIBERO-Pro 用 RLinf 发布的 pi05_libero130_fullshot（π₀.₅-SFT，论文记作 πRLinf），RoboCasa365 用官方 RLDX-1，RoboTwin C2R 用作者自己后训练的 LingBot-VLA。'), ('其余动作交给不需要训练数据的解析原语', '同一个词表里还有六条确定性的解析原语：move_to 与 move_pose 接受世界系笛卡尔目标、交给环境自带的求解器，rotate_wrist 与 rotate_pitch 在保持位置的前提下给腕部设定点，set_gripper 与 release 管夹爪；RoboCasa365 另加 navigate_to 与 move_base 两条底盘原语用于厨房尺度的摆位。它们由机器人运动学写死，负责自由空间搬运、预接触摆位、转向、退让与接触后重新摆位，vla_act 只留给抓取、受约束放置、按键、开关抽屉与插入这类接触密集的局部阶段。词表在评测前固定，规划器不能发明新原语。'), ('规划器只在文件化的 REPL 里出手', '规划器有两种后端——Codex 与 Claude Code，除后端外 harness、记忆接口、原语库、VLA 接口与评测协议完全相同。它把一次决策写成 command.json，长驻的环境 worker 读走、在仿真里执行到该原语的内部后置条件，再写回带序号的观测文件、诊断日志与同步标志；规划器等这些文件出现才选下一条原语，因此每一次物理动作后面都跟着一次观测与判断。它拿不到仿真器特权状态与物体真值坐标，语义靠 RGB 图像，度量靠共对齐的深度图与本体状态。'), ('两种记忆存的东西不一样', 'bootstrapping 阶段在一个参考实例上放开 reset 与时间预算，让规划器反复试不同的摆位顺序、预接触位姿、vla_act 的调用时机与早停阈值。做成之后写两份东西：任务记忆是一条 JSONL 过程轨迹加一份 JSON 语义摘要，轨迹按顺序记下发过哪些原语调用，并把具体坐标换成符号化的感知查询，摘要写清策略为什么成立、要避免什么；全局记忆存跨任务的操作知识，包括成功规则（接触阶段用 VLA、抓稳后改用解析动作做长距离搬运与精确放置）与失败模型（夹爪闭合但物体没跟着末端走，按空抓处理并重新定位；不要只凭视觉接近就判完成）。失败尝试也作为负证据保留。'), ('部署时重定位、按需重试、按谓词收尾', '正式评测关掉 reset、缩短步数预算。规划器取出任务记忆的结构，用当前 RGB-D 重新绑定物体、固定件、支撑面与目标位姿，再按记忆的顺序执行，同时参照全局记忆里的规则与失败模型。接触失败不终止整段 rollout：规划器读到新观测与诊断记录后把结果归类为进展、可恢复失败或不可恢复失败，可恢复时先用解析原语把机器人重新摆到一个该 VLA 熟悉的预接触构型，再调一次 vla_act，把错误局限在当前这一段接触上。循环直到完成谓词满足或预算用尽。')],
 example='教学推演：回到上面的场景。第一步，vla_act 背后是冻结的 πRLinf 检查点，它在标准变体上很强，但对任务描述的条件很弱——直接跑容易照训练时的习惯去够原来那个目标，论文的终止帧对比图展示的正是这种情况。第二步，规划器先不碰接触：用 move_to 把末端带到黑碗上方的预接触位姿，姿态不合适就用 rotate_pitch 调，这些都由解析原语按运动学算出来，不依赖策略。第三步，规划器把一次 vla_act 调用写进 command.json，提示是抓住黑碗，附带 chunk 预算和一个抓稳并抬起的早停谓词；worker 执行完写回新的观测与日志，规划器读到夹爪已闭合、但物体位置没跟着末端走。第四步，全局记忆里正好有一条失败模型说这种情况按空抓处理、要重新定位再重试；任务记忆里则存着这一任务的原语顺序骨架，且坐标是符号化的感知查询而不是参考场景的数值，可以直接拿到新布局上重新绑定。第五步，规划器从当前 RGB-D 重新定位黑碗，用解析原语把机器人摆回可接触的构型，再调一次 vla_act；抓稳之后，搬运与释放交还给 move_to 和 release，最后按基准的完成谓词收尾，而不是凭画面上碗看着到位就宣布成功。整个过程里策略参数一次没动，变的只是它被放在什么状态下起步、以及被允许试几次；反过来说，如果某个接触阶段本身超出这个冻结策略的能力，重新摆位与重试并不能把它补上。',
 code="memory = {task: 'JSONL 原语轨迹 + 语义摘要', global: '成功规则 + 失败模型'}\nwhile not benchmark_predicate() and steps < budget:       # 部署期禁用 reset、缩短预算\n    step = plan(task_text, rgbd, proprio, memory)         # 无仿真真值，只有观测与记忆\n    if step.kind == analytic:\n        write_command(action=step.name, args=step.args)   # move_to / rotate_* / set_gripper / release\n    else:\n        write_command(action=vla_act, prompt=step.prompt,\n                      max_chunks=step.budget, stop=step.tau)  # 冻结检查点，吐 chunk 到早停谓词\n    obs, log = wait_for_worker_files()                    # 文件化 REPL：每条原语后重新观测\n    outcome = classify(obs, log)                          # 进展 / 可恢复失败 / 不可恢复失败\n    if outcome == recoverable:\n        restage_with_analytic_primitives()                # 先摆回 VLA 熟悉的预接触构型，再调一次\nmemory.update(trace_if_success, failure_model_otherwise)",
 setup='引用 v4 完整表格。LIBERO-Pro 的 8 个条件每个 10 项任务 × 10 个 seed，共 800 次；RoboCasa365 为 50 项任务共 340 次；RoboTwin C2R 为 50 项任务 × 5 seed。含参考 seed 记忆探索，因此主结果并非完全无经验的零样本。',
 headers=['相应表格的总体成功率','直接冻结策略','Harness VLA'],
 rows=[['LIBERO-Pro · 表 3','πRLinf 同检查点：50.0%','CC 82.4%；Codex 72.1%'],['RoboCasa365 · 表 4','RLDX-1：30.0%','Codex 57.1%；CC 48.6%'],['RoboTwin C2R · 表 6','LingBot-VLA：50.4%','CC 58.4%；Codex 58.0%']],
 findings='收益随任务和 Agent 后端变化。RoboCasa 的 Codex 版从 30.0% 到 57.1%，是表中可直接核对的 27.1 个百分点；但未见组合任务只有 13.8%，不能将总体 57.1% 解释为所有新长任务的表现。',
 ablation='表 5 去掉任务专属记忆，在 Goal-T / Goal-S 上分别为 79% / 31%；这揭示两类扰动难度不同。图 4 随 VLA 调用预算增加的成功曲线，支持多次局部调用有用，但还应和等预算重试对照。',
 boundary='模型来源要分三层看：接触侧是冻结的 VLA 检查点，其中 LIBERO 系列用 RLinf 发布的 π₀.₅-SFT 检查点、RoboCasa365 用官方 RLDX-1，都是现成权重，只有 RoboTwin C2R 的 LingBot-VLA 由作者后训练（训完同样冻结，直接对比的基线用的也是它）；规划侧是现成的 coding agent（Codex 或 Claude Code），不为机器人做任何训练；解析原语由运动学写死，不需要训练数据。属于作者的前提成本主要是这套 harness 工程：原语词表、文件化 REPL、两级记忆与重试策略。系统增加了感知、解析控制、Agent 推理和记忆，收益不能全算作 VLA 自身变强。主结果还走的是 few-shot 协议：每个任务先在一个参考实例上 bootstrap 并写入任务记忆，评测才在新 seed 上进行，因此不是完全无经验的零样本。v4 表 3 中 CaP-X / RATs 只覆盖 6 个条件，直接比较其总体与 Harness 的 8 条件总体会改变任务集合。',
 transfer='与 RoboHarness 共同看“策略输入状态”的问题。前者强调一组固定原语与冻结 VLA 的分工；后者强调多个异构策略的选择和交接。',
 exercise='固定策略与总步数，对比直接运行、固定次数重试、先重新定位再短时调用；把有 / 无参考记忆作为另一条轴。',
 answer='若重新定位后的收益仍高于等预算重试，才更支持状态准备的作用。记录 VLA 调用次数和解析控制步数，避免预算差异掩盖解释。',
 sources=[('原语、闭环与记忆：§2','S2'),('v4 主结果：表 3–6','S3'),('调用预算分析：图 4','S3.F4'),('参考 seed 与评测数量：附录 C','A3')])

add('phyagentos', version='v1',
 takeaway='一次控制结束只产生执行证据；是否完成任务，要由独立的语义验收决定。',
 result='RoboCasa365 target50：π₀.₅ 首次 17.6%，经过验证触发的恢复后 26.8%；应同时看到增加的尝试。',
 why='当一个系统接入很多机器人和策略，“函数返回了”会被误当成“任务完成了”。PhyAgentOS 将认知规划与物理执行解耦，用 session 描述目标、前置条件、执行边界和验收标准，让不同后端沿同一条生命周期运行。',
 scene='指令是把杯子从桌上取回来。夹爪到达位姿、闭合，控制器正常退出，函数返回了成功——可杯子还留在桌上。如果系统把“控制器退出”当成“任务完成”，这次失败就再也没有机会被发现。',
 recall_module='改的是运行时与验收判定这一层。策略一个都不训练，仿真层评测的那些 VLA 都是外部检查点，权重、任务目标与基准成功判据在实验中保持不变，观测怎么编码、动作怎么生成仍留在原策略与执行层里。换掉的是执行的组织方式与宣布成功的权力：一次请求先被编译成写明目标、前置条件、执行边界与验收标准的 session，由 WatchdogSupervisor 做兼容性预检、拼不出合法执行路径就在拿到设备访问权之前拒掉，SessionRunner 只负责这次交互的生命周期。与 Harness VLA 改调用时机不同，这篇要回答的是一次控制结束之后谁有资格判定任务是否完成——答案是独立的 SessionVerifier，而不是正常退出的控制器。',
 recall_io='输入是一句用户请求，经 ContextBuilder 补上环境状态、之前的尝试、可用能力与检索到的教训，再由 Goal Planner、Goal Graph 与 Session Compiler 编译成写进 SESSIONS.md 的 session 契约；执行期策略拿到的输入由观测契约规定——语言、RGB 或深度、机器人状态与执行历史，经 PolicyAdapter 转成模型输入。输出有两层：一层是编译好的 session 及预检物化出的 AdapterPlan 与 TargetToolManifest，前者指明需要的 PolicyAdapter、TargetAdapter 与 ActionBridge 链，后者列出本次 session 被允许调用的目标操作，它们交给 SessionRunner 去跑；另一层是 runner 跑完后交出去的东西，那是一个结构化证据包而不是成功标签，内含初始与终止观测、对应的 ENVIRONMENT.md 快照、动作—观测历史与设备侧事件或指标。失败的判定者是 SessionVerifier，依据是任务定义与验收标准对照上述证据包，其中初始观测是必需项，因为多数成功描述的是一次变化，只看终止画面证明不了杯子被移动过；它返回 success、failure 或 replan 三种裁决。判 replan 时原来那次尝试保持不可变，系统另编译一个带更新后前置条件、设备状态或策略的子 session，从当前物理状态继续走同一条预检—执行—验证的路径，父子关系与两次裁决都留在追加写的尝试记录里；修正要经再验证通过才 consolidate，成功模式连同适用条件写进 KNOWLEDGE.md，失败目标、证据、诊断原因与修正是否被裁决支持写进 LESSONS.md。',
 steps=[('把一句请求编译成带验收标准的 session', 'Agent 层做三次递进的确定：Goal Planner 把意图解析成任务目标，并标出执行期间必须保持不变的约束；Goal Graph 与 Session Compiler 把目标拆成带依赖的子任务结构，每个可执行单元编译成一个 session；SkillRuntime-Target Selector 按所需能力、观测模态、动作语义与设备约束，决定这个 session 用哪种执行方式、在哪台目标上跑。session 契约至少写明任务目标、选定的 runtime 与 target、前置条件、执行边界和验收标准，记在 SESSIONS.md 里。编译不是只看用户那句话：ContextBuilder 会把环境状态、之前的尝试、可用能力与检索到的教训一起带上。'), ('Runtime 先做预检，再进入受控执行', 'WatchdogSupervisor 是唯一的监督入口：它领走待执行的 session，先做兼容性预检，判断请求的观测模态、动作表示、策略端点、设备能力、时序约束与安全配置能否拼成一条合法执行路径，结果物化为 AdapterPlan（指明需要的 PolicyAdapter、TargetAdapter 与 ActionBridge 链）与 TargetToolManifest（列出本次 session 被允许调用的目标操作）。拼不出合法路径的 session 在拿到设备访问权之前就被拒。之后 SessionRunner 负责这次交互的生命周期；监督者只管心跳、超时与终止结果回写，不进入观测—动作回路。'), ('两条执行流，同一个证据出口', 'PolicySkillRuntime 给连续控制策略用：观测契约（语言、RGB 或深度、机器人状态、执行历史）由 PolicyAdapter 转成模型输入，模型输出转回标准动作或 action chunk，Action Runtime 负责 chunk 缓冲、控制频率、截断、中断与重规划边界，ActionBridge 做坐标转换、维度投影与限幅，TargetAdapter 再编成设备原生接口。BuiltinSkillRuntime 给工具式任务用：没有独立策略服务，Agent 通过受控句柄逐步调用 observe、reset、invoke_tool、step、query_state 这类被清单过滤过的操作。两条流的决策位置不同，但都从 session 创建、受同一个监督者管、终止于同一种结构化证据包。'), ('验收由 SessionVerifier 独立判定', '控制器正常退出不等于任务完成，因此 runner 交出去的是证据而不是成功标签。验证器读的是一整包东西：任务定义与验收标准、本次 session 保留的初始与终止观测、对应的 ENVIRONMENT.md 快照、动作—观测历史，以及设备侧的事件或指标。之所以一定要初始状态，是因为多数成功描述的是一次变化，只看终止画面证明不了杯子被移动过、柜门被打开过。它返回 success / failure / replan 三种裁决，接口背后可以是确定性谓词、任务专用评估器、多模态模型或工具辅助复核，论文固定的是证据模式与裁决含义，而不是某一个模型。'), ('replan 开新 session，验证过的才进记忆', '判 replan 时原来那次尝试保持不可变，系统另编译一个子 session，带上更新后的前置条件、设备状态或策略，父子关系与两次裁决都留在记录里；每条裁决连同验证器配置与证据引用追加写入尝试记录，后来的结果不会覆盖先前的。经验按六步闭环沉淀：执行、验证、诊断、修订、再验证，只有再验证通过之后才 consolidate。知识分两个口子存：KNOWLEDGE.md 存验证过的成功模式与其适用条件、来源 runtime 与 target；LESSONS.md 存失败目标、相关证据、诊断出的原因、试过的修正，以及这个修正后来有没有被裁决支持——只提出过、没被验证的猜想不算经验。检索时按当前目标、环境状态、设备类型与风险因素查，并连同来源与适用范围一起注入。')],
 example='教学推演：回到上面的场景。第一步，Agent 层把这句话编译成一个 session：目标写成杯子离开桌面并随末端移动，前置条件是杯子在视野内、夹爪空着，执行边界给定步数上限，验收标准据此写成可判定的形式；同时选定用连续控制策略跑，目标设备是这台机械臂。第二步，WatchdogSupervisor 领走它做预检，确认这条策略要的观测模态这台设备能提供、动作表示能经 ActionBridge 转到设备接口、安全配置齐备，生成 AdapterPlan 之后才放行。第三步，SessionRunner 进入观测—推理—动作循环，策略输出 action chunk，经限幅与坐标转换发给设备；夹爪到达指令位姿并闭合，控制器按自己的终止条件正常退出。第四步是关键：runner 交出去的是证据包，不是一个成功标签。验证器把初始观测、终止观测、ENVIRONMENT.md 的前后快照和动作历史放在一起比，发现杯子的位置关系没变——它还在桌上——于是拒绝接受这次取杯。第五步，如果证据支持换个方式继续，裁决是 replan：第一次尝试原样留在记录里，系统另编译一个子 session，改掉接近方向或前置条件后从当前物理状态继续（论文的仿真评测正是这样在不重置环境的前提下恢复的）；只有这次修正也通过了验证，对应的教训才写进 LESSONS.md，成功模式才写进 KNOWLEDGE.md。这套机制把指令执行完了和世界变成了想要的样子分开，但它判得准不准，取决于验收标准是否写成可判定的形式、以及证据包里有没有能支持这个判断的那一项。',
 code='session = compile(goal, preconditions, limits, acceptance, runtime, target)  # 写入 SESSIONS.md\nplan = watchdog.preflight(session)          # 模态 / 动作表示 / 端点 / 安全，拼不通就拒\nif plan is None: reject(session)\nevidence = runner.execute(session, plan)    # 高频控制留在执行层，返回证据而非成功标签\n#   evidence = 初始观测 + 终止观测 + ENVIRONMENT 快照 + 动作观测历史 + 设备事件\nverdict = verifier(goal_and_acceptance, s_0, s_T, trace, history)\nattempts.append((verdict, evidence_ref, verifier_config))   # 追加写，旧裁决不被覆盖\nif verdict == success:\n    knowledge.add(pattern, applicable_conditions, provenance)\nelif verdict == replan:\n    child = compile(revised_goal, from_state=current_physical_state, parent=session)\n    # 父尝试不可变，子 session 重新走同一条 Watchdog - Runner - Verifier 路径\nelse:\n    lesson = diagnose(evidence)             # 修正被后续裁决支持，才写进 LESSONS',
 setup='论文涉及多个仿真平台与真实硬件接入。这里聚焦机器人操控的量化表：LIBERO、CALVIN ABC→D 和 RoboCasa365 target50。表中的 Final 明确表示验证器触发重试 / 恢复后的结果。',
 headers=['固定策略与任务集','首次结果','Final 结果'],
 rows=[['LIBERO · π₀.₅ 总成功率','97.0%','97.8%'],['CALVIN · π₀.₅ 五任务链成功率','85.3%','89.4%'],['RoboCasa target50 · π₀.₅','17.6%','26.8%'],['RoboCasa target50 · RLDX-1','35.6%','42.8%']],
 findings='RoboCasa target50 的 250 次评估中，π₀.₅ 从 44 个成功增加到 67 个，恢复了 23 个 episode。相比之下，高起点的 LIBERO 只提升 0.8 个百分点。不同难度与可恢复失败比例决定了额外机制的收益。',
 ablation='First / Final 是观察恢复效果的对照，但同时改变了尝试过程，不能单独证明“语义记忆”或“OS 架构”的贡献。若要研究这两者，应补上等重试预算的无记忆 / 无语义验收对照。',
 boundary='模型来源全是现成的：PhyAgentOS 不训练策略，仿真层评测的 OpenVLA、π₀、π₀.₅、X-VLA、RLDX-1、WorldDreamer 都是外部检查点，权重、任务目标与基准成功判据在实验中保持不变；游戏层则明确接了 qwen3.5-plus 做规划、qwen3-vl-flash 做视觉、STEVE-1 把子目标翻成键鼠动作、deepseek-v4-flash 做纯文本推理。论文真正提供的是协议、监督、验收与记忆这套系统层。读架构时还要注意两处自述：Goal Graph 与 Session Compiler 的 DAG 级分解是架构里描述、但尚未完全实现的部分；协议层目前靠轮询文件实现，延迟与轮询间隔成正比。接入多种设备证明接口覆盖面，不等于每种设备都经过同等强度的端到端测试——真机部分本身也以安全验证为主，而非大规模任务完成统计。本文 target50 的划分与 Harness VLA 的 RoboCasa365 三个 split 不同，不能直接横比两篇总体数值。',
 transfer='把 Inner Monologue 的“语言反馈”升级为可审计的执行与验收协议，是理解本文的好入口；要继续追问记忆更新是否真的改变后续行为。',
 exercise='给已有 Agent 工具增加契约、执行状态和验收状态三个字段。模拟“正常退出但目标未满足”，检查是否错误推进下游任务。',
 answer='记录首次成功、最终成功、平均尝试次数、误验收率。最终成功高却误验收多，可能只是系统自己宣布成功；外部独立判据必不可少。',
 sources=[('架构与 session：§3','S3'),('语义验收与经验：§4','S4'),('机器人量化结果：表 4–6','S5')])

add('roboharness', version='v2',
 takeaway='选对下一项策略还不够：上一项策略留下的状态，必须让下一项接得住。',
 result='LIBERO-LoHo：进度 97.5%、整任务成功 95.2%；真实桥搭建在重新藏起积木的扰动下从 86.7% 降至 66.7%。',
 why='不同策略可以各自很强，但训练分布和动作接口不同，直接串联会在交接处失败。RoboHarness 将异构策略注册为可调用技能，并用理解、记忆和经验更新辅助选择。核心 Memory Bridge 处理策略之间的状态分布不匹配。',
 scene='真机搭桥任务，指令是搭一座短桥，需要的积木里有一两块先被藏在柜子里。开柜门这类接触操作适合 VLA，按结构精确摆放积木适合 TAMP，两条策略各自都强。但把它们直接串起来，上一条留下的手臂构型可能正好是下一条难以规划的位置。',
 recall_module='改的是异构策略之间的交接状态，而不是任何一条策略的能力。每条策略保留自己的原生实现与输入输出，不要求统一动作表示，也不联合重训；理解技能里的编码器全部冻结、直接取现成权重；编排与自我进化交给现成的 coding agent。被换掉的是策略之间的那段空白：用 policy card 把异构策略登记成可比较、可调用的技能，用链式节点的记忆库存成功轨迹并做文本加视觉的两级检索，再由 Memory Bridge 在启动下一条策略之前，先把机器人从上一条策略留下的构型推进到下一条策略的支撑区。运行时真正被训练的只有 Memory Bridge 现场拟合的那个轻量进度估计器。',
 recall_io='输入是任务指令、当前观测与机器人状态（关节构型与末端位姿）、各条策略的 policy card（类型、能力、接口要求、约束、假设、训练过哪些任务与历史执行统计，必要时还可直接读策略的实现代码），以及理解技能产出的结构化证据：滑动窗口里物体位姿的均值与方差、冻结视觉编码器算出并加权求和的检索键、语义编码器对指令与策略语言描述的比对、由曝光与拉普拉斯响应方差等指标合成的输入质量分，还有借 Memory Bridge 重建的空间分布给当前位姿与构型打的兼容性评分；检索记忆时先用文本嵌入取一批相关节点，再在这批节点里用视觉嵌入收窄。输出是一份子任务划分与策略派发，以及每次交接时的一个交接目标状态与到达它的过渡轨迹——交接目标取在支撑域与运动规划可达集的交集里，是进度分减去运动代价之后最大且进度分非负的那个状态，过渡轨迹由现成运动规划器生成，走完才启动下一条策略，这段交接连同指令、观测与状态轨迹一并写回记忆供日后检索复用。失败在两个位置被处理：交接时的支撑域本身就是一道拒绝，只有与展开状态距离在阈值内的候选才算有效交接点，够不着的状态不会被当成交接目标；真正的更新则不由单次 rollout 触发，而是遇到持续性的执行失败时，由记忆技能取出相关失败历史与执行证据交给 coding agent，由它决定改编排代码修接口与路由、沿离散网格把某个连续参数调高或调低、接策略适配方法作用于 TAMP 一侧，或把这种条件下这条策略不可靠改写回 policy card；改动要经后续执行验证才保留，保留下来的跨评测 episode 延续。',
 steps=[('异构策略包成带 policy card 的可调用技能', '每条策略保留自己的原生实现与输入输出，不要求统一动作表示，也不联合重训；外面套一张 policy card，记录类型、能力、接口要求、约束、假设、训练过哪些任务，以及历史执行统计。coding agent（实现上是 Codex 搭 GPT-5.5）据此在规划层比较与组合不同家族的策略，必要时还能直接读策略的实现代码来判断兼容性。仿真里挂的三条策略是：Physical Intelligence 官方的 pi05_libero 检查点、用 RLinf 在 LIBERO-90 上做过 GRPO 后训练的 OpenVLA-OFT 检查点，以及作者自己实现的 TAMP 规划器（PDDL 描述符号层，Fast-Forward 求解，PDDLStream 负责抓取位姿等连续量的采样）。'), ('理解技能把观测变成能与能力边界比较的证据', '五类理解技能各算一件事：不确定性评估在滑动窗口里统计物体位姿的均值与方差；视觉上下文用两个冻结编码器（SigLIP2 与 DINOv2）算嵌入、与记忆中该策略的训练轨迹比，两者相似度加权求和作为检索键；语义上下文用冻结的 BGE 编码器比对指令与各策略的语言描述；输入质量用曝光、拉普拉斯响应方差、对比度与图像熵这些常规图像处理指标打一个综合分；状态—策略兼容性则直接借 Memory Bridge 重建出的空间分布，给当前末端位姿与关节构型评分。coding agent 按需调用这些技能，再综合它们的结构化输出来拆任务、派策略。'), ('记忆按链式节点存轨迹，检索分两级', '记忆库里每条成功 rollout 是一串按时间链接的节点，节点存当时的视觉观测、任务提示、机器人状态（关节构型与末端位姿）以及对应的文本与视觉嵌入；链接关系让系统能从任一被检中的节点往前后展开执行上下文。检索是分层的：先用文本嵌入的余弦相似度取一批最相关的节点，再在这批节点里用视觉嵌入收窄。除了轨迹，系统另外维护跨任务的策略执行统计，作为能力估计与派发的经验依据；两者都在每次 rollout 之后更新。'), ('Memory Bridge 把状态推进下一条策略的支撑区', '交接分三步。先按下一个子任务与当前观测检索出锚点节点，沿各自轨迹前后各展开若干步，按时间偏移给每个节点赋一个进度分（锚点记零），用这些状态—分数对训一个轻量进度估计器，实验里用的是成对排序 SVM；同时用这批展开状态定义一个支撑域，只有与它们距离在阈值内的状态才算有效交接点。然后在支撑域内给候选状态打分，正分表示比锚点更靠前的进度。最后在支撑域与运动规划可达集的交集里，取进度分减去运动代价之后最大、且进度分非负的状态作为交接目标，调现成的运动规划策略生成过渡轨迹，再启动下一条策略。这段交接连同指令、观测与状态轨迹一并写回记忆，以后同类交接可以直接检索复用。'), ('进化技能只在反复失败时才动', '四类更新：策略适配接现成方法（SIMPACT 按执行反馈调抓取位姿，PDDLLM 在线学新的逻辑表示，二者都作用于 TAMP 一侧）；harness 精炼由 coding agent 改编排代码，修接口、改路由与协调逻辑；参数调优把连续参数离散成网格，agent 只预测调高、调低或保持这个方向，由单独的模块落成具体值；元数据更新据新的成败改写 policy card 的能力边界。触发条件不是每次 rollout，而是遇到持续性的执行失败；此时记忆技能取出相关的失败历史与执行证据交给 coding agent，由它决定用哪一种或哪几种。改动要经后续执行验证才保留，保留下来的跨评测 episode 延续。')],
 example='教学推演：回到上面的场景。第一步，系统挂着两条策略：TAMP 负责有几何约束的取放与装配，π₀.₅ 负责开关柜门这类 TAMP 难建模的接触操作；两张 policy card 写明各自的能力、接口与历史统计，coding agent 读卡决定谁做哪一段。第二步，理解技能先把场景说清楚：视觉与语义上下文把当前观测、当前子任务分别和两条策略的训练轨迹与语言描述比，输入质量确认画面够清楚，不确定性评估看几帧里积木位姿稳不稳；结论是开柜门这一段落在 VLA 一侧，把积木按结构摆好落在 TAMP 一侧。第三步，在把开柜门交给 π₀.₅ 之前，先按文本检索出记忆里与这句子任务最相关的节点，再在这批节点里按视觉相似度收窄，拿到这条策略成功做过同类动作时的轨迹片段作为参照。第四步是交接：VLA 开完门后手臂停在门边，这个构型对 TAMP 的取放未必好规划。Memory Bridge 按下一个子任务检索 TAMP 的成功轨迹，沿轨迹前后展开出一批机器人状态、按时间偏移赋进度分，据此拟合局部的进度估计器并圈出支撑域，再在支撑域与运动规划可达集里挑一个进度分非负、运动代价又不高的状态，用现成运动规划器过去，然后才启动 TAMP；这段过渡轨迹同样写回记忆。第五步，如果这类交接反复失败，进化技能才被触发：coding agent 拿到失败历史后，可能改编排代码、沿网格把检索设置或交接接受阈值调一格，或者把这种条件下这条策略不可靠写回 policy card；改动要在后续执行中验证过才留下。要记住这套机制调度的是已有能力：如果两条策略都不会某一步，换谁去接都补不上。',
 code='plan, assign = agent.decompose(task, understanding_skills(obs), policy_cards)\nfor g, pi_next in zip(plan, assign):\n    anchors = retrieve(memory, text=g, then_visual=obs)     # 先文本 TopK，再在其中视觉 TopK\n    if not compatible(robot_state, pi_next, anchors):\n        nodes = expand(anchors, horizon=l)                  # 沿链式轨迹前后展开\n        f = fit_progress(nodes, y=offset * dt)              # 成对排序估计器，锚点记零分\n        region = support(nodes, eps)                        # 只有近邻状态算有效交接点\n        s_star = argmax(f(s) - lam * motion_cost(state, s)) # s 在支撑域 ∩ 可达集，且 f(s) >= 0\n        execute(motion_planner(state, s_star))              # 现成规划器生成过渡轨迹\n    obs, ok = execute(pi_next, g)                           # 策略保留原生接口，不联合重训\n    memory.append(nodes_of(rollout))                        # 交接轨迹同样写回记忆\n    if persistent_failure(ok):\n        agent.evolve(retrieved_failures)                    # 改编排 / 调参 / 改 policy card，验证后保留',
 setup='论文含 LIBERO、LIBERO-Plus、LIBERO-LoHo、500 项自定义长程仿真任务，以及 135 次真实实验。真实平台组合 TAMP 与 π₀.₅；每种结构和扰动条件各 15 次，部分积木先藏在柜内。',
 headers=['表 2 · LIBERO-LoHo','平均进度','整任务成功率'],
 rows=[['π₀.₅','55.3%','6.4%'],['LLM-guided π₀.₅','66.8%','26.8%'],['H-WM-π₀.₅','84.9%','64.8%'],['RoboHarness','97.5%','95.2%']],
 findings='只看进度会低估交接失败：π₀.₅ 能完成部分步骤，最终却只有 6.4% 成功。真实桥任务为 86.7%，重新隐藏积木后为 66.7%，增加探索与重规划会撞上时间上限；这比只记 95.2% 更接近部署问题。',
 ablation='图 4 在 500 项自定义任务上拆分理解、经验更新和 Memory Bridge。去掉 Bridge 仍保留较高进度，却更难完成整任务，符合“选对步骤但交接不稳”的机制解释。应将这组消融与公开基准结果分开。',
 boundary='模型来源基本都是现成的：两条 VLA 是公开检查点（Physical Intelligence 的 pi05_libero，以及用 RLinf 在 LIBERO-90 上做过 GRPO 后训练的 OpenVLA-OFT），编排与自我进化用的是 Codex 搭 GPT-5.5，理解技能里的编码器（SigLIP2、DINOv2、BGE）全部冻结、直接从 Hugging Face 取；作者自己实现的是 TAMP 规划器与整套 harness。运行时真正被训练的只有一样东西：Memory Bridge 每次交接现场用检索到的状态—进度对拟合的轻量进度估计器，它的可信度完全取决于检索到的经验是否覆盖当前状态。因此 Memory Bridge 依赖已有执行经验，新策略或记忆稀疏时边界估计可能不可靠。跨策略编排不能创造技能库中完全没有的能力，实机小样本也不意味着普遍可靠。',
 transfer='结合 Harness VLA 形成一个共同研究问题：如何判断策略现在是否处于可工作的状态，以及怎样低成本地把它带回这个状态？',
 exercise='用网站实验章节的状态交接小实验起步，再在仿真里固定两个策略，比较直接串联、重试、显式过渡与真值过渡。',
 answer='把交接前后状态偏差、局部成功、任务进度和整链成功一起画出来。若过渡估计噪声很大，Bridge 也可能有负作用，这正是值得研究的边界。',
 sources=[('记忆与 Bridge：§4.2','S4.SS2'),('公开长程结果：表 2','S5.T2'),('组件消融：§7 / 图 4','S7'),('135 次实机实验：§8','S8')])

add('emerge', version='v2',
 takeaway='编排有两个平面：谁去执行，和谁去看证据；这一篇拆的是后者。',
 result='LIBERO-Plus 表 2：完整系统 93.9%，同一 Cosmos Policy 后端运行 82.2%；另加五路 Agent 侧相机。',
 why='如果你写过多智能体的 tool-calling 系统，这篇值得学的是上下文归属。执行里最占地方的不是计划，而是每帧检测结果与工具调用的中间输出：它们对判断“刚才那一下做成没有”必不可少，对决定“下一步做什么”大多无关。论文把两类需求拆进不同上下文，之间只传结构化结论。',
 scene='LIBERO-Plus 的一次 rollout：背景、相机位置与指令说法都被换过，冻结策略照训练习惯伸过去，抓空了。要接住它，系统得看清桌上现在有什么、判断刚才那下算不算做成、还得记着做到第几步。朴素做法是把这些全塞进同一个上下文，很快填满，真正用得上的只有一小部分。',
 recall_module='改的是编排系统内部的信息分工：感知、验证、监控与记忆整理从高层规划器的上下文里被搬出去，放进各自隔离的 Sub Agent 上下文，只把结构化结论交回来。没改执行侧——π₀.₅ 与 Cosmos Policy 都用官方检查点、全程不额外微调，动作空间与基准自己的成功判据也没动；规划器是现成的闭源 Codex，不为机器人做任何训练。运行时被改写的只有外部文本状态（PLAN.md、HISTORY.md、MEMORY.md 与 Branch Stack），论文明确说这一步不更新任何模型权重，也不改 Skill 的实现。',
 recall_io='输入分两路进两个地方：原始多模态观测（LIBERO 系列除原环境视角外另加五路固定相机，仅供 Agent 侧使用，不进 WAM 与 VLA 的观测）只进 Sub Agent 的隔离上下文；Main Agent 的活动上下文里只有任务指令、当前子目标、PLAN.md 的计划状态、Branch Stack 栈顶、相关记忆、最近的结构化结果，以及每个可调接口的一行签名。输出是一次编排决策——委派某个 Sub Agent、调用某个 Skill、更新任务状态、发起恢复、修订计划或终止；物理动作经 Embodied Action API 落到规则运动原语或 VLA 策略上。一次失败的判定者是 Verification Sub Agent 或 Monitor Sub Agent，依据是该子目标三元组里写死的 Criterion 与执行后的观测（监控信号取决于部署的传感器与执行后端），它回一份含观测证据、失败类型、状态变化与可推断原因的结构化报告。Main Agent 据此写一段文本诊断，把一个局部恢复子目标压进 Branch Stack，栈顶先做、做成就弹出并回到被打断的计划；论文说恢复子目标连续失败到预设次数（举例两次）之后才换一个恢复子目标或转入全局重规划，但 v2 在这一句上保留了未合并的修订痕迹，两种写法并存，统一的次数与预算上限论文没有给出。',
 steps=[('主 Agent 的上下文里只放摘要', '活动上下文 C_t 装的是任务指令、当前子目标、计划状态、Branch Stack 栈顶、任务相关记忆、最近的结构化结果，以及各 Skill 的紧凑签名；原始多模态观测与完整执行轨迹一律留在外面。控制上下文增长靠三件事：把稳定约束与本体配置和动态任务状态分开、只在相关时插入；每个可调接口按 K=⟨I_meta, Θ_param, Φ_pre, Ψ_post⟩ 注册，上下文里先只给一行能力描述 I_meta，选中之后才取参数、前置与后置条件；证据密集的活全部委派出去。规划器实现上是闭源的 Codex（论文记作 codex-5.6-sol），跨基准共享同一套基础动作原语，只按基准换一份 AGENTS.md 提供高层指令。'), ('子目标写成三元组，感知与验证各自在隔离上下文里做', 'Main Agent 把指令拆成有序子目标 g_i=⟨Target, Change, Criterion⟩ 写进 PLAN.md：目标实体、意图状态变化、以及判定完成的条件。Sub Agent 以非阻塞后台 worker 的形式跑，建实例时只拿到当前子目标、任务相关的空间范围与被许可的工具原语，处理完只回结构化结果，中间观测、提示与工具轨迹留在自己的上下文里。Perception Sub Agent 走 Scene Graph API 与外部视觉接口，接的是现成模型——SAM3 做开放词表实例分割（用自然语言提示），VGGT 出三维几何先验；作者报告 SAM3 在结构清晰目标上的分割 IoU 如 open basket 0.971、bottle with green cap 0.948、blue soup can 0.946，但在遮挡、光照变化或属性含糊的目标上会漏检，因此把 SAM3 的候选掩码与 VGGT 的几何先验融合。Verification Sub Agent 执行前查前置条件、执行后拿观测比 Criterion，回一个完成判定加支撑证据。'), ('三类 Skill 按功能登记，同一个模型可以占两个位置', 'Skill 的分类依据是它在决策循环里干什么，而不是底层架构：Operational 出可执行动作，Imagination 预测候选结果但不改变环境，Evaluation 评估可行性、进度与判据是否满足。LIBERO 系列的执行后端二选一，VLA 是 openpi 的 pi05_LIBERO，WAM 是 nvidia 的 Cosmos-Policy-LIBERO-Predict2-2B，两条都用官方发布的检查点、不额外微调。Cosmos Policy 同时占两个位置：作为 Operational Skill 出动作块，作为 Imagination Skill 预测对应的未来帧；Evaluation Skill 给预测出的末帧对着子目标判据打一个标量分，贪心取最高分那条去执行，只执行首段动作就重新规划。作者报告的具体设置是每个决策步生成 M=5 条候选、每条 horizon H=16、温度 0.1，这一环节带来约 1.2 秒的额外延迟；Evaluation Skill 论文只写成“一个轻量视觉语言模型”，型号没有给出。'), ('失败先压成局部恢复子目标，压不动才动全局计划', 'Monitor 或 Verification Sub Agent 发现失败时，回一份含观测证据、失败类型、相关状态变化与可推断原因的结构化报告；Main Agent 据此写一段文本诊断，论文说这一步借鉴 Reflexion 的语言反思机制。诊断之后不是直接重规划，而是构造一个局部恢复子目标压进 Branch Stack，栈顶那个先做，做成就弹出、执行回到被打断的计划。恢复子目标连续失败到预设次数（论文举例两次）之后，才换一个恢复子目标或转入全局重规划——v2 的 §2.1.2 在这一句上保留了未合并的修订文本，两种写法同时存在，论文没有给出统一的重试次数与总预算上限。'), ('记忆是外部文本，按 token 触发整理，每集清零', '论文列了四份任务状态加一个恢复栈：活动上下文窗口当工作记忆，PLAN.md 存子目标序列与完成状态，HISTORY.md 只追加地记时间序摘要，MEMORY.md 是可以被后来证据改写的信念集合，Branch Stack 单独存临时恢复子目标。活动上下文触到 token 容量时由 Memory Integration Agent 整理：被逐出的时间序摘要追加进 HISTORY.md，相关事实并进 MEMORY.md 并改写过时条目，再从指令、PLAN.md 状态、Branch Stack、相关事实与最近的 Sub-Agent 结果重建下一个活动上下文，HISTORY.md 不会整份自动塞回。论文强调这一步只改外部文本、不更新模型权重或 Skill 实现，四份状态在下一集开始前全部重置，因此评测里不存在跨集在线适应。需要注意 §3.5.1 的案例分析换了一套说法，讲的是 PLAN.md 加 ENVIRONMENT.md 的三层记忆，ENVIRONMENT.md 由环境 watchdog 在每次物理动作后刷新、Agent 必须强制重读；两处描述并不完全一致。')],
 example='教学推演：回到上面的场景。第一步，Main Agent 的上下文里并没有那几路相机的画面，只有指令、PLAN.md 的当前状态、Branch Stack 栈顶和几行 Skill 签名；它要用某个接口时才把这个接口的参数、前置与后置条件取进来，别的接口仍旧只占一行描述。第二步，它把这一段写成子目标三元组——目标是那只碗、变化是被抓起并移到盘上、判据写成可以对着观测判定的条件——再把感知委派出去：Perception Sub Agent 在自己的隔离上下文里用 SAM3 按“黑碗”这样的语言提示取实例掩码，配 VGGT 的几何先验定位，回来的只是坐标与空间关系，不是整条检测轨迹。第三步，执行前先想一遍：Cosmos Policy 作为 Imagination Skill 出 5 条候选动作块、各预测 16 步的未来帧，Evaluation Skill 给每条的预测末帧按判据打分，贪心选最高的那条交给 Operational Skill 执行，只走首段就回头重新决策。第四步，动作走完，Verification Sub Agent 拿新观测比判据，发现碗并没有离开桌面，于是回一份失败报告；Main Agent 写下文本诊断，把一个局部恢复子目标压进 Branch Stack——比如先退开重新对位——栈顶做成之后弹出，回到原来那条计划继续，而不是整段重规划。第五步，这一轮的摘要在活动上下文触到 token 上限时被 Memory Integration Agent 整理：时间序摘要追加进 HISTORY.md，“这只碗此刻在托盘右侧”这类事实并进 MEMORY.md 并覆盖掉过时的旧值，下一个活动上下文从指令、计划状态、Branch Stack 与这些事实重新拼出来。这套机制没有做到的是：判定“做成没有”的那个 Sub Agent 与给出计划的是同一个规划器模型、只是换了上下文，论文没有提供独立于它的判据来估计自报验收的误接受率；四份文本状态每集清零，所以这里的“记忆”只在一集之内起作用，不构成跨任务的经验积累；执行后端的能力边界也一点没变，想象与评估只能在它出的候选里挑，挑不出这条策略本来就做不到的动作。',
 code="plan = decompose(task)                          # 子目标三元组 ⟨Target, Change, Criterion⟩ → PLAN.md\nwhile plan.unfinished():\n    g = branch_stack.top() or plan.next()       # 恢复子目标优先于主计划\n    Z_p = sub_agent('perception', raw_obs, g)   # 隔离上下文：SAM3 + VGGT，只回结构化证据\n    cands = imagination(Z_p, g, M=5, H=16)      # Cosmos Policy 预测候选动作块的未来帧\n    a = argmax(evaluation(cands, g.criterion))  # 轻量 VLM 打分，温度 0.1，贪心选\n    obs = operational(a)                        # π₀.₅ 或 Cosmos Policy，官方检查点、不微调\n    Z_v = sub_agent('verification', obs, g)     # 判定者是它，依据是 g.criterion\n    if Z_v.ok: plan.mark_done(g); branch_stack.pop_if(g)\n    elif g.retries < K:                         # K 论文举例为 2，未给统一上限\n        branch_stack.push(recovery(main_agent.diagnose(Z_v.report)))\n    else:\n        plan = replan(Z_v.report)               # 局部恢复补不上才动全局计划\n    if tokens(C) >= cap: C = memory_agent.consolidate(C)   # 写 HISTORY/MEMORY，权重不动",
 setup='作者在 LIBERO、LIBERO-Plus、LIBERO-Pro 与双臂 RoboDojo 上评测，规划器全程是闭源 Codex。协议有两处改动：LIBERO 系列另加五路只供 Agent 侧使用的相机，不进策略观测；每集步数上限被放宽，只写“适度增加”。真机为三层纸杯金字塔。',
 headers=['作者报告的总体（对应表格）', '执行后端直接运行', 'EMERGE-Policy'],
 rows=[['标准 LIBERO 四套件平均 · 表 1', 'Cosmos Policy 98.5%', 'w/ WM 99.2%'], ['标准 LIBERO 四套件平均 · 表 1', 'π₀.₅ 96.8%', 'w/o WM 98.8%'], ['LIBERO-Plus 七类扰动平均 · 表 2', 'Cosmos Policy 82.2%', 'w/ WM 93.9%（同表 RoboHarness 93.2%）'], ['LIBERO-Pro 隐式指令 Total(S) · 表 3', 'π₀.₅ 20.8%', '77.8%（同表 HarnessVLA 68.8%）'], ['RoboDojo 平均 分数 / 成功率 · 表 5', 'π₀.₅ 11.41 / 6.91%', '20.46 / 13.54%']],
 findings='标准 LIBERO 已贴天花板，+2.0 与 +0.7 个百分点须连同未报告的试验次数看。差距出现在扰动与隐式指令（表 3 Spat-S 95.7% 对 20.0%），但这侧多了五路相机与放宽步数，作者也说它不能分离角色分工的贡献。表 5 易读反：平均分数 20.46 最高，成功率 13.54% 低于 GalaxeaVLA 的 14.88%。',
 ablation='表 4 逐项屏蔽，参照 93.9%：去 Evaluation Skill 85.6%，去 Imagination 88.3%，去两类 Sub Agent 91.2%。w/o WM 在 Layout 反而 +2.6；w/o Sub 仍保留 Perception Sub Agent，不是“没有角色分工”的对照。',
 boundary='模型来源是混合的：执行侧是现成检查点（openpi 的 pi05_LIBERO 与 nvidia 的 Cosmos-Policy-LIBERO-Predict2-2B，论文明确不额外微调），感知侧接 SAM3 与 VGGT，规划器是闭源 Codex，同样不为机器人训练；作者自己训练的模块论文没有报告任何一个，唯一可能的位置是 Evaluation Skill，但只写成“一个轻量视觉语言模型”，没有型号，也没有说是否微调。所以前提成本不在训练，而在工程与预算：角色化 Sub Agent 与隔离上下文、三类 Skill 的接口、Branch Stack 与四份外部记忆文件、每个基准一份 AGENTS.md，以及那五路额外相机、放宽的步数上限和想象—评估带来的每步约 1.2 秒延迟。另有几处论文没写清：恢复重试只说“预设次数（例如两次）”，步数上限只说“适度增加”，试验次数与真机硬件配置都没有给出。最后，外部记忆每集重置，论文强调不存在跨集在线适应，这里的记忆指一集之内的状态保持。',
 transfer='与 PhyAgentOS 并读：都不把控制器返回当成任务完成，但那边判定者独立于规划器。与 Harness VLA、RoboHarness 相比：前者编排能力，本篇编排证据。',
 exercise='固定执行后端、相机路数、步数上限与工具集合，只比较三种编排：单 Agent 全部直读、单 Agent 加摘要、完整角色分工。',
 answer='有解释力的不是“分工更好”，而是收益随上下文压力如何变化：若单 Agent 加一层摘要就追平，增益来自信息量而非角色划分。同时记 token 与物理步数。',
 sources=[('方法总览：§2', 'S2'), ('子 Agent 与技能编排：§2.2–2.3', 'S2.SS2'), ('基准结果：§3.2 / 表 1–3', 'S3.SS2'), ('消融：§3.4 / 表 4', 'S3.SS4')])
